window.APP_DATA={"meta":{"title":"逻辑填空 · 易混词语辨析闭环","source":"《逻辑填空1000高频词闭环突破》讲义","words":1122,"groups":156},"themes":[{"id":"a-speed","name":"速度与变化"},{"id":"b-attitude","name":"态度判断与评价"},{"id":"c-extent","name":"程度与差距"},{"id":"d-relation","name":"关系与配合"},{"id":"e-cause","name":"因果与形势"},{"id":"f-light","name":"难度与执行"},{"id":"g-express","name":"表达与认知"},{"id":"h-quality","name":"性质与状态"},{"id":"i-verb","name":"实词动词辨析"}],"groups":[{"id":"g001","theme":"d-relation","label":"融合／结合","words":["融合","结合"],"rows":[{"w":"融合","f":31,"def":"（动词）几种不同的事物合成一体。","key":"不同事物彼此交融、你我不分，最终合为一体（多指文化、产业、技术等渐变式交融）","dim":"交融程度","egs":["歌剧是一个由五种艺术融合为一体的综合物。","党的十八大以来，习近平总书记三次考察福建，多次提到“两岸融合发展”。"],"rel":""},{"w":"结合","f":7,"def":"1．（动词、名词）凝结在一起，组成整体。泛指人或事物之间发生密切联系。2．（动词）特指结为夫妻。","key":"彼此连接组成一个整体，也指建立密切联系（可指婚配），强调“联”而不强调“化”","dim":"侧重联系","egs":["一些学校通过“校社合作”创新人才培养模式，走出非遗传承与高校教育相结合的新路子，为濒临失传的传统技艺注入新的生机。","在历史的长河中，婚姻始终承担着特殊的使命。它不仅代表着两个人的结合，更象征着生命的延续，以及传宗接代的庄严承诺。"],"rel":""}]},{"id":"g002","theme":"i-verb","label":"推动／推进","words":["推动","推进"],"rows":[{"w":"推动","f":29,"def":"1．（动词）使事物前进。2．（动词）使工作展开。","key":"使事物前进、使工作展开，强调外部施力，宾语常为“发展、进步”","dim":"施力主体","egs":["中国共产党成为推动中国历史前进、领导中国人民前进的坚强力量。","推动直播经济健康持续发展，必须加快完善产业生态圈。"],"rel":"推动力"},{"w":"推进","f":8,"def":"1．（动词、名词）推动而使之前进。2．（动词）递次前进。","key":"推动并使之前进，强调有步骤、逐层、递次向前（“推进+进程/步伐/工作”）","dim":"递次推进","egs":["正确理解和大力推进中国式现代化。","中国式现代化的成功推进和拓展，推动中华民族伟大复兴进入不可逆转的历史进程。"],"rel":"推进器"}]},{"id":"g003","theme":"b-attitude","label":"毋庸置疑／质疑等5词","words":["毋庸置疑","质疑","毋庸置喙","毋庸赘述","毋庸讳言"],"rows":[{"w":"毋庸置疑","f":29,"def":"毋：无。庸：用。置疑：怀疑。用不着怀疑，形容事实或道理非常清楚充分。","key":"用不着怀疑——事实、道理确凿可信","dim":"肯定程度","egs":["中国对世界经济的贡献是毋庸置疑的。2010 年中国对世界经济增长的贡献将达到 1/3，远远超过美国。","毋庸置疑，改革从来都不是一帆风顺的，也不是一劳永逸的。"],"rel":"不容置疑、毋容置疑、置疑：（动词）怀疑（多用于否定式）。"},{"w":"质疑","f":15,"def":"（动词、名词）提出疑问。","key":"提出疑问（中性词，不等于否定）","dim":"中性疑问","egs":["人们不仅仅是对玩具本身产生了讨论，更对媒体的报道方式产生了质疑。","“接诉即办”刚提出时，有的基层干部表示压力太大、干不了，有的基层干部质疑是一句口号、走形式。"],"rel":""},{"w":"毋庸置喙","f":4,"def":"毋庸：无须，不必。置：放。喙：嘴。指不需要别人插嘴，不需要多话。","key":"不必别人插嘴、不必多话——强调不该由外人议论","dim":"插话权限","egs":["巴西的互联网享有很高的自由度，西方国家对此毋庸置喙。","以何种方式解决台湾问题、实现国家统一，是中国人自己的事，不容他人置喙。"],"rel":"不容置喙、置喙"},{"w":"毋庸赘述","f":4,"def":"赘：多余的。述：讲述。意为不需要啰唆地陈述，用不着多说。","key":"用不着啰嗦陈述——事情已明，不必重复","dim":"篇幅冗长","egs":["“宁让电等发展，不让发展等电”，电力供应对于经济发展与社会运转的重要性毋庸赘述。","丝路旅游的丰富内涵与迷人魅力已无庸赘述，它的广阔发展前景也为沿线各国所公认。"],"rel":"毋庸赘言、不容赘述、赘述"},{"w":"毋庸讳言","f":3,"def":"用不着忌讳，可以直说。","key":"用不着忌讳，可以直说（多用于引出不光彩的事实）","dim":"直说避讳","egs":["毋庸讳言，当前历史学发展面临着一种尴尬局面。","毋庸讳言，今天的高校人才培养中，依然要解决“过窄的专业教育、过强的功利主义、过弱的人文精神”之问题。"],"rel":""}]},{"id":"g004","theme":"c-extent","label":"大相径庭／背道而驰等7词","words":["大相径庭","背道而驰","截然不同","相去甚远","迥然不同","天差地别","云泥之别"],"rows":[{"w":"大相径庭","f":28,"def":"比喻彼此相差很远，大不相同。偏正式结构，在句中一般作谓语或定语。","key":"彼此相差很远、大不相同，可与“大、悬殊”呼应，也可反用“不”","dim":"程度+书面","egs":["原来，这篇假冒的文章，虽然表面上看起来和人民网的正版页面无异，但仔细一瞧，网址却大相径庭。","许多市民感觉公园环境与以往大相径庭。"],"rel":""},{"w":"背道而驰","f":18,"def":"背：逆着。道：道路。向着相反的道路奔驰。比喻彼此方向目标完全相反。也比喻背离正确的目标，朝相反的方向走。在句中一般作谓语，有时作定语。","key":"朝相反方向跑，强调方向、目标相反或背离正确方向（贬义）","dim":"方向相反","egs":["以零售和餐饮经营的服务业都应该向日本学，正如日本餐饮业的赚钱大王西腾公司，其经营术与一般餐饮企业背道而驰，但却成为日本餐饮界当之无愧的赚钱大王。","享乐主义与人民群众的根本利益是相悖的，与党的宗旨是背道而驰的，严重败坏党风和社会风气。"],"rel":""},{"w":"截然不同","f":12,"def":"事物之间，界限分明，全然不一样。（主语需二者或以上）","key":"界限分明、判然两样，事物或态度非此即彼，主语须为两者或以上","dim":"界限分明","egs":["同样是 400 年前的剧本，两场演出截然不同的舞台风格，引发了观众的热议。","头部企业加速奔跑、越走越远，而中型房企由于业绩各不相同，市场应对策略也截然不同。"],"rel":"截然相反、截然对立"},{"w":"相去甚远","f":8,"def":"指距离很远，或相差很大。（主语是两者或以上）","key":"距离/水平相差很大，主语须为两者或以上，常指与某标准差距大","dim":"距离感","egs":["只有坚持敬意的内核和礼节的规范，人情才会与“消费”二字相去甚远。","被誉为澳大利亚“红土中心”的土著胜地乌鲁鲁，是一片与想象中相去甚远的所谓“沙漠”。"],"rel":""},{"w":"迥然不同","f":7,"def":"迥然：差得很远。形容差别很大，一点儿也不相同。作谓语、定语。","key":"差别很大、完全不一样，“迥然”不可替换为“截然”（截然强调界限分明）","dim":"全然相异","egs":["两位艺术家的风格迥然不同，一位擅长细腻的水彩画，另一位则偏爱粗犷的油画。","这是一个和从前迥然不同的时代。"],"rel":"迥然、迥异：完全不同。"},{"w":"天差地别","f":5,"def":"形容两种或多种事物之间的差距很大，就像天和地之间的距离一样。","key":"像天和地一样悬殊，含夸张色彩，可修饰具体体验或情形","dim":"夸张对比","egs":["乍看之下，职业年金与企业年金似乎并无区别，但实际情况却是天差地别。","日本在面对不同国家时，对二战反省的真诚度天差地别。"],"rel":""},{"w":"云泥之别","f":2,"def":"云泥：天上的云和地上的泥。比喻相差十分悬殊。（也可形容地位相差悬殊）","key":"如云与泥般高下悬殊，另可形容地位高下","dim":"高低悬殊","egs":["一边是群众反映问题却始终未闻回音，一边是领导稍加推动就轻易破解难题，其中落差，可谓云泥之别。"],"rel":""}]},{"id":"g005","theme":"d-relation","label":"凝聚／凝结等4词","words":["凝聚","凝结","凝固","凝集"],"rows":[{"w":"凝聚","f":28,"def":"1．（动词）气体变浓或凝结。2．（动词）凝结；聚集。（多用于抽象语境，形容思想、感情、精神、智慧和心血等无形资产的集中）","key":"使分散的聚集成一体，多用于精神、力量、共识、人心等抽象对象","dim":"抽象聚集","egs":["荷叶上凝聚着晶莹的露珠。","凝聚合作共识，激发创新活力。"],"rel":"凝聚力"},{"w":"凝结","f":13,"def":"1．（动词）由气体变成液体或由液体变成固体。2．（动词）聚集，积聚。（多用于抽象语境，用来形容血汗、思想或感情等无形资产经过积累和沉淀，最终凝结成有形的成果或作品）","key":"液体变固体；也指血汗、友情等经积累沉淀成有形成果","dim":"由虚变实","egs":["清晨的露水在叶尖上凝结成了小珠子，晶莹剔透。","随着攻克的难题越来越多，“秘籍”也越来越厚，一条条创新经验凝结着我们对精益求精的追求。"],"rel":""},{"w":"凝固","f":6,"def":"1．（动词）液体变成固体。2．（动词）固定不变，停滞。","key":"液体变固体；也指固定不变、停滞（凝固的空气、凝固的模式）","dim":"静止停滞","egs":["寒冷的冬夜，湖面上的水渐渐凝固成了一层厚厚的冰。","积极发掘中国传统建筑的精神追求，建筑是富有生命的东西，是凝固的诗、立体的画、贴地的音符。"],"rel":""},{"w":"凝集","f":3,"def":"（动词）凝结在一起，聚集。（与凝聚相近，可抽象可具象）","key":"凝结聚集，抽象具象皆可，多用于共识、能量、血小板","dim":"中性聚集","egs":["培育和践行社会主义核心价值观，就要充分发挥社会主义核心价值观引领社会思潮、凝集社会共识、推动社会前进的重大作用。","凝集公民行动正能量，战胜一切暴力和邪恶。"],"rel":""}]},{"id":"g006","theme":"d-relation","label":"相得益彰／相辅相成等3词","words":["相得益彰","相辅相成","相映成趣"],"rows":[{"w":"相得益彰","f":28,"def":"指两个人或两件事物互相配合，双方的能力和作用更能显示出来。偏正式结构，含褒义；在句中一般作谓语。","key":"互相配合后各自的长处更加显著，1+1>2，含褒义","dim":"互相成就","egs":["新质生产力与新时代工匠精神相辅相成、相得益彰。","抚州市东乡区虎圩乡坎头村，一座座设施农业大棚依次分布，与乡村美景相得益彰。"],"rel":""},{"w":"相辅相成","f":24,"def":"指两件事物互相配合，互相补充。","key":"互相配合、互相补充，缺一不可，不强调“更显出其好”","dim":"互为补充","egs":["能源绿色低碳转型与增强安全保障能力是相辅相成的。","如果说传统美德是社会文明的“根”和“魂”，那么法治和规则就是它的“骨架”，二者缺一不可，相辅相成。"],"rel":""},{"w":"相映成趣","f":9,"def":"相互衬托着，显得很有趣味，很有意思。作谓语，指两者事物之间。","key":"互相衬托而显得有趣味、有意境，多用于景物、书画","dim":"意境趣味","egs":["泛黄的稻田与通村公路、民居、绿植相映成趣，构成一幅田园“丰”景画卷映入眼帘。","他的书法，尤其进入五十岁后的新体势草书，渴笔浓墨相映成趣，别有一番风味。"],"rel":""}]},{"id":"g007","theme":"i-verb","label":"提升／提高","words":["提升","提高"],"rows":[{"w":"提升","f":27,"def":"（动词）使位置、程度、水平、数量、质量等方面比原来高。","key":"提高（水平、质量、效能），也可指具体位置的移动；偏书面、含“层次上抬”","dim":"层次上抬","egs":["扩大就业容量，提升就业质量。","这些木材需要使用机器提升到指定位置。"],"rel":""},{"w":"提高","f":16,"def":"（动词）使位置、程度、水平、数量、质量等方面比原来高。","key":"使程度、水平、数量、质量等增高，最通用、最中性","dim":"通用增高","egs":["提高政治站位用好督察利剑。","提高新闻稿被采纳的几率是每位作者的目标。"],"rel":""}]},{"id":"g008","theme":"a-speed","label":"历久弥新／经久不衰等3词","words":["历久弥新","经久不衰","长盛不衰"],"rows":[{"w":"历久弥新","f":26,"def":"指经历长久的时间而更加鲜活，更加有活力，更显价值。","key":"经历时间越久越显出新的生命力（思想、精神、经典）","dim":"时间愈久愈新","egs":["新时代的中俄友谊内涵丰富历久弥新。","中华文明历久弥新，生生不息，始终充满文化创新的能量和动力。"],"rel":"历久弥深、历久弥坚"},{"w":"经久不衰","f":11,"def":"持续很长时间而不衰减。形容人精神饱满的状态，身体健壮的外表；形容事物经历很长时间仍旧保持较高的旺盛状态。同“经久不息”。","key":"长久保持旺盛势头、不衰退（多指风气、活动、传统）","dim":"长盛不衰","egs":["玉文化，历经八千年经久不衰，无可替代。","这些脍炙人口的戏剧名作，蕴含了丰富深刻的精神内涵，具有经久不衰的艺术魅力。"],"rel":""},{"w":"长盛不衰","f":6,"def":"长久兴盛而不衰败，比喻长时间保持旺盛的势头。","key":"长期兴旺不衰退，语义同“经久不衰”，更书面","dim":"持续兴旺","egs":["欧美同学会为什么能够长盛不衰？原因有以下几个方面。","必胜的信念和做到极致的理念，在一代代跳水人心中传承，成为他们不断前进、勇攀高峰的动力，成为中国跳水队长盛不衰的秘诀所在。"],"rel":""}]},{"id":"g009","theme":"i-verb","label":"引导／引领","words":["引导","引领"],"rows":[{"w":"引导","f":25,"def":"1．（动词）带领；领路。2．（动词）指引、启发；诱导。","key":"带领、指引，含“疏导、劝告”意味，可用于风气、舆论、群众","dim":"指引方向","egs":["他引导全体村民走上了发家致富的道路。","多地义务教育学校对课间安排做出整体统筹优化，原则上落实 15 分钟课间时长，提供更加从容的课间时间，引导学生走出教室、走向户外、走进阳光。"],"rel":""},{"w":"引领","f":15,"def":"（动词）引导，带领。","key":"率先带领、带领前行，多用于潮流、时代、行业等宏大对象","dim":"率先引领","egs":["理念是行动的先导，一定的发展实践都是由一定的发展理念来引领的。","对于一个政党、一个国家而言，求变意味着不满足于被动适应，而是主动引领时代发展方向。"],"rel":""}]},{"id":"g010","theme":"g-express","label":"展现／呈现等4词","words":["展现","呈现","显现","涌现"],"rows":[{"w":"展现","f":25,"def":"（动词）展示；明显地表现出。","key":"显现出（精神、风貌、才能、前景），主动展示","dim":"主观展示","egs":["彰显中国精神 展现中国担当。","淮安里运河展现梦里水乡画卷。"],"rel":""},{"w":"呈现","f":20,"def":"（动词）显出，露出，展示出。","key":"显出、露出，多为客观状态自然显露，中性与书面","dim":"客观显露","egs":["与第四次全国经济普查结果相比，我国经济发展在规模总量、结构优化、创新驱动、安全保障、绿色转型等方面都呈现出诸多的积极变化。","走进赣州各大园区，呈现眼前的是一处处拼经济、拼发展、拼项目的场景。"],"rel":""},{"w":"显现","f":10,"def":"（动词）呈现，显露。","key":"由隐而显，逐渐显露出来（成效、迹象）","dim":"由隐到显","egs":["11 月份，宏观政策组合效应继续显现。","雾气逐渐消失，重叠的山峦一层一层地显现出来。"],"rel":""},{"w":"涌现","f":6,"def":"（动词）（人或事物）大量出现。","key":"（人、事物）大量地突然出现，重在“多”和“突然”","dim":"大量出现","egs":["专精特新中小企业大量涌现、共同发力，必将不断激发创新创造活力，为国家竞争力提升提供有效助力。","当前，各行各业正涌现出一大批优秀的女性从业者。"],"rel":""}]},{"id":"g011","theme":"a-speed","label":"推陈出新／革故鼎新等3词","words":["推陈出新","革故鼎新","吐故纳新"],"rows":[{"w":"推陈出新","f":24,"def":"推去旧的，产生新的。后多指在文化艺术方面去掉旧的糟粕，吸取其精华，创造出新的来。（适用范围有拓展）","key":"去掉旧的，助长新的，多用于文艺创作、技艺、产品","dim":"文艺创新","egs":["我们研究历史不是为了复古，而是要借鉴历史、推陈出新。","随着大数据、云计算等数字技术推陈出新，智能产业、数字经济蓬勃发展，极大改变了产业发展模式和人民生活方式。"],"rel":""},{"w":"革故鼎新","f":12,"def":"革：除去；鼎新：立新。指革除旧的，建立新的。含褒义，在句中一般作谓语、定语。（多指改朝换代或重大变革）","key":"革除旧的、建立新的，多指重大变革、改朝换代","dim":"重大变革","egs":["太平天国定都南京后，革故鼎新，颁布《天朝田亩制》。","中华文明是革故鼎新、辉光日新的文明。"],"rel":"鼎革：建立新的，革除旧的。旧时特指改朝换代。"},{"w":"吐故纳新","f":4,"def":"指人呼吸时，吐出浊气，吸进新鲜空气。比喻扬弃旧的、不好的，吸收新的，好的。（多形容事物在发展中呈现新的面貌）","key":"呼出浊气吸入清气的比喻，指弃旧收新，可用于思想、组织","dim":"吸收更新","egs":["没有一个文艺高峰时代不是在吐故纳新的开放中到来的。","换届，就要吐故纳新，换出新精神，新思路和新气象。"],"rel":""}]},{"id":"g012","theme":"i-verb","label":"限制／束缚等3词","words":["限制","束缚","约束"],"rows":[{"w":"限制","f":24,"def":"1．（动词）规定范围，不许超过。2．（名词）规定的范围。","key":"规定范围，不许超出（多出于规定、规则）","dim":"外部规定","egs":["限制、禁止两轮电动车已成为多地共识，公告纷纷出台。","全面放宽落户限制，推行常住地公共就业服务制度。"],"rel":""},{"w":"束缚","f":17,"def":"（动词、名词）缠绕捆绑，比喻拘束或限制。","key":"使人受约束不得自由（贬义，含“压抑个性”）","dim":"压抑自由","egs":["道德是一种束缚，用良心、责任、素质等约束我们的言行举止。","改革旨在破除思想观念束缚和体制机制弊端。"],"rel":""},{"w":"约束","f":13,"def":"（动词、名词）限制使不越出范围。","key":"限制使不越出范围，褒贬皆可，多指自我或纪律管控","dim":"自我规范","egs":["所有自由都是以约束为限度，有约束才会拥有更多更大的真自由。","遵守交通规则是每个人的责任，它约束了我们的驾驶行为，确保道路安全。"],"rel":"约束性"}]},{"id":"g013","theme":"a-speed","label":"日新月异／一日千里等3词","words":["日新月异","一日千里","突飞猛进"],"rows":[{"w":"日新月异","f":23,"def":"指每天都在更新，每月都有变化。形容发展或进步迅速，不断出现新事物、新气象。在句中一般作谓语、宾语、定语。","key":"每天每月都有新变化，强调变化之快、之新","dim":"变化速率","egs":["面对日新月异的互联网舆论环境，科学把握网络传播新形势、新任务、新要求，深入推进正能量精品建设，塑造更多正能量网宣品牌。","红寺堡区聚焦产业、就业、社会融入三件事，城乡一体化发展日新月异，荒漠戈壁上建成一座繁荣的生态新城。"],"rel":"日异月殊、日新月盛"},{"w":"一日千里","f":15,"def":"形容马跑得极快。也形容进步或发展的迅速。多含褒义。","key":"一天走一千里，原形容马快，多指发展进步神速（含褒义）","dim":"速度感","egs":["互联网发展一日千里。","一日千里的“中国速度”让这位出国近 20 年的侨胞深感自豪。"],"rel":""},{"w":"突飞猛进","f":10,"def":"形容发展进步飞快，变化巨大。作谓语、宾语、定语，含褒义。","key":"突然、猛烈地飞速前进，强调进步幅度大、势头猛","dim":"进步幅度","egs":["我可以肯定地认为，中国会继续实现突飞猛进的发展。","科技发展突飞猛进，时代洪流奔腾向前。"],"rel":""}]},{"id":"g014","theme":"a-speed","label":"方兴未艾／如日中天","words":["方兴未艾","如日中天"],"rows":[{"w":"方兴未艾","f":22,"def":"指事物正当兴旺之时，不会停止发展。在句中一般作谓语、定语。","key":"正在兴起、尚未停止，处在上升初期，前景广阔","dim":"上升初期","egs":["随着大数据、人工智能等数字技术在农业领域的广泛应用，智慧农业在许多国家方兴未艾。","方兴未艾的文旅康养，让晋城与世界深度握手，一座中国“北方康养样板城市”呼之欲出。"],"rel":""},{"w":"如日中天","f":8,"def":"像太阳正处于天空中央。比喻事物正发展到十分兴盛的阶段。作谓语、定语，含褒义。","key":"像正午的太阳，比喻正当最兴盛、最热烈的鼎盛阶段","dim":"鼎盛阶段","egs":["近年来，我国航天事业如日中天，太空生活也受到人们的广泛关注。","20 年前，法国队 3∶0 战胜了如日中天的巴西队，历史性夺得了队史的首座世界杯冠军。"],"rel":""}]},{"id":"g015","theme":"c-extent","label":"举足轻重／轻而易举等4词","words":["举足轻重","轻而易举","无足轻重","举重若轻"],"rows":[{"w":"举足轻重","f":22,"def":"只要脚移动一下，就会影响两边的轻重。形容有实力，地位重要，能左右局势的发展。在句中一般作谓语、定语。","key":"所处地位重要，一举一动影响全局（褒/中性）","dim":"地位重要","egs":["今天的经济，某种程度上说是一种信心经济，社会预期对经济走向起着举足轻重的作用。","西部地区在全国改革发展稳定大局中举足轻重。"],"rel":""},{"w":"轻而易举","f":16,"def":"重量轻而容易托举起来。形容事情容易做，不用费力。","key":"事情容易做，毫不费力，强调难度小","dim":"难度小","egs":["从来没有轻而易举就能做好的工作，更没有敲锣打鼓就能干成的事业。","改变老祖宗几千年的用餐习惯，不是件轻而易举的事。"],"rel":""},{"w":"无足轻重","f":9,"def":"没有它并不轻些，有它也并不重些。指无关紧要。作谓语、定语。","key":"无关紧要、不起作用，强调不重要（含轻视）","dim":"无关紧要","egs":["新中国成立初期，中国的对外贸易无足轻重。","轻松的浏览、无足轻重的主题恰好填塞忙碌工作尚未覆盖的时间缝隙。"],"rel":""},{"w":"举重若轻","f":6,"def":"举起重的东西好像很轻的样子。比喻能力强，能够轻松地胜任繁重的工作或处理困难的问题。","key":"举起重物像举轻物，形容能力强、能轻松驾驭难事","dim":"能力强","egs":["这本书把人性的尖锐冲突，举重若轻地化解在精彩的带血迹的细节描写中，沉重地唤起人们对灾难的记忆。","发布会上，在回应反腐、环境恶化、领土纠纷等严肃话题时，她举重若轻、娓娓道来。"],"rel":""}]},{"id":"g016","theme":"i-verb","label":"保护／维护","words":["保护","维护"],"rows":[{"w":"保护","f":21,"def":"（动词）尽力照顾，使不受损害。","key":"使不受损害，重在“护”，对象可为具体或抽象（环境、权益、文物）","dim":"护而无损","egs":["切实保护群众合法权益，维护社会稳定和谐。","走进黑龙江扎龙国家级自然保护区，广袤无垠的芦苇荡映入眼帘。"],"rel":"保护伞、保护套、保护性"},{"w":"维护","f":10,"def":"（动词）维持保护，使免于遭受破坏。","key":"维持并保护，多指秩序、利益、权利、尊严不被破坏","dim":"维持不倒","egs":["安全不是某一方面、某一领域的单一安全，我们要坚决维护的安全是总体安全。","维护农民合法权益，保障农业生产安全。"],"rel":"维护者"}]},{"id":"g017","theme":"g-express","label":"标志／载体等5词","words":["标志","载体","代表","象征","缩影"],"rows":[{"w":"标志","f":21,"def":"1．（名词）表明事物特征，便于识别的记号。2．（动词）表明某种特征。","key":"表明某种特征或表明事物的出现（中性/客观）","dim":"客观标识","egs":["这篇作品是作者在创作上日趋成熟的标志。","辛亥革命的成功标志着封建制度的灭亡。"],"rel":"标志物"},{"w":"载体","f":17,"def":"（名词）泛指能够承载其他事物的事物。","key":"承载某事物的物质实体、平台（文化载体、传播载体）","dim":"物质承载","egs":["短视频、直播等形式将成为传播中华文化的重要载体，让更多的人能够在轻松愉快的氛围中了解和学习中华文化。"],"rel":""},{"w":"代表","f":13,"def":"1．（名词）能代替同一类的具有共同特征的人或事物。2．（动词）代替个人或集体表达意见，反映情况。","key":"能显示同一类事物的共同特征，或替他人/集体表达意志","dim":"代表同类","egs":["这位艺术家的画作是当代艺术风格的代表，吸引了众多收藏家和艺术爱好者的关注。","权力是国家给的，是人民赋予的；代表人民，就要说出人民的心声。"],"rel":"代表作"},{"w":"象征","f":12,"def":"（动词、名词）用具体的事物表现某种抽象的事物。","key":"用具体事物表现某种抽象意义（多含情感、文化色彩）","dim":"抽象象征","egs":["标志中的红色代表着中国共产党的旗帜颜色，也象征着人民网的党报背景。","昆木加哨所的老岗楼成为一代代哨所官兵向老一代边防军人学习的精神象征。"],"rel":""},{"w":"缩影","f":3,"def":"（名词）指可以代表同类的具体而微的人或事物。","key":"能代表整体面貌的局部、具体而微者","dim":"局部显整体","egs":["《红楼梦》中的贾府是日趋没落的中国封建社会的缩影。","他们是亿万普通百姓的代表者，他们是为“中国梦”而奋斗的群像缩影。"],"rel":""}]},{"id":"g018","theme":"g-express","label":"反映／反应","words":["反映","反应"],"rows":[{"w":"反映","f":21,"def":"1．（动词）比喻把客观事物的本质表现出来。2．（动词）把情况或意见等向上级报告。","key":"把客观情况反照出来，或把意见转达上去；也可指以比喻显出本质","dim":"如实映照","egs":["文学作品反映现实生活。","党的政策反映了人民群众的期望。"],"rel":""},{"w":"反应","f":8,"def":"1．（动词、名词）物质因某种作用而发生化学变化或物理变化。2．（动词、名词）事情或行为引起的意见、态度或行动。","key":"受刺激后的应对、回应（化学反应、强烈反应）","dim":"刺激回应","egs":["烹饪过程中还有很多其它化学反应，这些反应使我们的食物增添了风味，满足了我们多样化的味蕾需求。","这种细腻的演绎，反应了人民警察的职责担当，将他们对正义的坚守具象化了。"],"rel":""}]},{"id":"g019","theme":"d-relation","label":"不可或缺／必不可少","words":["不可或缺","必不可少"],"rows":[{"w":"不可或缺","f":20,"def":"表示非常重要，不能有一点点的缺失。作定语或谓语。","key":"一时都不能缺少，强调“必需”，多用于抽象事物","dim":"必需性","egs":["中国是全球绿色转型不可或缺的力量，是可再生能源发展的积极推动者。","一种媒体，无论以纸质还是网络为载体，要实现其自身的生存、发展，进而在民众间拥有广泛而深刻的影响力，鲜明的、与时代相符的品质个性须臾不可或缺。"],"rel":""},{"w":"必不可少","f":8,"def":"绝对需要的或者没有就不能做成某种事情的。作谓语、定语。","key":"不能缺少，语义与前者近，更口语、更通用","dim":"通用必需","egs":["铜绿釉是中国传统陶瓷制作中必不可少的釉色之一。","置办年货筹备过年，美味佳肴必不可少，其中准备年夜饭，更是重要的节目。"],"rel":""}]},{"id":"g020","theme":"c-extent","label":"独树一帜／另辟蹊径等4词","words":["独树一帜","另辟蹊径","匠心独具","别出心裁"],"rows":[{"w":"独树一帜","f":20,"def":"单独树起一面旗帜。比喻创造独特风格，自成一家。同“别树一帜”。作谓语、定语。含褒义。（侧重风格）","key":"另树一面旗帜，强调风格、主张自成一家（多指艺术、学术）","dim":"自成一家","egs":["程砚秋在京剧旦角中独树一帜，以“程腔”闻名于世。","多年以来，影视剧市场的“宠儿”无论如何变化，当代军旅现实题材影视剧都一直保持着独树一帜的地位。"],"rel":""},{"w":"另辟蹊径","f":20,"def":"自己开辟一条路。比喻独创新法。作谓语、定语、状语，含褒义。同“独辟蹊径”。（侧重方法上的不同）","key":"另开一条路，强调方法、路径上另找新路","dim":"另找路径","egs":["其中不乏独辟蹊径的思想和一语破的的言辞。","福建湿地保护应独辟蹊径，力促美丽福建持续发展。"],"rel":""},{"w":"匠心独具","f":19,"def":"匠心：精巧的心思。具有独到的或创造性。多指文学艺术创作构思的心思巧妙。作定语、谓语、状语。同“独具匠心”“匠心独运（具）”“别有匠心”。","key":"在构思、布局上独具巧妙心思，褒义，多用于创作、设计","dim":"巧思独特","egs":["除了满满的烟火气，琳琅满目的民族手工艺品让人眼前一亮，这些匠心独具的艺术品，深深吸引了游客的目光。","他们精益求精，匠心独具。"],"rel":""},{"w":"别出心裁","f":10,"def":"心裁：内心的决断。另外想出与众不同的办法、主意。也作“独出心裁”。（侧重想法构思巧妙）","key":"独出巧思，构思与众不同（多指设计、构思精巧）","dim":"构思巧","egs":["6 月 16 日上午，在国网庆城县供电公司组织的“安全月”宣传活动中，一份别出心裁的安全宣传“资料”吸引了广大群众前来围观。","古今中外很多名人的墓志铭，就别出心裁，幽默十足。"],"rel":""}]},{"id":"g021","theme":"e-cause","label":"未雨绸缪／居安思危等4词","words":["未雨绸缪","居安思危","有备无患","防患未然"],"rows":[{"w":"未雨绸缪","f":20,"def":"绸缪：缠绕，引申指修缮。趁着天还没下雨，先把门窗缠缚牢固。比喻事先做好防备工作。在句中作谓语、定语。","key":"还没下雨就先修门窗，强调提前做准备（可行动、可谋划）","dim":"提前准备","egs":["面对错综复杂的宏观经济环境，我们既要看到推动经济发展的有利条件，又要充分估计影响经济发展的不利因素，未雨绸缪，防范风险。","我们必须时刻保持居安思危的忧患意识、未雨绸缪的远见卓识、如履薄冰的谨慎态度。"],"rel":""},{"w":"居安思危","f":8,"def":"处在安定的环境中，也要想到可能产生的危难和祸害。含褒义。","key":"处在安定时想到可能的危险，重在“思”（意识层面）","dim":"意识警惕","egs":["增强忧患意识，做到居安思危，是我们治党治国始终坚持的一个重大原则。","居安思危，思则有备，有备无患。"],"rel":""},{"w":"有备无患","f":4,"def":"指事先有准备，才可以避免祸患。","key":"事先有准备就不会有祸患，强调准备带来的结果","dim":"有备免患","egs":["要坚持底线思维，不回避矛盾，不掩盖问题，凡事从坏处准备，努力争取最好的结果，做到有备无患、遇事不慌，牢牢把握主动权。"],"rel":""},{"w":"防患未然","f":4,"def":"患：灾祸。未然：没有这样，指没有发生。在祸患还没有发生之前就进行防备、采取预防措施。","key":"在祸患发生之前就加以防范，重在“防”","dim":"事前防范","egs":["治理\"宰客\"还应防患未然。","未雨绸缪、防患于未然，是最高效、最明智的安全生产法则。"],"rel":""}]},{"id":"g022","theme":"g-express","label":"彰显／凸显等3词","words":["彰显","凸显","突显"],"rows":[{"w":"彰显","f":20,"def":"1．（动词）鲜明地显示。2．（名词）昭著的事实。多褒义。","key":"鲜明地显示出来（多指品格、意义、价值），含褒义","dim":"鲜明显示","egs":["英雄们的壮举，彰显了中国人民威武不屈的崇高品格。","网络文学，彰显蓬勃的文化生产力。"],"rel":""},{"w":"凸显","f":16,"def":"（动词）清楚地显露。（侧重明显、显著，多搭配抽象事物）中性词。","key":"突出地显出，强调由不明显到明显","dim":"突出显现","egs":["主流媒体融合发展成效凸显。","日本贸易数据凸显中国市场重要性。"],"rel":""},{"w":"突显","f":8,"def":"（动词）突出地显露。（侧重从无到有，可形容具体事物）","key":"突出地显出，与“凸显”近，更侧重“显”的动作性","dim":"突出显露","egs":["手臂上突显出一条条青筋。","这份报告的数据分析突显了公司今年的业绩增长。"],"rel":""}]},{"id":"g023","theme":"i-verb","label":"积累／积淀等3词","words":["积累","积淀","沉淀"],"rows":[{"w":"积累","f":20,"def":"（动词）（事物）逐渐聚集。","key":"逐渐聚集（经验、资金、知识），可“积累+起来”","dim":"渐次积聚","egs":["没有什么诀窍，都是平时积累、注意细节的结果。","30 多年来，中国在经济飞速发展的过程中积累了过硬的基础设施建设能力和丰富经验。"],"rel":"日积月累"},{"w":"积淀","f":18,"def":"1．（动词）积累沉淀。2．（名词）积累沉淀形成的思想、文化、习俗、经验等。（多形容抽象事物）","key":"积累沉淀，多指文化、历史、情感的厚重沉积","dim":"厚重沉积","egs":["悠悠岁月，有着五千多年文明史的中华民族，积淀了灿烂的中华文明，涵养着一方中华儿女。","千年的积淀，长乐枕山襟水，文脉赓续，孕育了独具特色的海耕文化、笔耕文化、士绅文化。"],"rel":""},{"w":"沉淀","f":12,"def":"1．（动词）指溶液中难溶解的固体物质从溶液中释出。2．（动词）凝聚，积累。（多用于抽象事物）","key":"溶液中析出固体；也指心绪沉静下来、杂质沉底（抽象化的“沉淀”）","dim":"下沉沉淀","egs":["河水中的泥沙经过长时间的沉淀，底部形成了一层厚厚的淤泥。","学会沉淀自己，是一种了不起的能力。"],"rel":""}]},{"id":"g024","theme":"c-extent","label":"不言而喻／显而易见等7词","words":["不言而喻","显而易见","有目共睹","家喻户晓","众所周知","不言自明","妇孺皆知"],"rows":[{"w":"不言而喻","f":19,"def":"指不用说就可以明白。形容事理极其明显。也作“不言自明”。作谓语、定语。","key":"不用说就能明白，多指道理、结论显而易见","dim":"道理自明","egs":["他坦承，对亚利桑那州来说，中国的重要性不言而喻。","一副小小的春联就能透视中华民族悠久历史、灿烂文化和民族精神，其重要性是不言而喻的。"],"rel":""},{"w":"显而易见","f":19,"def":"事情或道理非常明显，极容易看清楚。","key":"（事情、道理）明摆着，很容易看清楚","dim":"一看便知","egs":["这道理显而易见，谁都能看明白。","我国对酒驾醉驾长期“零容忍”“严整治”，其效果是显而易见的。"],"rel":""},{"w":"有目共睹","f":18,"def":"睹：看见。指大家都能看得见，形容十分明显。作谓语、定语。（多形容成效、成就等）","key":"人人都看得见，强调事实、成绩确凿不容否认","dim":"事实验证","egs":["中国人权事业取得的成就有目共睹。","过去五年，中国经济发展既平稳又高速，中国国内生产总值飞速增长和人民生活水平巨大改善都是有目共睹的。"],"rel":""},{"w":"家喻户晓","f":9,"def":"家家户户都知道。形容人所共知、广为流传。作谓语、定语。","key":"每家每户都知道，多指人物、事迹传播极广","dim":"入户知晓","egs":["他的名字家喻户晓，他的事迹温暖人心。","“天下兴亡，匹夫有责”在我国是一句家喻户晓的名言。"],"rel":""},{"w":"众所周知","f":8,"def":"大家都知道的。作谓语、定语。","key":"大家都知道，强调知晓范围广","dim":"知晓范围","egs":["众所周知，地球自转的同时还在绕太阳公转。","癌症的危害众所周知，在不少人的印象中，一个人如果患上了癌症，也就被宣判了“死刑”。"],"rel":""},{"w":"不言自明","f":7,"def":"指不用说话就能明白。形容道理或事实很明显，容易理解。","key":"不用说明自己就明白，与“不言而喻”近，更书面","dim":"自我显明","egs":["纪律的重要性不言自明。","本草理论是基于古人农耕生活而产生的，许多古人不言自明的东西，今人已不熟悉，阻碍着今人对本草理论的理解。"],"rel":""},{"w":"妇孺皆知","f":3,"def":"孺：小孩。妇女、小孩全都知道。指众所周知。","key":"妇女小孩都知道，极言流传范围广、影响深","dim":"人人知晓","egs":["这些倡导人与人之间友爱互助的名言，在中华民族历史上可谓家喻户晓、妇孺皆知，并产生了世界性影响。"],"rel":""}]},{"id":"g025","theme":"e-cause","label":"理所当然／顺理成章","words":["理所当然","顺理成章"],"rows":[{"w":"理所当然","f":19,"def":"从道理上说或从情理上讲应该是这样。作谓语、定语、状语。（形容不容怀疑，语气较绝对。）","key":"从道理上讲应当如此，强调合理性","dim":"合乎道理","egs":["有人认为比亚迪“议价”供应商是理所应当的行为。","中国设立南京大屠杀死难者国家公祭日理所当然。"],"rel":"理所应当"},{"w":"顺理成章","f":12,"def":"写文章、做事情顺着条理就能做好。比喻随着某种情况的发展而自然产生的结果。（多褒义）","key":"写文章顺着条理自然成篇，比喻做事合乎条理、自然发展","dim":"自然成序","egs":["在此背景下，国家决定统一核算地方 GDP，可谓顺理成章。","随着城市的发展，各地商品住宅小区越来越多，成立业主委员会成为顺理成章的一个选择。"],"rel":""}]},{"id":"g026","theme":"h-quality","label":"全面／片面","words":["全面","片面"],"rows":[{"w":"全面","f":19,"def":"1．（名词）所有方面，各个方面的总和。2．（形容词）完整的，兼顾各方面的（跟“片面”相对）。","key":"各方面都顾及，周全而不偏","dim":"周全","egs":["“四个全面”涵括我们党治国理政的方方面面。","这些挑战全面多样，斗争形势复杂严峻。"],"rel":""},{"w":"片面","f":9,"def":"（形容词）偏于一面的，不全面（跟“全面”相对）。","key":"只涉及一方面，偏而不全（含贬义）","dim":"偏而不全","egs":["美国新政府上任以来，片面强调“美国优先”，奉行单边主义和经济霸权主义。","只有再通过一次战争才能证明中日孰强孰弱的认识，是幼稚和片面的，具有强烈的感情色彩。"],"rel":""}]},{"id":"g027","theme":"g-express","label":"体现／表现","words":["体现","表现"],"rows":[{"w":"体现","f":19,"def":"（动词或名词）某种性质或现象在某一事物上具体表现出来。","key":"某种性质、精神在具体事物上具体地显现（内在通过外在呈现）","dim":"内在外显","egs":["说实话，办实事，体现了他的务实精神。","“中国游”的蓬勃发展是中国推进高水平对外开放的直接体现。"],"rel":""},{"w":"表现","f":12,"def":"（动词、名词）表示出来、显示出来。","key":"显示出来；也指行为、作风中显示出的态度（含评判色彩）","dim":"外显行为","egs":["作为国家级媒体，在这一领域的表现尤为突出。","现代社会治理的“公共性”应表现出社会公共诉求的有限和理性。"],"rel":"表现力"}]},{"id":"g028","theme":"a-speed","label":"一成不变／亘古不变","words":["一成不变","亘古不变"],"rows":[{"w":"一成不变","f":19,"def":"成：形成。指事物一形成就不再改变。多用于否定句中。作谓语、定语，含贬义。","key":"一经形成就不再改变，多指墨守成规（贬义）","dim":"僵化不变","egs":["中国的发展证明，社会主义并没有定于一尊、一成不变的套路。","与高古青铜器比较，宣德炉又并非因循守旧、一成不变，而是兼收了宋代瓷器的简约、文静。"],"rel":""},{"w":"亘古不变","f":8,"def":"从古到今，没有变化。作谓语、定语。","key":"从古到今从未改变，多指真理、规律、自然法则","dim":"恒久如常","egs":["在亘古不变的时序更替中，我们朝着新的目标一步步前行迈进。","路还是那条路，人还是那些人，艰险恶劣的环境亘古不变，但连队官兵传承赓续的精神之光永存。"],"rel":"亘古不灭：从古到今，永不绝灭。形容永久的生命力。"}]},{"id":"g029","theme":"d-relation","label":"休戚与共／息息相关等4词","words":["休戚与共","息息相关","唇齿相依","如影随形"],"rows":[{"w":"休戚与共","f":19,"def":"休：欢乐，吉庆；戚：忧愁，悲哀。指忧喜祸福彼此共同承担。形容关系密切同甘共苦，利害相关。含褒义，在句中一般作谓语、定语。","key":"欢乐和祸患共同承担，强调同甘共苦、利害一致","dim":"同甘共苦","egs":["党始终与人民休戚与共、生死相依。","大陆与台湾是休戚与共的命运共同体。"],"rel":"休戚相关"},{"w":"息息相关","f":13,"def":"彼此呼吸都相互关联，形容彼此的关系非常密切。","key":"关系非常密切，呼吸相互关联，适用范围最广","dim":"关系紧密","egs":["宪法与我们每个人的生活息息相关。","一桩桩、一件件，都是和百姓生活息息相关的大事实事。"],"rel":""},{"w":"唇齿相依","f":8,"def":"指嘴唇和牙齿互相依靠。比喻互相依存，关系密切。含褒义，作谓语、定语。","key":"像唇和齿一样互相依存，强调彼此依存不可分离","dim":"互相依存","egs":["中越两国是山水相连、唇齿相依的友好邻邦。","经济建设与国防建设唇齿相依。"],"rel":"唇亡齿寒"},{"w":"如影随形","f":8,"def":"好像影子总是跟着身体一样。比喻两个事物或两个人关系密切不能分离。","key":"像影子跟着身体，强调两者时刻相随、不可分离（也可指紧跟）","dim":"时刻相随","egs":["档案与历史总是相伴相生、如影随形。","“不迎合”的同时，种种压力如影随形。"],"rel":""}]},{"id":"g030","theme":"b-attitude","label":"持之以恒／坚持不懈等3词","words":["持之以恒","坚持不懈","锲而不舍"],"rows":[{"w":"持之以恒","f":18,"def":"持：保持。恒：恒心。有恒心地长期坚持下去。含褒义，在句中一般作谓语、状语。","key":"长久坚持下去，强调时间的持续性","dim":"长期坚持","egs":["锻炼身体必须持之以恒，不然收效甚微。","只有脚踏实地地研发、持之以恒地投入，才能打赢关键核心技术攻坚战。"],"rel":""},{"w":"坚持不懈","f":17,"def":"坚持到底，一点不松懈。形容做事持之以恒。作谓语、定语、状语。","key":"坚持到底不松懈，强调意志顽强、不放弃","dim":"意志顽强","egs":["经过新时代十年坚持不懈的强力反腐，反腐败斗争取得压倒性胜利并全面巩固。","坚持不懈做好疫情防控工作关键靠社区。"],"rel":"坚持"},{"w":"锲而不舍","f":12,"def":"不断地镂刻，比喻有恒心，有毅力。可作谓语、定语、状语，含褒义。","key":"不停地雕刻下去，比喻有恒心、有毅力（更书面、更形象）","dim":"恒心毅力","egs":["发扬钉钉子精神，是指做事情要有一种稳扎稳打、锲而不舍的精神状态。","从中秋到国庆，从元旦到春节，党中央抓完这个节日抓下个，体现了锲而不舍抓作风的坚定决心。"],"rel":""}]},{"id":"g031","theme":"g-express","label":"打造／塑造等5词","words":["打造","塑造","改造","营造","制造"],"rows":[{"w":"打造","f":18,"def":"（动词）制造、创造的意思。进行打造的可以是具体的事物，如金银、首饰、兵器等，也可以是抽象的概念，如精神、文化、品牌等。","key":"像打造器物一样精心制作、建设（品牌、平台、高地），多用于抽象工程","dim":"精心建设","egs":["着力打造一批具有竞争力的新型主流媒体。","这件艺术品是经过千锤百炼打造出来的精品。"],"rel":""},{"w":"塑造","f":14,"def":"1．（动词）用泥土等可塑材料制成人物形象，形容用语言文字或其他艺术手段表现人物形象。2．（动词）通过培养、打造、或改造使人或事物达到某种预定的目标。","key":"用泥土等造成形象；也指培养、刻画（形象、灵魂、品格）","dim":"塑形刻画","egs":["画家用画笔和色彩塑造了一个充满力量和魅力的女性形象，展现了她的独立和坚强。","南非目前正站在能源革命的前沿，创新不断推动行业进步，塑造着未来格局。"],"rel":""},{"w":"改造","f":11,"def":"（动词）就原有的事物加以修改或变更，使适合需要。","key":"就原有基础加以修改、改变使之适合需要（含“由旧变新”）","dim":"改旧为新","egs":["老旧小区改造一头连着民生福祉，一头连着城市发展。","下放农村劳动改造，全家老小一度十分困苦。"],"rel":""},{"w":"营造","f":8,"def":"（动词）有计划、有目的地建造。","key":"经营建造；也指有意造成某种气氛、环境（氛围、环境）","dim":"营造氛围","egs":["在中国建筑史研究中，不但要研究中国传统建筑高超的营造技艺、独特的空间形态、恢宏的气度气象，更要积极发掘蕴含其中的精神追求。","太原铁警营造良好春运治安环境。"],"rel":"营造氛围"},{"w":"制造","f":8,"def":"1．（动词）把原材料加工成适用的产品制作。2．（动词）造成某种气氛或局面。","key":"用人工使原材料成为产品；也指人为造成（事端、气氛，可含贬义）","dim":"人工生产","egs":["动物与人的重要区别就是人能够制造和使用劳动工具。","在舆论场上，仍然有人在继续制造恐慌情绪。"],"rel":""}]},{"id":"g032","theme":"h-quality","label":"精准／准确等3词","words":["精准","准确","精确"],"rows":[{"w":"精准","f":18,"def":"（形容词）非常准确，精确。","key":"精确而准确，强调“命中目标”，常用于施策、打击、识别","dim":"命中目标","egs":["切实做到精准扶贫。","导弹全部精准命中目标，检验了精确打击和区域拒止能力。"],"rel":"精准化、精准性"},{"w":"准确","f":18,"def":"（形容词）情况、结果等完全符合标准、实际或预期。","key":"结果或表达完全符合事实、标准，最通用","dim":"符合事实","egs":["确保全国文物普查数据真实准确、完整可信。","全面准确地贯彻“一国两制”。"],"rel":"准确无误"},{"w":"精确","f":12,"def":"（形容词）精密确切的。","key":"精密准确，强调数据、计算、测量上的误差小","dim":"数值精密","egs":["经过大量数据的训练后，该模型能精确预测各种人体细胞内部的基因表达情况。","如何把它的刻度设置得更精确，让用“尺子”的人“眼不花”，是值得科学共同体思考的问题。"],"rel":""}]},{"id":"g033","theme":"g-express","label":"描绘／描摹等4词","words":["描绘","描摹","勾勒","描述"],"rows":[{"w":"描绘","f":18,"def":"（动词）用线条、颜色或语言文字表现事物的情景。","key":"用线条、色彩或语言文字描画（画面、图景、蓝图）","dim":"画出图景","egs":["展馆入口，五幅描绘疫情防控工作者的巨型海报高悬，成为了“人民至上 生命至上”无声的注脚。","一项项具体的任务书、施工图和政策清单明确了努力方向，想方设法补短板，锲而不舍抓落实，就能描绘出更亮丽的民生画卷。"],"rel":""},{"w":"描摹","f":10,"def":"1．（动词）照着底样写和画。2．（动词）用语言文字等艺术手段表现人物或事物。","key":"照着原样摹写（实物、形态、声音），重“像不像”","dim":"照原摹写","egs":["画大写意不是简单描摹自然，而是借助笔墨抒发情感，聊写胸中意趣。","作家用细腻的笔触描摹了一个小镇的日常生活，让读者仿佛身临其境。"],"rel":""},{"w":"勾勒","f":10,"def":"1．（动词）用线条画出轮廓。2．（动词）比喻用简单的笔墨描写事物的大致情况。","key":"用简练的线条画出轮廓；也指简要地叙述出轮廓","dim":"勾勒轮廓","egs":["横跨水面的飞桥在落日余晖中，勾勒出清晰的剪影。","中国方案勾勒出全球治理变革完善的蓝图。"],"rel":""},{"w":"描述","f":7,"def":"（动词）描写叙述，运用语言、文字等对事物进行形象化的阐述。","key":"用语言叙述出事物的样子或过程，重“说清楚”","dim":"语言叙述","egs":["作品朴实地描述了农民的生活。","物理学家总是希望宇宙万物的运行规律可以是“极简模式”，简单到或许只需要用一个方程就可以描述。"],"rel":""}]},{"id":"g034","theme":"c-extent","label":"司空见惯／屡见不鲜等4词","words":["司空见惯","屡见不鲜","习以为常","不足为奇"],"rows":[{"w":"司空见惯","f":18,"def":"司空：古代官职。指某事常见，不足为奇。在句中一般作谓语、定语、宾语。","key":"看惯了就不觉得奇怪，主语多为“人”，含“麻木”意味","dim":"看惯不奇","egs":["当生活中司空见惯的物品遇上“脑洞之王”，会擦出怎样的创意火花？","央企违规发福利，早已变得司空见惯，但是国家很少像这样对类似违规行为动真格的。"],"rel":""},{"w":"屡见不鲜","f":15,"def":"指多次见到，不觉得新鲜。作谓语、定语。","key":"多次见到，不觉得新鲜，强调出现次数多","dim":"出现频次","egs":["虚假信息、恶意传播、网络暴力等问题屡见不鲜，给社会带来了诸多困扰。","“馕”在新疆是屡见不鲜的美食之一，距今已有两千多年的历史。"],"rel":""},{"w":"习以为常","f":11,"def":"习：习惯。常：平常。指某种事情经常去做，或某种现象经常看到，就成了常规或习惯，觉得很平常了。作谓语、定语。","key":"习惯了就当作平常，强调个人习惯成自然","dim":"习惯成自然","egs":["印度内战打响，6 名警察死亡 80 多人受伤，莫迪政府却习以为常。","事实上这样的事自古以来经常发生，人们习以为常，见怪不怪。"],"rel":""},{"w":"不足为奇","f":6,"def":"某种事物或现象很平常，没有什么奇怪的。","key":"不值得奇怪，对现象的评价，主观判断色彩重","dim":"不足为怪","egs":["所谓巧妇难为无米之炊，从组队便陷入困境的国少队，小组赛折戟不足为奇。","有如此虚怀若谷、谦以自牧的君子之风，精品力作不断涌现，也就不足为奇了。"],"rel":""}]},{"id":"g035","theme":"i-verb","label":"支撑／支持","words":["支撑","支持"],"rows":[{"w":"支撑","f":18,"def":"1．（动词）顶住物体使不倒塌。2．（动词）勉强维持，支持局面使不崩溃。","key":"顶住压力使不倒，也指勉强维持（经济支撑、支撑局面）","dim":"顶住负担","egs":["我国数字经济核算统计标准出炉，为高质量发展提供数据支撑。","尽管面临经济困境，他依然努力支撑家庭的生活。"],"rel":"支撑点"},{"w":"支持","f":17,"def":"1．（动词、名词）给以鼓励或赞助。2．（动词）勉强维持。","key":"给予鼓励或援助（道义、资金、技术）；也表示赞同","dim":"给予援助","egs":["为政府和企业提供决策支持。","支持民营企业发展，就是支持整个国民经济的健康发展。"],"rel":""}]},{"id":"g036","theme":"c-extent","label":"凤毛麟角／寥寥无几等4词","words":["凤毛麟角","寥寥无几","屈指可数","九牛一毛"],"rows":[{"w":"凤毛麟角","f":17,"def":"凤毛：凤凰的毛。麟角：麒麟的角。比喻珍贵而稀少的人或事物。多作宾语，也作定语。含褒义。","key":"凤凰毛、麒麟角，极言稀少而珍贵（多指人才、珍品）","dim":"稀少而贵","egs":["在众多将帅中，享有“军事家”称号的仅有 36 人，可谓凤毛麟角。","直到现在，公认能做出一款既容易操控，又安全稳定的无人机的厂商仍是凤毛麟角。"],"rel":""},{"w":"寥寥无几","f":13,"def":"形容稀少，没有几个。","key":"数量非常少，客观陈述，中性","dim":"数量少","egs":["田间浇地、锄苗的多是老人孩子，而本该做这些活计的青壮年却寥寥无几。","打开手机客户端，严肃新闻寥寥无几，低俗信息却铺天盖地。"],"rel":"寥寥可数、寥若晨星、寥若星辰、"},{"w":"屈指可数","f":9,"def":"扳着手指就可以数清楚，形容数量稀少。作谓语、定语。","key":"扳着手指就能数清，少但多有“珍贵/难得”含义","dim":"少而可数","egs":["环视宇内，能够自主建造航母的国家，屈指可数。","这里是关西地区屈指可数的攀岩景点，岩石坚硬且凹凸不平。"],"rel":""},{"w":"九牛一毛","f":2,"def":"意为九头牛身上失掉一根毛，微不足道。后用来比喻众多数量中的一点点，指极少，很轻微。名词","key":"极大数量中极小一部分，强调占比微不足道","dim":"占比极小","egs":["要大老板拿出这点钱来加我们的工资，对他来说，不过是九牛一毛。"],"rel":""}]},{"id":"g037","theme":"b-attitude","label":"急功近利／急于求成","words":["急功近利","急于求成"],"rows":[{"w":"急功近利","f":17,"def":"急：急切，急于。指急于求成，贪图眼前功利。含贬义，在句中一般作谓语、定语。","key":"急于求成、贪图眼前利益（贬义较重，含功利心）","dim":"贪眼前利","egs":["搞教育不能急功近利，它不是短时性的，而是长期性的。","许多人对功利赤裸裸地甚至不择手段地追逐与攫取，使社会中弥漫、充斥着急功近利的气息。"],"rel":""},{"w":"急于求成","f":5,"def":"形容急着要取得成功。含贬义。（含有忽视质量，追求速度之意）","key":"急着要取得成功，强调心态急躁","dim":"心态急躁","egs":["在现实生活中，一些年轻人存在一种急于求成、急功近利的心理。","推进城镇化健康发展是优化经济发展空间格局的重要内容，要有历史耐心，不要急于求成。"],"rel":""}]},{"id":"g038","theme":"i-verb","label":"平衡／均衡","words":["平衡","均衡"],"rows":[{"w":"平衡","f":17,"def":"（动词、形容词、名词）对立的方面保持均等或大致均等。","key":"两边相等或保持稳定状态（动态平衡、心理平衡）","dim":"保持稳定","egs":["到 2035 年全谷物食品供给和消费实现动态平衡。","传者有使命，受者有需求，平衡利益，解决矛盾，是永不过时的话题。"],"rel":""},{"w":"均衡","f":7,"def":"（形容词、副词）平衡。","key":"各部分数量、程度大体相当（均衡发展、营养均衡）","dim":"分布相当","egs":["每天摄取均衡的营养，才能常保身体的健康。","加快义务教育优质均衡发展和城乡一体化。"],"rel":"均衡化"}]},{"id":"g039","theme":"g-express","label":"诠释／解释等3词","words":["诠释","解释","阐释"],"rows":[{"w":"诠释","f":17,"def":"（动词、名词）说明，解释。（多书面语）","key":"说明、解释（多指对作品、理念的阐发，带有“演绎”色彩）","dim":"阐发演绎","egs":["抗疫大考生动诠释时代精神。","喀斯特地貌造就的美景让人流连忘返，人与自然和谐共处在这方水土上得到生动诠释。"],"rel":"诠释力"},{"w":"解释","f":11,"def":"（动词、名词）分析、说明（某事的意义、原因、理由等）。","key":"说明含义、原因、理由，最通用","dim":"说明原委","egs":["《关于审理生态环境侵权责任纠纷案件适用法律若干问题的解释》。","清明节期间，不少家长碰到了各式问题和矛盾，比如要不要带孩子去扫墓、怎样向孩子解释死亡等。"],"rel":""},{"w":"阐释","f":10,"def":"（动词）阐述并解释。","key":"阐述并解释，多用于理论、观点、政策，书面性强","dim":"理论阐述","egs":["本期学术版围绕这一主题，刊发 3 篇文章进行阐释。","另一方面，深刻阐释中西方现代化在价值理念上的差异。"],"rel":""}]},{"id":"g040","theme":"b-attitude","label":"人云亦云／随波逐流等3词","words":["人云亦云","随波逐流","亦步亦趋"],"rows":[{"w":"人云亦云","f":17,"def":"别人怎么说，自己也跟着怎么说。形容随声附和，没有主见。（侧重说）","key":"别人怎么说自己也怎么说，强调没主见、随声附和","dim":"鹦鹉学舌","egs":["在大是大非面前，是含糊不清还是立场坚定；在杂音噪音面前，是人云亦云还是保持定力。","一个健康向上的网络，绝不是随波逐流、人云亦云、跟风起哄的地方。"],"rel":""},{"w":"随波逐流","f":11,"def":"比喻自己没有立场和主见，只是随大流，跟着别人走。","key":"随着波浪起伏，比喻没主见、随大流（含放弃原则）","dim":"随大流","egs":["大多数人其实都是随波逐流的，生活的大部分选择都是跟着身边人走。","新闻舆论工作者一定要保持独立思考的精神，不能人云亦云、随波逐流。"],"rel":""},{"w":"亦步亦趋","f":9,"def":"别人慢走，跟着慢走；别人快走，也跟着快走。比喻没有主见，处处追随模仿的意思。（侧重做）","key":"别人走也跟着走，比喻事事模仿追随（多含缺乏独创）","dim":"模仿跟随","egs":["人类历史上没有一个民族、一个国家可以通过依赖外部力量、照搬外国模式、跟在他人后面亦步亦趋实现强大和振兴。"],"rel":""}]},{"id":"g041","theme":"h-quality","label":"完善／完整等4词","words":["完善","完整","完美","完备"],"rows":[{"w":"完善","f":17,"def":"1．（形容词）完备良好。2．（动词）使完善。","key":"完备而良好，使之更齐全（体制、机制、设施）","dim":"趋于完备","egs":["持续完善基础研究与成果转化的循环促进机制。","不断完善的中国反恐怖主义法律体系。"],"rel":""},{"w":"完整","f":13,"def":"（形容词）具有或保持着应有的各部分，没有损坏或残缺。","key":"整体未残缺、未被分割（结构、体系、过程）","dim":"整体无缺","egs":["我国全过程人民民主是一个完整的制度链条。","任何人都不要低估中国人民捍卫国家主权和领土完整的坚强决心、坚定意志、强大能力！"],"rel":""},{"w":"完美","f":9,"def":"（形容词）完备美好，没有缺点。","key":"完备美好、没有缺陷，程度最高","dim":"毫无缺陷","egs":["工匠精神是一种严谨认真、精益求精、追求完美、勇于创新的精神。"],"rel":"完美无缺、完美无瑕"},{"w":"完备","f":9,"def":"（形容词）应该有的全都有了。","key":"应该有的全都有，强调“齐全”（手续、条件）","dim":"齐全无缺","egs":["市域具有较完备的社会治理体系，在国家治理体系中具有承上启下的枢纽作用。"],"rel":""}]},{"id":"g042","theme":"e-cause","label":"一劳永逸／高枕无忧","words":["一劳永逸","高枕无忧"],"rows":[{"w":"一劳永逸","f":17,"def":"辛苦一次，把事情处理好，以后就不用费力了。在句中常作定语、谓语等，多用于否定句中。","key":"辛苦一次就永远安逸，强调投入一次长期受益（常用于否定）","dim":"一次长逸","egs":["先进性和纯洁性建设不是一蹴而就的，也不是一劳永逸的。","媒体融合，唯一不变的就是变化，没有一种模式可以立竿见影、一劳永逸地完成媒体融合。"],"rel":""},{"w":"高枕无忧","f":3,"def":"指垫高枕头睡觉，无所忧虑，指平安无事，不用担忧。也比喻放松警惕，麻痹大意。","key":"垫高枕头睡觉，形容平安无事、不必忧虑（多指局势安定）","dim":"无忧安枕","egs":["今年雨水大，不要以为大堤修整过一次，就可以高枕无忧了。","不能奢望技术为每个人提供高枕无忧的“保险箱”，应该提高安全意识、法律意识，加强全社会对公民个人信息的立体防护。"],"rel":""}]},{"id":"g043","theme":"i-verb","label":"展示／显示等3词","words":["展示","显示","警示"],"rows":[{"w":"展示","f":17,"def":"（动词）展现，显示，摆出来让人看。","key":"清楚地摆出来给人看（成果、魅力、形象），主动性最强","dim":"主动摆出","egs":["中国制造公交车在乌兰巴托苏赫巴托广场展示。","长春的街景亮化工程展示了长春城市建设的新面貌和发展长春冰雪经济的新热度。"],"rel":""},{"w":"显示","f":11,"def":"（动词）明显地表示。","key":"明显地表现出（能力、迹象、数据），也指“显示器”","dim":"清楚显出","egs":["这截然不同的结果，足以显示唯有强军才能强国、唯有强国才能太平。"],"rel":""},{"w":"警示","f":6,"def":"（动词、名词）警告，启示。","key":"通过警告使人警醒（多指教训、案例的警示作用）","dim":"警告提醒","egs":["这些准则规范，是针对主要问题、突出问题来划定基本底线，既是对教师的警示提醒，也是一份严管厚爱。","这些历史镜鉴，不仅让我们看到权力滥用、金钱腐蚀的严重后果，更警示我们在任何时候都应将权力视为责任，将地位视为服务人民的平台，而非迷失自我的借口。"],"rel":""}]},{"id":"g044","theme":"c-extent","label":"浮光掠影／走马观花等4词","words":["浮光掠影","走马观花","浅尝辄止","蜻蜓点水"],"rows":[{"w":"浮光掠影","f":16,"def":"浮光：水面上的反光。掠影：一闪而过的影子。比喻因事物很快消逝而使人对它的印象不深。比喻观察事物漂浮粗疏，印象不深刻。含贬义（侧重抽象语境，多指不细致）","key":"像水面光和掠过的影子，印象不深、观察不细（多指印象、了解）","dim":"印象肤浅","egs":["在评价问题上，不能“浮光掠影”“点到为止”，应进行更加细致的研究。","每当夜幕降临，安徽省全椒县太平古城内张灯结彩、新襄河上游船穿梭、步行桥上人潮涌动、楼台亭阁浮光掠影……恰如一幅“清明上河图”在这里徐徐展开。"],"rel":""},{"w":"走马观花","f":15,"def":"走马：骑马快跑。比喻观察事物或者了解情况不深入细致。（含贬义。侧重于用眼看具体事物的过程，看得快；一般不形容读书）","key":"骑在马上看花，粗略地看一遍（重“看”的过程）","dim":"粗略观看","egs":["有的上级督查检查考核兴师动众但又各行其是，基层没有那么多人力、物力，往往只能应付，而检查组也是走马观花。","城市漫步既不同于走马观花式的传统观光旅游，也不是漫无目的的“散步和闲逛”。"],"rel":""},{"w":"浅尝辄止","f":12,"def":"略微尝试一下就停下来。指做事情不深入。","key":"稍微尝试就停止，强调不愿深入钻研","dim":"不肯深入","egs":["可惜的是，我尽管出于爱好选修了足够多的人文类课程，但终是浅尝辄止、不成体系。"],"rel":""},{"w":"蜻蜓点水","f":9,"def":"指蜻蜓在水面飞行时用尾部轻触水面的动作。比喻做事肤浅不深入。","key":"像蜻蜓点水一样一触即离，做事肤浅不深入","dim":"浅触即离","egs":["水面泛起点点涟漪，蜻蜓点水，锦鲤巡游，一派生机盎然的盛夏图景。","少数领导干部对自身存在的问题看不到、找不出、查不准，甚至不想查、不愿查、不真查，蜻蜓点水、隔靴搔痒、应付了事。"],"rel":""}]},{"id":"g045","theme":"c-extent","label":"根深蒂固／积重难返","words":["根深蒂固","积重难返"],"rows":[{"w":"根深蒂固","f":16,"def":"根基深厚牢固，不可动摇。在句中一般作谓语、定语。中性词。（侧重难动摇）","key":"根基牢固、不易动摇（多指观念、势力、习惯）","dim":"难以动摇","egs":["在感人至深的话语里，光荣属于人民，感情系于人民，力量源于人民，体现了一以贯之的人民立场，彰显了根深蒂固的人民情怀。","美国种族主义根深蒂固，种族歧视情势严重。"],"rel":""},{"w":"积重难返","f":14,"def":"重：程度深；返：回转。指长期形成的不良习惯、弊端等，不易改变。含贬义，在句中一般作谓语、定语，多搭配“问题”。（侧重时间久）","key":"长期形成的问题深重，难以改变（贬义，多指弊端、陋习）","dim":"积弊难改","egs":["一旦躺在过去的功劳簿上，安于现状、止步不前，就会暮气丛生、积弊日深，最终积重难返。","面对盘根错节的问题，积重难返的矛盾，个别党员领导干部产生了观望态度、畏难情绪。"],"rel":"积习深重、积习难改：指长期形成的旧习惯很难更改。"}]},{"id":"g046","theme":"f-light","label":"顾此失彼／捉襟见肘等4词","words":["顾此失彼","捉襟见肘","左支右绌","应接不暇"],"rows":[{"w":"顾此失彼","f":16,"def":"顾了这个，丢了那个。形容做事无法全面照顾或穷于应付，忙乱或慌张的情景。作谓语、定语。","key":"顾了这个丢了那个，形容无法全面照顾","dim":"照顾不全","egs":["诸如此类顾此失彼的做法，虽然完成了某些方面的指标和任务，但是留下了后遗症。","坚持系统观念，必须从事物的整体着眼、谋划推进，防止工作顾此失彼。"],"rel":""},{"w":"捉襟见肘","f":15,"def":"指整理一下衣襟，就露出了胳膊肘，形容衣服破烂，生活窘困。也比喻困难很多，应付不过来。含贬义。（侧重人力、物力等资源、条件有限）","key":"拉一下衣襟就露出胳膊肘，形容衣服破烂；也比喻困难重重、应付不过来","dim":"穷于应付","egs":["当代作家享受当代可以，表现当代则显得捉襟见肘，力不从心。","用一篇千字短文介绍李渔及其《闲情偶寄》，实在是捉襟见肘。"],"rel":""},{"w":"左支右绌","f":9,"def":"支：支撑。绌：不足。应付了这边，那边又有了问题。指力量不足。（侧重财力或能力有限，应付不过来）","key":"力量不足，顾了这头顾不了那头，处境窘迫","dim":"力量不济","egs":["洪秀全所处的时代时逢中西交冲，身处千年未有的时代变局，他左支右绌，无力应付。","希腊为了应付财政上的左支右绌，通过了一项议案，让数千名公务员丢了工作。"],"rel":""},{"w":"应接不暇","f":6,"def":"暇：空闲。1．指景物很多，看不过来。2．形容来人或事情太多，应付不过来。（主语一般是人）","key":"来的人或事太多，接待应付不过来","dim":"事务繁多","egs":["火车站的问事处挤满了人，工作人员应接不暇。","基层的事务千头万绪，一些部门人少事多，应接不暇。"],"rel":""}]},{"id":"g047","theme":"d-relation","label":"汇聚／聚集等3词","words":["汇聚","聚集","汇集"],"rows":[{"w":"汇聚","f":16,"def":"（动词）指汇合在一处，没有分开的意思。","key":"（水流、人群、力量）聚集到一起，含“汇流”意象","dim":"汇流而聚","egs":["广泛团结和联系更多群众，就能最大限度地凝聚人心、最大规模地汇聚力量。","汇聚时代之声，彰显中国精神。"],"rel":""},{"w":"聚集","f":16,"def":"（动词）围聚、集合、会合，凑在一起。（多形容具体的人或事物）","key":"集合在一起，最通用","dim":"通用集合","egs":["在势不可挡的新能源浪潮中，江苏聚集了诸多新能源汽车上下游企业。","化解信访矛盾，必须形成配合密切的相互协作，聚集各方合力。"],"rel":"集聚"},{"w":"汇集","f":9,"def":"（动词）聚集、集中在一起。（多具体人或事物）","key":"聚集、集合在一起（资料、人才、作品）","dim":"集合起来","egs":["即将开始的 2025 年春节档，汇集各种类型大片、高关注度的 IP，有望形成新的观影热潮。","该机构汇集以色列科技部门、学术界、国防工业等领域专家。"],"rel":""}]},{"id":"g048","theme":"i-verb","label":"激发／激活","words":["激发","激活"],"rows":[{"w":"激发","f":16,"def":"（动词）刺激使奋发。","key":"刺激使产生（情感、斗志、活力），对象多为抽象的“劲头”","dim":"刺激产生","egs":["进一步激发基层干事活力。","这场比赛激发了我们团队的斗志。"],"rel":""},{"w":"激活","f":5,"def":"（动词）泛指刺激某事物，使活跃起来。","key":"使原本沉寂的活跃起来（机制、市场、细胞、潜能）","dim":"由静转活","egs":["激活各类经营主体活力。","冰雪运动激活冬季旅游新动能。"],"rel":""}]},{"id":"g049","theme":"b-attitude","label":"莫衷一是／各执己见等5词","words":["莫衷一是","各执己见","众说纷纭","各执一词","见仁见智"],"rows":[{"w":"莫衷一是","f":16,"def":"莫：不能。衷：折衷，判断。是：对。不能断定哪个对，哪个不对。也指意见纷纭，分歧很大，不能得出一致的结论。作谓语、定语。（侧重难以统一）","key":"不能得出一致结论，各有各说法、无法统一","dim":"无法定论","egs":["个中原因莫衷一是，有的专家将之归咎为英国近年来执行的紧缩政策导致高校科研和培养师资的经费不足，有的专家则认为，这是生源水平下降的结果。","如果一个民族、一个国家没有共同的核心价值观，莫衷一是，行无依归，那这个民族、这个国家就无法前进。"],"rel":""},{"w":"各执己见","f":7,"def":"各人都坚持自己的意见。作谓语、定语。同“各持己见”、“各抒己见”。（主语需是两者或以上）","key":"各人坚持自己的意见，互不相让（含固执）","dim":"固执己见","egs":["双方在此次会谈中依然如以前几轮会谈一样各执己见。","各执己见的网友们为此争得不可开交，而《大鱼海棠》的票房也在争议中越炒越热。"],"rel":"各持己见、各抒己见"},{"w":"众说纷纭","f":6,"def":"纷纭：多而姑乱。形容人多嘴杂，各有各的说法，议论纷纷。作谓语、定语。（前面可加主语，也可不加主语；侧重观点多）","key":"人多嘴杂，说法各种各样","dim":"说法繁多","egs":["中国特色社会主义三十多年来实践的惊人成就世人公认，但对其发展呈现的突出矛盾和未来走向，则众说纷纭，议论很多。","专家对手机引雷说法众说纷纭。"],"rel":""},{"w":"各执一词","f":6,"def":"各人坚持各人的说法。形容意见不一致。同“各执一端”。作谓语。（主语是二者或以上）","key":"各人坚持一种说法，多指争执双方各说各的","dim":"各持一说","egs":["调解之初，双方情绪十分激动，各执一词，互不相让。","熟记校歌，究竟是传承文化，还是固步自封？对此，社会各界各执一词。"],"rel":""},{"w":"见仁见智","f":3,"def":"指对同一问题，各人有个人的看法和道理。（褒义）","key":"各人从不同角度有不同看法（中性，含“各有道理”）","dim":"各有道理","egs":["有人说，效率与公平的关系问题是一个见仁见智的问题，孰先孰后、孰轻孰重往往是公说公有理、婆说婆有理，难以定于一端。","党的提出乡村振兴战略以来，出现了对乡村振兴的多方面的诠释，关于乡村振兴的文献日益丰富，学者们从不同角度见仁见智，形成了一系列的丰硕成果。"],"rel":""}]},{"id":"g050","theme":"c-extent","label":"南辕北辙／缘木求鱼","words":["南辕北辙","缘木求鱼"],"rows":[{"w":"南辕北辙","f":16,"def":"辕：车辕，车前驾牲口的直木。辙：车轮经过留下的痕迹。本要往南边去却驾车向北。比喻行动和目的截然相反。含贬义，多做谓语、定语。(多用于同一个主语，侧重目标与做法相反）","key":"想往南却车向北，比喻行动和目的正好相反","dim":"行动背目的","egs":["如果一方面盼望有功于“世道人心”的文艺，而同时又不许文艺作品带着强心和清泻的药品，这何异南辕北辙？","欧盟本不必押注成为好战的军国主义分子，现在却走在与正确方向南辕北辙的道路上。"],"rel":""},{"w":"缘木求鱼","f":16,"def":"原义是爬上树去找鱼。比喻行事的方向、方法不对，必将劳而无功。作谓语、宾语，含贬义。（侧重方法错误）","key":"爬到树上去找鱼，比喻方向方法不对，一定达不到目的","dim":"方法方向错","egs":["脱离经济发展抓环境保护是“缘木求鱼”，离开环境保护搞经济发展是“竭泽而渔”，正确的经济政策就是正确的环境政策。","诚信有着坚实的精神内核，离开仁义谈诚信如同舍本逐末，缘木求鱼。"],"rel":""}]},{"id":"g051","theme":"d-relation","label":"潜移默化／耳濡目染","words":["潜移默化","耳濡目染"],"rows":[{"w":"潜移默化","f":16,"def":"潜：暗中。默：毫无声息。指受到外来影响而在不知不觉中发生变化。在句中一般作谓语、定语、状语。（侧重长时间、无形地影响）","key":"在不知不觉中受到感染而变化，强调“过程无形、时间长”","dim":"无形渐染","egs":["精神文明建设要做到潜移默化、春风化雨，引导群众树立文明观念、争当文明公民。","军歌的魅力，就是能够在潜移默化中发挥教育引导作用。"],"rel":""},{"w":"耳濡目染","f":12,"def":"濡：沾湿；染：沾染。指耳朵经常听到，眼睛经常看到，无形之中受到影响。在句中一般作谓语、宾语。（侧重身处某种外在环境中）","key":"耳朵经常听到、眼睛经常看到，不知不觉受到影响，强调“亲历环境”","dim":"耳目亲历","egs":["出生在教育世家的卓瑛，从小耳濡目染，深知教师这个职业责任重大。","一系列接地气、冒热气、聚人气的群众性军营文化活动，让官兵在耳濡目染中获得文化滋养，砥砺战斗精神。"],"rel":"濡染"}]},{"id":"g052","theme":"c-extent","label":"脱颖而出／崭露头角等4词","words":["脱颖而出","崭露头角","出类拔萃","鹤立鸡群"],"rows":[{"w":"脱颖而出","f":16,"def":"原指锥尖透过囊袋显露出来，比喻有才能的人或事物得到机会，本领全部显现出来。含褒义。（侧重出现）","key":"锥处囊中，尖端立刻露出，比喻才能全部显露、超出众人","dim":"才显露尖","egs":["近来，张杨执导的《冈仁波齐》脱颖而出，创造了近期国产文艺片的票房新纪录。","各级政府需拿出真招、实招、硬招，让更多技能人才脱颖而出。"],"rel":""},{"w":"崭露头角","f":13,"def":"头上的角已明显地突出来了。指初显露优异的才能。作谓语、定语，含褒义。","key":"初次显露出才能（多指年轻人刚开始出头）","dim":"初显头角","egs":["近日，记者发现上海一批高学历、广视野、敢创新，且经过多年基层磨炼的年轻干部，正在崭露头角。","其中有德高望重的老专家，有成果丰硕的学术带头人，也有崭露头角的后起之秀。"],"rel":""},{"w":"出类拔萃","f":7,"def":"指出于那一类，超出那一群。比喻超出同类之上。多指人的品德、才能或事物优异性。含褒义，作谓语、定语。","key":"超出同类之上，形容才能、品德卓越（静态评价）","dim":"卓越出众","egs":["我们的大学生往往缺少出类拔萃的创新能力，也缺少精巧灵活的动手能力。","皮亚曼石榴之所以出类拔萃，是因为其独特的自然条件。"],"rel":""},{"w":"鹤立鸡群","f":6,"def":"像鹤站在鸡群中一样。比喻一个人的仪表或才能在周围一群人里显得很突出。（多指外貌方面）","key":"像鹤站在鸡群中，形容仪表或才能突出（多含外貌、气度）","dim":"外形突出","egs":["模特出生的瞿颖站在人群之后显得鹤立鸡群。","在里岭一幢幢旧屋群中，望燕楼真可谓“鹤立鸡群”。"],"rel":""}]},{"id":"g053","theme":"e-cause","label":"循序渐进／按部就班","words":["循序渐进","按部就班"],"rows":[{"w":"循序渐进","f":16,"def":"按照一定的步骤或程序逐渐推进或提高。常用于学习、工作中以及处理事情时。含褒义。","key":"按一定次序、步骤逐渐深入（学习、工作），强调“有序”","dim":"按序而进","egs":["国的传统文化博大精深，对于青年人而言，有必要循序渐进，以便逐步全面把握、深入理解。","坚持在大局稳定中推动发展，在开拓进取中筑牢根基，在循序渐进中破解难题。"],"rel":""},{"w":"按部就班","f":12,"def":"部：类别。班：次序。原指写文章按类别安排文义，按顺序组织文辞。后指按照一定的次序或部置进行。（中性词）","key":"按一定条理、步骤做事，中性；现多指按老规矩办事、缺乏创新","dim":"按部守成","egs":["学习应当按部就班，循序渐进。","落实上级部署时，存在机械执行、按部就班的情形。"],"rel":""}]},{"id":"g054","theme":"g-express","label":"蕴含／包含","words":["蕴含","包含"],"rows":[{"w":"蕴含","f":16,"def":"（动词）包含在内。","key":"包含在内（道理、情感、意味），多用于抽象、深层内容","dim":"内含深意","egs":["中国式现代化蕴含巨大发展机会。","典故是中华优秀传统文化中的瑰宝，集中蕴含着为人处世的道理，体现了治国理政的智慧。"],"rel":""},{"w":"包含","f":6,"def":"（动词）里面含有。","key":"里面含有（成分、内容、意思），最通用","dim":"通用含有","egs":["第二十四届冬季奥林匹克运动会圆满落幕，中国不仅兑现了承诺，凝聚起“一起向未来”的磅礴力量，也向世界交付了一份包含办赛经验、冰雪产业发展、绿色低碳实践，以及奥利匹克精神在内的丰厚奥运遗产。"],"rel":""}]},{"id":"g055","theme":"b-attitude","label":"坚定不移／坚忍不拔等3词","words":["坚定不移","坚忍不拔","矢志不渝"],"rows":[{"w":"坚定不移","f":16,"def":"形容立场、意志、主张等专一固定，毫不动摇。也指不放弃，不改变自己的想法。含褒义。","key":"立场、信念毫不动摇，强调“不变”","dim":"立场不动摇","egs":["在新时代，中国人民将继续自强不息、自我革新，坚定不移全面深化改革。","对于追求自己的梦想始终坚定不移，无论遇到多大的困难都从不放弃。"],"rel":"坚定"},{"w":"坚忍不拔","f":12,"def":"形容在艰苦困难的情况下信念坚定，意志顽强，不可动摇。作谓语、定语，含褒义。","key":"在艰苦困难中坚持而不屈服，强调“能扛”","dim":"坚韧能扛","egs":["百折不挠、坚忍不拔是中华民族的优秀品格。","巴中以刮骨疗伤的勇气、坚忍不拔的韧劲向这些问题叫板，坚决予以整治。"],"rel":"坚韧：坚固有韧性，不易摧毁。坚韧不拔"},{"w":"矢志不渝","f":8,"def":"矢：誓；渝：改变。指立下志愿，绝不改变。含褒义，作谓语、状语。同“矢志不移”。（侧重志向、誓言）","key":"立誓志向永不改变，多指理想、爱情、事业","dim":"志向不改","egs":["她要让大家知道，她的丈夫是无罪的，她要矢志不渝地等待着丈夫归来。","无数党员干部牺牲奉献，他们经千难而百折不挠、历万险而矢志不渝。"],"rel":""}]},{"id":"g056","theme":"i-verb","label":"遏制／遏止","words":["遏制","遏止"],"rows":[{"w":"遏制","f":15,"def":"（动词）制止，控制。（多形容控制在一定范围内）","key":"用力控制住，使之不能发展（势头、蔓延），不一定已停止","dim":"控制势头","egs":["反腐败斗争形势依然严峻复杂，遏制增量、清除存量的任务依然艰巨。","其抹黑中国、遏制打压中国的动机昭然若揭。"],"rel":""},{"w":"遏止","f":5,"def":"（动词）用力阻止，使停止。","key":"用力阻止，使之停止（多用于趋势、行为），程度更彻底","dim":"彻底阻止","egs":["遏止对儿童的家庭暴力刻不容缓。","用强制性国标遏止月饼市场乱象。"],"rel":""}]},{"id":"g057","theme":"c-extent","label":"浩如烟海／汗牛充栋等3词","words":["浩如烟海","汗牛充栋","卷帙浩繁"],"rows":[{"w":"浩如烟海","f":15,"def":"浩：广大。烟海：雾气弥漫的大海。形容事物（多指书籍、文献等）数量繁多，极其丰富。作谓语、定语。","key":"像烟雾弥漫的大海，形容文献、资料极多（多指书籍、典籍）","dim":"典籍众多","egs":["在这浩如烟海的汉字中，我们究竟需要掌握多少呢？","古今中外，人们的思想、文化、历史通过书籍代代传承，形成的书籍浩如烟海。"],"rel":""},{"w":"汗牛充栋","f":11,"def":"充：装满。栋：栋宇，房屋。书运输时牛累得出汗，存放时可堆至屋顶。形容书多。在句子中一般作谓语、定语，含褒义。","key":"书多到用牛运使牛出汗、堆满屋子，专指藏书、著作多","dim":"藏书极多","egs":["从古至今，汗牛充栋的著述中，关于“乐群”的论述与见解远远不止这些。","他是新中国第一代宪法学者，1953 年从教，著书立说汗牛充栋。"],"rel":""},{"w":"卷帙浩繁","f":3,"def":"形容书籍很多或一部书的篇幅很长。","key":"书籍篇章数量巨大，多形容丛书、巨著","dim":"篇幅浩大","egs":["此外，还应当看到，马克思留给后人的精神财富，不仅是卷帙浩繁的著作，还有感人至深的风范。","没有民法典时，法官审理民事案件，需要在卷帙浩繁的单行法律中寻找依据。"],"rel":""}]},{"id":"g058","theme":"h-quality","label":"客观／主观","words":["客观","主观"],"rows":[{"w":"客观","f":15,"def":"1．（形容词）不依赖主观意识而存在的（跟“主观”相对）。2．（形容词）按照事物的本来面目去考察，不加个人偏见的。（跟“主观”相对）","key":"不以人的意志为转移、从实际出发（客观规律、客观评价）","dim":"不依意志","egs":["规律是客观的，不以人们意志为转移。","既制造舆论，又监测、分析舆论，肯定不客观。"],"rel":"客观性"},{"w":"主观","f":10,"def":"（形容词）不依据实际情况，单凭自己的愿望、偏见（办事）。与“客观”相对。","key":"属于自我意识的、从自身出发的（主观臆断，含片面之意）","dim":"出于自我","egs":["每个人的审美都是主观的，所以不同的人对同一幅画可能有不同的评价。"],"rel":"主观性真题练习：16．在知识大爆炸的今天，不少人已习惯于浅阅读，这虽在所难免，其________也是明显的。浅阅读虽能够收获一些印象式的谈资，但________之中透露出的是浮躁心气，很难________为提升阅读者主体素质的扎实“文化准备”。依次填入画横线部分最恰当的一项是：A．代价   走马观花   转换       B．影响     浅尝辄止   汲取C．弊端   浮光掠影   沉淀       D．局限     言谈举止   锤炼17．文学翻译，尤其是经典文学的翻译，是特别专业的事情，需要锲而不舍的________、旁征博引的考证和________的付出才能做好。可惜绝大多数读者没有认识到这一点，他们当中有些人甚至对文学翻译有一种________的傲慢与偏见。依次填入画横线部分最恰当的一项是：A．追求   长年累月   理所当然     B．追寻     不离不弃   自以为是C．求索   持之以恒   根深蒂固     D．探求     聚精会神   前所未有18．晚清官员最害怕的就是和洋人直接打交道，他们中的绝大部分人不懂外语，不明世界大势，不知国际公法，在和洋人打交道时未免________，进退失据。对于日渐增多的华洋纠纷，他们处理起来更是________，稍有不慎，就会招来严重的外交纷争。因此，他们便普遍形成了一种“畏洋如虎”的心态。依次填入画横线部分最恰当的一项是：A．如履薄冰      捉襟见肘        B．瞻前顾后        手足无措C．左支右绌      力不从心        D．妄自菲薄        眼花缭乱19．市场经济最神奇也最让人________之处，就是市场中不同的主体通过自发的博弈与________而各得其所。对所谓完美、超然、成熟改革方案的渴望与膜拜，其实仍然是典型的计划思维，指望用一套方案打遍天下更是南辕北辙、________。依次填入画横线部分最恰当的一项是：A．奇特   取舍    刻舟求剑       B．惊喜     碰撞    离题万里C．赞叹   磨合    缘木求鱼       D．佩服     交汇    天壤之别20．计算机可以帮助学者在________的信息中快速发现和定位议题，新兴数字技术正在加速数字中国的构建进程，以数字媒介和人工智能为基础的新兴文化形态和知识生产体系正________，数字人文正在积极引领文化时空的数字化转换，并展现出广阔的发展前景。依次填入画横线部分最恰当的一项是：A．浩如烟海      如日中天        B．纷繁芜杂        日见雏形C．汗牛充栋      方兴未艾        D．鳞次栉比        如火如荼                    第五天"}]},{"id":"g059","theme":"i-verb","label":"控制／掌控","words":["控制","掌控"],"rows":[{"w":"控制","f":15,"def":"1．（动词）掌握住对象不使任意活动或超出范围。2．（动词）使处于自己的占有、管理或影响之下。","key":"掌握住不使任意活动或越出范围（控制规模、情绪、疫情）","dim":"约束范围","egs":["目前，我国本轮疫情已经得到有效控制。","另外，还应该注意戒烟限酒，控制体重，少熬夜。"],"rel":""},{"w":"掌控","f":5,"def":"（动词）掌握控制。核心语义为对事物的控制权与主导权。","key":"掌握、控制（局面、局势、节奏），更强调“主动权在手”","dim":"握主动权","egs":["置身现场亲身感受国家发展的磅礴力量与国防现代化的伟大成就，更坚定了我们掌控关键核心技术、走自主创新道路的信念。"],"rel":"掌控者"}]},{"id":"g060","theme":"e-cause","label":"墨守陈规／因循守旧等5词","words":["墨守陈规","因循守旧","闭门造车","画地为牢","抱残守缺"],"rows":[{"w":"墨守陈规","f":15,"def":"指思想保守，守着老规矩不肯改变。含贬义，在句中一般作谓语、定语。同“墨守成规”、“固守陈规”。","key":"守着老规矩不肯改变（贬义，强调“守旧”）","dim":"守旧不改","egs":["在改革和创新的时代，企业在参与市场竞争过程中应有灵活处理各种问题的能力，不能墨守陈规。","同学们绝对不能把知识学成负担，切莫把能力训练成墨守陈规的呆板。"],"rel":""},{"w":"因循守旧","f":13,"def":"死守老一套，缺乏创新的精神。含贬义。","key":"沿袭旧例、不思创新（贬义，强调“沿袭”）","dim":"沿袭旧例","egs":["工匠精神不是因循守旧、拘泥一格的“匠气”，而是在坚守中追求突破、实现创新。","要与时俱进，不要因循守旧。"],"rel":""},{"w":"闭门造车","f":9,"def":"原指由于规格相同，关起门来造成的车子，用起来也能合辙。现在比喻不管客观情况如何，只凭主观愿望办事。含贬义。","key":"关起门来造车，比喻脱离实际、只凭主观办事","dim":"脱离实际","egs":["广义的开放没有问题，不能闭门造车，不能单打独斗，不能不学习人家的先进技术。","解放思想不是脱离国情的异想天开，也不是闭门造车的主观想象，更不是毫无章法的莽撞蛮干。"],"rel":""},{"w":"画地为牢","f":8,"def":"牢：牢狱。在地上画个圈儿，作为牢狱。比喻局限在小圈子里活动。作谓语、宾语。","key":"在地上画圈当牢房，比喻只许在指定范围内活动、自我限制","dim":"自我设限","egs":["当前互联网企业为维护自身市场优势地位，正纷纷“画地为牢”，平台内自我导流，对竞争对手选择性屏蔽。","任何国家画地为牢、搞单边主义和保护主义，都将损害世界现代化进程。"],"rel":""},{"w":"抱残守缺","f":8,"def":"残、缺：不完整。1．固守陈旧残缺的东西不放，形容保守，不知改进。2．保存虽有残缺但仍有价值的古物。","key":"守着残缺陈旧的东西不放，形容保守不知改进","dim":"保守残缺","egs":["在一切学术领域里，都需要参考、借鉴外国的成就，抱残守缺、固步自封是不行的。","如果不能在保护与修复中保存文物的历史、科学、艺术等价值，还不如抱残守缺，让其静静展现其历史的真实。"],"rel":""}]},{"id":"g061","theme":"g-express","label":"培育／孕育等3词","words":["培育","孕育","培养"],"rows":[{"w":"培育","f":15,"def":"1．（动词）培养幼小的生物，使它发育成长。2．（动词）培养教育。","key":"培养幼小的使之发育成长（品种、人才、市场），含“精心抚育”","dim":"精心抚育","egs":["积极培育新能源、新材料、先进制造、电子信息等战略性新兴产业。","我们培育的时代新人，一定要立鸿鹄志，做坚定者。"],"rel":""},{"w":"孕育","f":15,"def":"（动词）怀胎生育，比喻在既存的事物中酝酿着新事物。","key":"怀胎生育，比喻既存事物中酝酿产生新事物（含“酝酿”过程）","dim":"酝酿生成","egs":["交叉融合是医学基础研究中孕育新发现的“摇篮”。","黄河宛如一条奔腾不息的巨龙，孕育了中华民族悠久的文化。"],"rel":""},{"w":"培养","f":8,"def":"（动词、名词）以适宜的条件促使其发生、成长和繁殖，也指按照一定的目的长期地教育和训练，使其成长。","key":"按一定目的长期教育训练使之成长（人才、习惯、能力）","dim":"教育训练","egs":["普通细菌的培养至少需要一天时间，厌氧菌可能需要 72 个小时。","培养什么人，是教育的首要问题。"],"rel":""}]},{"id":"g062","theme":"a-speed","label":"如火如荼／欣欣向荣等4词","words":["如火如荼","欣欣向荣","生机勃勃","蒸蒸日上"],"rows":[{"w":"如火如荼","f":15,"def":"荼：茅草、芦苇之类植物的白花。原形容军容盛大，后用来形容气势盛大或气氛、情感热烈。含褒义。（常搭配发展、建设、活动等，侧重热闹）","key":"像火那样红、像荼那样白，形容气势旺盛、气氛热烈（多指运动、建设）","dim":"气氛热烈","egs":["金秋十月，在农网改造施工现场，举目可见忙碌着的电力施工人员，他们在如火如荼地进行农网改造升级施工。","这一年，数据产业发展如火如荼，日益成为加快建设数字中国的重要支撑。"],"rel":""},{"w":"欣欣向荣","f":9,"def":"指草木长的茂盛，生机勃勃的样子。后用于比喻事业蓬勃发展，兴旺昌盛的景象。含褒义，在句中一般作谓语、定语。（常搭配事业、国家等）","key":"草木长得茂盛，比喻事业蓬勃发展、充满生机","dim":"充满生机","egs":["这样普普通通的场景向世人证明，在文化体制改革不断深入的历史进程中，文化事业欣欣向荣，文化产业蓬勃发展。","放眼欣欣向荣的中华大地，江山壮丽，人民豪迈，前程远大。"],"rel":""},{"w":"生机勃勃","f":9,"def":"1．形容自然界充满生命力的样子。2．形容社会生活活跃。作谓语、定语，含褒义。","key":"生命力旺盛、充满活力（多形容自然、景象、局面）","dim":"活力充沛","egs":["米林植被茂密、生机勃勃，远处群山连亘。","生机勃勃的中华大地，澎湃着向上向前的磅礴力量。"],"rel":"勃勃生机"},{"w":"蒸蒸日上","f":8,"def":"蒸蒸：热气上升的样子。形容一天天地向上发展，进展很快。作谓语、定语，含褒义。（常搭配事业、国家、人民生活等）","key":"一天天向上发展，形容事业、生活繁荣兴旺","dim":"蒸腾向上","egs":["30 多年来，中国的发展，北京的成长，让世人看到了中国的实力。与此同时，中国的体育事业也蒸蒸日上。","越来越多外出务工的村民选择返乡，一个个富民产业风生水起，乡村发展蒸蒸日上。"],"rel":""}]},{"id":"g063","theme":"c-extent","label":"栩栩如生／惟妙惟肖等4词","words":["栩栩如生","惟妙惟肖","活灵活现","绘声绘色"],"rows":[{"w":"栩栩如生","f":15,"def":"形容生动逼真，就像活的一样，多指文学、艺术作品描摹、刻画人或物的形象十分生动逼真。含褒义。","key":"艺术形象非常逼真，像活的一样（多指绘画、雕塑等造型艺术）","dim":"形象逼真","egs":["不出一刻钟，一只栩栩如生、威风神气的龙头就成型了。","众多人物汇聚图上，虽微小如蚁，却姿态各异，栩栩如生。"],"rel":""},{"w":"惟妙惟肖","f":11,"def":"形容描写或模仿得非常逼真，生动形象。","key":"模仿或描摹得非常逼真，重“像”（可指表演、模仿）","dim":"模仿逼真","egs":["杂技节目惊险奇美、二胡演奏婉转悠扬、口技表演惟妙惟肖……2．延安整风时期，他用泥菩萨惟妙惟肖地刻画了官僚主义者的形象特征。","当天展出的作品画的是《水浒传》里的人物，笔触细腻，惟妙惟肖。"],"rel":""},{"w":"活灵活现","f":7,"def":"形容神情逼真、传神，使人有亲眼所见的感觉。作谓语、定语、状语。","key":"形容描述、模仿得神情逼真（多指说话、描写出的形象）","dim":"神情逼真","egs":["在队员们的操控下，一条彩龙时而盘旋，时而昂首，在阳光下活灵活现、栩栩如生。","一道道精心细致的工序之后，一张活灵活现的杨柳青年画热热闹闹地呈现在人们眼前，平添了一份节日的喜庆。"],"rel":""},{"w":"绘声绘色","f":7,"def":"绘：描绘。把人物的声音、神色都描绘出来了。形容叙述、描述得生动逼真。同“绘声绘影”、“绘影绘声”。（多修饰语言）","key":"叙述、描写生动逼真，重“讲得生动”（只用于言谈、文章）","dim":"叙述生动","egs":["报告会上，解放军的战斗英雄绘声绘色地讲述着战斗经过。","打竹板、唱鼓书、二重唱……只要群众喜欢什么，他们就用什么形式将一条条严肃的理论宣传，讲得绘声绘色。"],"rel":""}]},{"id":"g064","theme":"e-cause","label":"因势利导／顺势而为","words":["因势利导","顺势而为"],"rows":[{"w":"因势利导","f":15,"def":"指顺着事情发展的趋势向有利的方向引导。含褒义。","key":"顺着事情发展趋势加以引导，使之走向有利（含“主动引导”）","dim":"顺势引导","egs":["反向情绪是一股需要因势利导的细流，虽然细流本身并不可怕，但不积小流何以成江海。","只有因势利导引领变化，自觉同安于现状、不思进取、不敢斗争、贪图享乐的现象作斗争，才能永葆先进性和纯洁性。"],"rel":""},{"w":"顺势而为","f":6,"def":"顺应形势做事情。同“顺势而行”。","key":"顺着形势发展去做（强调不逆势、借力而行）","dim":"借势而行","egs":["我们要因势而谋、应势而动、顺势而为，快推动媒体融合发展。","移动互联网时代，用户的消费场景革命已经悄悄带来了很多消费可能性，如何顺势而为地打造爆款产品？"],"rel":"顺势而行"}]},{"id":"g065","theme":"e-cause","label":"应运而生／异军突起等4词","words":["应运而生","异军突起","横空出世","粉墨登场"],"rows":[{"w":"应运而生","f":15,"def":"应运：应天命。指顺应天命而降生。后泛指顺应时机而产生。（需满足两个条件：顺应背景+新产生）","key":"顺应时机、形势而产生（多指新事物、新业态）","dim":"顺应时机","egs":["现代经济学已经失灵，适应信息时代的新型经济学将应运而生。"],"rel":""},{"w":"异军突起","f":11,"def":"异军：另一支军队。比喻与众不同的新派别或一支新生力量突然一下子崛起。","key":"另一支军队突然兴起，比喻新的力量、派别突然崛起","dim":"新力量崛起","egs":["近几年，作为“国潮”兴起的赛道之一，新中式餐饮异军突起。","观察这些异军突起的企业，就是心无旁骛、一以贯之、做强主业。"],"rel":""},{"w":"横空出世","f":6,"def":"形容人或物高大，横在空中，浮出人世。或比喻卓尔不群，十分优秀。","key":"突然出现、气势不凡（多用于作品、人物、重大成果）","dim":"突然而出","egs":["四十载波澜壮阔，一批批拓荒者、先行者、攻关者，闯关夺隘、攻坚克难，让一串串惊世奇迹横空出世。","1848 年，两个年轻人共同撰写的《共产党宣言》横空出世。"],"rel":""},{"w":"粉墨登场","f":5,"def":"粉墨：傅粉施墨，指化妆。场：戏场，舞台。1．化好妆登台演戏（中性词）。2．比喻坏人登上政治舞台。也比喻不良事物乔装打扮后出台。（贬义词）。作谓语。","key":"化装上台演戏，现多比喻坏人登上政治舞台（贬义）","dim":"贬义登场","egs":["戏迷票友粉墨登场，台上台下热情互动，掌声不断。","一所饭店内，十天封锁，各路势力粉墨登场，尔虞我诈。"],"rel":""}]},{"id":"g066","theme":"a-speed","label":"此起彼伏／此消彼长","words":["此起彼伏","此消彼长"],"rows":[{"w":"此起彼伏","f":14,"def":"这里起来，那里落下。形容接连不断。同“此起彼落”。作谓语、定语。（多形容声音或事物发展连续不断）","key":"这里起来、那里落下，连续不断（声音、浪潮、斗争）","dim":"交替不断","egs":["近几年，电视剧的改名现象此起彼伏。","会场上，铿锵的声音穿透此起彼伏的掌声，回荡久远。"],"rel":""},{"w":"此消彼长","f":10,"def":"指这个下降，那个上升。","key":"这个下降、那个上升，两者互为消长（力量、势力对比）","dim":"一消一长","egs":["传统媒体和新兴媒体融合发展，不是一个此消彼长的概念，而是此长彼长的过程。","公与私如同天平的两端，此消彼长。"],"rel":""}]},{"id":"g067","theme":"i-verb","label":"拓展／开拓","words":["拓展","开拓"],"rows":[{"w":"拓展","f":13,"def":"（动词）开拓发展。（多形容面积、范围上）","key":"在原有基础上向外扩展、拓宽（领域、空间、业务）","dim":"向外拓宽","egs":["进一步拓展区域合作领域。","拓展系统化工作思路。"],"rel":""},{"w":"开拓","f":8,"def":"（动词）指从小到大地发展，开辟扩大。（对象一般是范围较大的）","key":"开辟、扩展（新领域、新市场、新局面），含“从无到有”","dim":"开辟新境","egs":["精彩的故事、新鲜的题材、精湛的制作，再配上多样化的经营业态，才能不断开拓电影消费新空间。","维护和开拓市场，从本质上讲，就是在增加效益。"],"rel":"开拓者"}]},{"id":"g068","theme":"c-extent","label":"叹为观止／拍案叫绝","words":["叹为观止","拍案叫绝"],"rows":[{"w":"叹为观止","f":14,"def":"叹：赞叹。观止：看到这里就停止，不再看别的了。称赞所看的事物尽善尽美。赞美所看到的事物好到了极点。（主语是人）","key":"赞叹所见事物好到极点（褒义，对象是看到的事物）","dim":"赞到极点","egs":["我们这些平凡人，只能叹为观止。","早在新石器时代，这里的人们便在这块土地上创造了辉煌灿烂的贾湖文化和令人叹为观止的古迹遗存。"],"rel":""},{"w":"拍案叫绝","f":6,"def":"拍着桌子叫好。形容情不自禁地极力称赞。","key":"拍桌子叫好，形容非常赞赏（多指对诗文、技艺）","dim":"击节赞赏","egs":["川剧变脸《智幻华彩》让人拍案叫绝，板胡独奏《喜洋洋》引得全场观众随节拍鼓掌。","海派巨擘任伯年对吴昌硕以石鼓文的篆法入画拍案叫绝，并预言其必将成为画坛的中流砥柱。"],"rel":""}]},{"id":"g069","theme":"g-express","label":"挖掘／发掘","words":["挖掘","发掘"],"rows":[{"w":"挖掘","f":14,"def":"（动词）从深处挖出来。","key":"从深处挖出；比喻深入发现、探求（潜力、内涵、素材）","dim":"深入挖潜","egs":["讲好品牌故事，挖掘文化底蕴。","坚持改革创新，挖掘增长潜力。"],"rel":""},{"w":"发掘","f":13,"def":"1．（动词）挖掘埋藏在地下的东西。2．（动词）比喻把潜在、埋没的东西挖掘出来。","key":"把埋藏的东西挖出来；比喻发现、揭示（人才、价值、遗址）","dim":"发现揭示","egs":["深入发掘长江文化的时代价值，推出更多体现新时代长江文化的文艺精品。","工作人员正在对人字洞遗址进行考古发掘。"],"rel":""}]},{"id":"g070","theme":"b-attitude","label":"本末倒置／舍本逐末","words":["本末倒置","舍本逐末"],"rows":[{"w":"本末倒置","f":13,"def":"本：树根。末：树梢。比喻把事情的轻重主次颠倒了过来。","key":"把根本和枝节弄颠倒了，强调主次颠倒","dim":"主次颠倒","egs":["搞政治理论和业务学习，却以“停止办公”之举直接违背这个最基本的“政治理论”，实在是本末倒置。","现实中也有人本末倒置，把“打卡”获赞当成了一种满足自我虚荣心的途径。"],"rel":"轻重倒置"},{"w":"舍本逐末","f":12,"def":"放弃根本的而追求枝节的，后用以比喻轻重主次颠倒，做事不从根本的、主要的问题着手，而只在细枝末节上用力气。含贬义。","key":"舍弃根本、追求枝节，强调“放弃根本”","dim":"舍本求末","egs":["盖豪华厕所不过是舍本逐末的政绩秀。","在媒体融合中，不要舍本逐末，不能丢了内容生产这个核心。"],"rel":""}]},{"id":"g071","theme":"c-extent","label":"不胜枚举／比比皆是等6词","words":["不胜枚举","比比皆是","数不胜数","俯拾皆是","不计其数","不一而足"],"rows":[{"w":"不胜枚举","f":13,"def":"无法一一全举出来，形容数量很多。多用于列举的场合。","key":"无法一一列举，形容同类事物很多","dim":"多到难列","egs":["中国的名胜古迹不胜枚举，从雄伟的故宫到壮丽的黄山，每一处都令人流连忘返。","这样的例子不胜枚举。"],"rel":""},{"w":"比比皆是","f":12,"def":"到处都是，形容极其常见。作谓语、定语，用于人和物。","key":"到处都是，形容数量多、分布广","dim":"到处都是","egs":["美国肆意干涉他国内政的事例比比皆是。","比比皆是的隐私泄露事件令人不寒而栗。"],"rel":""},{"w":"数不胜数","f":11,"def":"数都数不过来。形容数量极多，很难计算。","key":"数也数不过来，形容数量极多","dim":"数不清","egs":["翻开人民军队战史，胜利数不胜数。","名目繁多的检查、评比、考核，数不胜数的重复报表、材料，表面上轰轰烈烈，声势浩大，基层干部也是整天忙得团团转，老百姓却见不到实惠。"],"rel":"不可胜数"},{"w":"俯拾皆是","f":10,"def":"只要低下头来捡取，到处都是，形容多而易得。","key":"弯下腰就能捡到，形容数量极多、随处可得（多指细小事物、例证）","dim":"随处可得","egs":["古诗词中反映园林借景的俯拾皆是。","体验奎壁山的摩西分海、赤足轻踏细软白纱、丰富刺激的海上活动以及俯拾皆是的贝壳与珊瑚礁石……"],"rel":"俯拾即是、俯仰可拾"},{"w":"不计其数","f":8,"def":"没法计算数目。形容很多。作谓语、定语，中性词。","key":"无法计算数目，形容极多（多含“损失、数量”意味）","dim":"无法计算","egs":["如今，不计其数的 80 后、90 后甚至 00 后活跃在科研一线，在科技创新的赛道上激扬青春、成就梦想。","为了快速通过，有些国民党军官甚至用机枪开道，手无寸铁的百姓死伤不计其数。"],"rel":""},{"w":"不一而足","f":4,"def":"不是一事一物能够使之满足的。后也用来形容所说的事物或现象不止一种，而是很多，不能一一列举。作谓语、分句。用于句尾。","key":"不止一种或一次，而是很多（多指同类事物列举不尽）","dim":"种类繁多","egs":["最近一些地方上的调查表明，社会上各种学会、协会层出不穷，联谊会、研究会不一而足。","有的眼见无利不想为，有的本领恐慌不会为，有的担当缺乏不敢为，有的得过且过无所为，凡此种种，不一而足。"],"rel":""}]},{"id":"g072","theme":"g-express","label":"传播／传递等3词","words":["传播","传递","传达"],"rows":[{"w":"传播","f":13,"def":"（动词）广泛散布。","key":"广泛散布（信息、疾病、文化），强调“扩散范围”","dim":"广泛扩散","egs":["蜜蜂在采花蜜的时候，也为这些植物传播了花粉。","虱子传播疾病。"],"rel":""},{"w":"传递","f":8,"def":"（动词、名词）由一方交给另一方，辗转递送。","key":"一个接一个地递送（信息、情感、火炬），强调“接力交付”","dim":"接力递送","egs":["本次亚冬会火炬传递还设计了线上部分，让更多人突破时间与空间限制，参与到这一体育文化活动中来。","网络的美好未来需要我们积极传递正能量。"],"rel":""},{"w":"传达","f":6,"def":"1．（动词）把一方的意思告诉给另一方。2．（动词）机关、学校、工厂等门口管理登记和引导来宾的工作。","key":"把上级的意思转告下级，或表示（情感、意味），多为单向","dim":"上传下达","egs":["经理在会议上向员工们传达了公司的最新决策和未来的发展方向。","工厂门口的传达员严谨地管理着出入人员，确保工厂的安全与秩序。"],"rel":""}]},{"id":"g073","theme":"h-quality","label":"多元／多样","words":["多元","多样"],"rows":[{"w":"多元","f":13,"def":"（形容词）多样的，不单一的。","key":"多主体、多角度、多层次并存（多元文化、多元主体）","dim":"多主体并存","egs":["在漫长的历史发展中，我国各民族相互依存、休戚与共、水乳交融，形成了中华民族多元一体的格局。","面对多元化的社会，青年难免在各种思潮中产生思想的困惑、选择的焦虑。"],"rel":"多元化、多元性"},{"w":"多样","f":11,"def":"（形容词）描述事物具有多方面特性或丰富变化。","key":"种类、形式多而不同（形式多样、生物多样性）","dim":"种类形式多","egs":["在这个多元化的社会，文化的多样性使得我们的生活更加丰富多彩。"],"rel":"多样化、多样性"}]},{"id":"g074","theme":"i-verb","label":"放弃／摒弃","words":["放弃","摒弃"],"rows":[{"w":"放弃","f":13,"def":"（动词）不坚持或丢掉原有的（原则、权利、主张等）。","key":"丢掉（原有的权利、主张、机会），中性","dim":"中性舍弃","egs":["发展新质生产力不是忽视、放弃传统产业。","因“维权难”便放弃维权，乃至放弃发表作品，这就带有一定的“赌气”成分。"],"rel":""},{"w":"摒弃","f":9,"def":"（动词）舍弃，丢弃。（多用于搭配不好的东西）","key":"坚决排除、抛弃（多指错误的、不好的东西），含主动排斥","dim":"坚决排除","egs":["面对利益复杂的中国，推进治理体系和治理能力现代化，最需要我们摒弃简单化思维。","战胜这场疫情乃至接下来的种种冲击，需要我们摒弃分裂与偏见、坚持团结与合作。"],"rel":""}]},{"id":"g075","theme":"i-verb","label":"忽视／审视等3词","words":["忽视","审视","重视"],"rows":[{"w":"忽视","f":13,"def":"（动词）不注意，不重视。（可以是主观故意，也可以是无意）","key":"疏忽、不注意（无意造成，多含批评）","dim":"无意疏忽","egs":["在高速发展的城市化建设进程中，高龄农民工贡献了青春和热血，他们令人敬佩，却容易被忽视。","“故意忽视”教育就是在孩子无理取闹、又处在安全的地方时，对他们进行的一种“放任不管”的教育方法。"],"rel":""},{"w":"审视","f":12,"def":"（动词）仔细地看。","key":"仔细看、认真端详（含分析和判断）","dim":"仔细察看","egs":["无论从任何角度审视中美关系，都能发现中美之间有着广泛共同利益。","改革开放 40 年之际，人们都在从不同的角度审视和思考。"],"rel":""},{"w":"重视","f":12,"def":"（动词、名词）认为很重要而认真对待。","key":"认为重要而认真对待（与“忽视”相对）","dim":"看重","egs":["教育是国家发展的基石，我们每个人都应该重视教育，为国家的未来贡献力量。","领导多次在不同场合表达对冰雪运动的重视，强调持续推进冰雪运动发展。"],"rel":""}]},{"id":"g076","theme":"h-quality","label":"良莠不齐／鱼龙混杂等6词","words":["良莠不齐","鱼龙混杂","泥沙俱下","鱼目混珠","参差不齐","滥竽充数"],"rows":[{"w":"良莠不齐","f":13,"def":"莠：狗尾草，比喻坏人。指好的、坏的混在一起。同“良莠不一”。作谓语、定语。（可形容人，也可形容事物）","key":"好人坏人混杂（专指人的品质好坏不一）","dim":"人品不一","egs":["目前，处在发展初期的微短剧内容良莠不齐，在带来大流量的同时，也存在剧情套路化、部分内容低俗化的问题。","随着留学之风愈刮愈烈，留学生队伍也更显良莠不齐。"],"rel":""},{"w":"鱼龙混杂","f":11,"def":"比喻各色各样的人混在一起，成分复杂，好坏难分。作谓语、定语。（现在用法不止形容人，也可形容事物）","key":"鱼和龙混在一起，专指好人坏人混杂","dim":"人鬼混杂","egs":["以前的艺术批评地位非常高，也很自律；现在的批评界则是鱼龙混杂、门槛太低。","从业人员鱼龙混杂，服务水平参差不齐。"],"rel":""},{"w":"泥沙俱下","f":9,"def":"指在江河的急流中泥土和沙子随着水一起冲下。比喻好的坏的混杂在一起。作谓语、定语，中性词。可以用于人或事物（用于人的语境比较少见）。","key":"泥土和沙子一起流下，比喻好坏不同的人或事物混杂在一起","dim":"好坏混杂","egs":["作为新模式新业态，直播行业快速发展难免泥沙俱下。","在众声喧哗的舆论格局下，在泥沙俱下的信息潮流中，把弘扬主旋律作为新闻宣传的一条主线、一种底色，叫得更响亮、亮得更鲜明。"],"rel":""},{"w":"鱼目混珠","f":7,"def":"拿鱼的眼睛掺杂在珍珠里面。比喻以假乱真，以次充好。含贬义。","key":"拿鱼眼当珍珠，比喻以假乱真、以次充好","dim":"以假充真","egs":["近年来，少数不法分子用染色的玉米须冒充藏红花，用苹果皮代替牡丹片，甚至用淬取后的药渣“鱼目混珠”，让消费者防不胜防。","对那种肆意妄为、横冲直闯的“三敢干部”，应引起高度警惕，谨防他们鱼目混珠、带病提拔。"],"rel":""},{"w":"参差不齐","f":5,"def":"参差：高低、长短、大小不齐的样子。形容很不整齐或水平不一。（多搭配水平、质量、进展等）","key":"长短高低不一致，泛指水平、质量、规模等不一致","dim":"水平不一","egs":["记者发现，虽说众多政府机构和部门都已开通了微博，但政务微博的运营情况良莠不齐，影响力参差不齐。","目前，宣称可用于儿童的化妆品琳琅满目，但质量安全水平参差不齐。"],"rel":""},{"w":"滥竽充数","f":5,"def":"滥：失实，不真实。竽：一种簧管乐器。比喻没有真实本领的人，混在行家队伍里充数。也比喻以次充好。（可用于自谦）","key":"不会吹竽的人在乐队中充数，比喻没有真才实学的人混在内充数","dim":"无才充数","egs":["教学是一个综合性的技能，没有专业资格证的人代表水平达不到，一旦遇到外籍教师中的滥竽充数者，学生很难获得高质量教学成果。","文具盲盒和其他盲盒一样，已经形成了热潮，但要警惕三无产品滥竽充数。"],"rel":""}]},{"id":"g077","theme":"i-verb","label":"契合／符合等4词","words":["契合","符合","迎合","吻合"],"rows":[{"w":"契合","f":13,"def":"1．（动词）十分符合。2．（形容词）意气相投。","key":"彼此相符、完全投合（理念、需求、心思）","dim":"彼此投合","egs":["中国不遗余力推动经济高质量发展，契合国际社会共同期待。","无论是探讨人生哲学还是分享日常琐事，都能感受到彼此的默契与理解，这种契合让我们在人生旅途中成为了不可或缺的伙伴。"],"rel":""},{"w":"符合","f":9,"def":"（动词）与存在的式样、形式或标准一致、相合。","key":"与（标准、规定、事实、利益）相一致，最通用","dim":"符合标准","egs":["中国式现代化是符合中国国情的正确道路。","续签《中美科技合作协定》符合两国人民利益。"],"rel":""},{"w":"迎合","f":7,"def":"（动词）有意使自己的言行或举动适合别人心意。","key":"有意使自己的言行投合别人的心意（多含贬义，讨好）","dim":"曲意讨好","egs":["市场经济的压力使得许多艺术工作者不得不迎合商业化的需求，导致艺术作品的创作质量下降。","新的产品要迎合消费者的喜好，才能占有市场。"],"rel":""},{"w":"吻合","f":6,"def":"（形容词）完全符合，一致。","key":"完全一致（数据、说法、尺码），强调“对得上”","dim":"完全对上","egs":["曹氏后人和曹操叔祖父曹鼎的 DNA 检测是否吻合，是复旦大学课题组双重验证法的关键一环。","习近平主席即将对美国进行的国事访问吻合了一个重要的历史节点：中国人民抗日战争暨世界反法西斯战争胜利 70 周年和联合国成立 70 周年。"],"rel":""}]},{"id":"g078","theme":"b-attitude","label":"适得其反／事与愿违","words":["适得其反","事与愿违"],"rows":[{"w":"适得其反","f":13,"def":"恰好得到与愿望相反的结果。含贬义，在句中一般作谓语、定语。","key":"结果与愿望正好相反（多因方法不当导致）","dim":"结果相反","egs":["如果从“便民”变为“碍民”，酒店智能化改造将适得其反。","如果不顾实际情况“一刀切”，可能会造成适得其反的工作效果。"],"rel":""},{"w":"事与愿违","f":7,"def":"事：事实。愿：心愿，愿望。事情的发展结局与主观愿望相违背。形容事情不能称心如意。作谓语、定语，含贬义。（侧重没达到）","key":"事情的发展与愿望相违背","dim":"愿望落空","egs":["本想做了手术以后，他的身体会好起来的，但事与愿违，他的身体还是一天天地衰弱下去。","因在新旧实践之间左右摇摆、飘忽不定而偏离高质量发展轨道，致使不对路子的举动时有发生，甚至重蹈高速增长覆辙，搞出一些事与愿违、南辕北辙的事情来。"],"rel":""}]},{"id":"g079","theme":"a-speed","label":"演变／演化等5词","words":["演变","演化","嬗变","蜕变","演进"],"rows":[{"w":"演变","f":13,"def":"（动词、名词）指历时较久的发展变化。","key":"发展变化（多指长期、整体的历史过程）","dim":"长期演化","egs":["中国人民解放军军旗经历了从工农革命军军旗、中国工农红军军旗到中国人民解放军“八一”军旗的历史演变过程。","随着互联网的快速发展，内容创作的形式和内容也在不断演变。"],"rel":""},{"w":"演化","f":7,"def":"（动词、名词）演变（多指自然界的变化）。","key":"自然发展、进化（生物、宇宙、制度）","dim":"自然进化","egs":["人类社会的演化经历了从狩猎采集到农业文明，再到工业化和信息化的过程。","真实性的概念是一个不断发展和演化的过程。"],"rel":""},{"w":"嬗变","f":5,"def":"1．（名词、动词）演变。2．（名词、动词）彻底的改变。","key":"演变、蜕变（多指社会、制度、观念的深刻变化），书面性强","dim":"深刻蜕变","egs":["尊法、学法、守法和用法是守法层次递进嬗变的过程表现。","随着科技的飞速发展，人们的生活方式正在经历着深刻的嬗变。"],"rel":""},{"w":"蜕变","f":5,"def":"（动词、名词）本指蝉蜕壳变。后比喻（人或事物）发生质变。中性词。","key":"（人或事物）发生质的变化，可指向好的也可指向坏的","dim":"质变","egs":["厦门市思明区东坪山公园内，一只蝉在石壁上完成了蜕变。","这些累积的航迹，如同不断叠加的“海上年轮”，每一圈都记录着水兵们战风斗浪的成长与蜕变。"],"rel":""},{"w":"演进","f":4,"def":"（动词、名词）事物随时间推移逐渐演变发展的过程。强调事物在时间维度上的持续性优化。","key":"逐步向前发展（过程、潮流、学说），强调“向前推进”","dim":"向前推进","egs":["新质生产力代表先进生产力的演进方向，向“新”而行的中国经济将行稳致远，为全球发展增添新活力、注入新动能。","艺术门类的发展与演进，既要靠传统经典的重新演绎，还须有立足时代的创作。"],"rel":""}]},{"id":"g080","theme":"d-relation","label":"依托／依附","words":["依托","依附"],"rows":[{"w":"依托","f":13,"def":"（动词、名词）依靠，凭借。","key":"靠、凭借（依托优势、依托平台），中性","dim":"凭借依靠","egs":["依托独特的文学资源，近年来，西吉县擦亮“文学之乡”金字招牌。","他想以近海为依托，大力发展水产养殖业。"],"rel":""},{"w":"依附","f":6,"def":"（动词）依赖，附着。","key":"附属于他人或他物而不能自立（含丧失独立性）","dim":"失去自立","egs":["水蒸气必须依附在灰尘上，才能凝结成小水滴。","城市往往因为文化而文明，文明又往往依附于其在悠远历史长河中所形成的独有文化。"],"rel":"依附性真题练习：26．在这个经济高速发展的时代，工作________着我们的业余时间。工作与家的关系，不是非得舍弃哪一方才能成全另一方，而是可以兼顾的，我们不能________，忽略生命中最珍贵的东西，而在未来老去时空留悔恨和遗憾。依次填入画横线部分最恰当的一项是：A．占据   三心二意             B．消磨     本末倒置C．侵占   半途而废             D．蚕食     舍本逐末27．向民众________科学知识，________科学精神，是科学家义不容辞的责任。但是科学家首先要致力于科研，他究竟能花多少时间来做科普，显然无法一概而论。通常，一线科学家很难花费太多的时间和精力直接参与一波又一波的科普活动。依次填入画横线部分最恰当的一项是：A．传输   传递               B．传递     传播C．传导   传扬               D．传达     传承28．文旅开发需注重对古镇自然环境的呵护，避免简单________其他文旅项目大广场、大草坪、大展馆等设计，应当留住古镇清幽、古朴的历史风貌，而大规模迁移原住居民、过度引入商业设施的开发模式，已经让众多注重旅游体验的游客“用脚投票”，尤当________。依次填入画横线部分最恰当的一项是：A．移植   引以为戒               B．复制     居安思危C．参考   防微杜渐               D．借鉴     慎之又慎29．化工企业在环保治理和达标排放上的确存在着________的现象，少数企业偷排乱放严重污染了当地环境，败坏了化工行业的________。专家认为，对这种违法企业无论怎样处罚都不为过，但是，简单粗暴的“一刀切”会让企业________，正常的生产运营受到严重影响，这有悖环保风暴的初衷。依次填入划横线部分最恰当的一项是：A．愈演愈烈      风气    分崩离析    B．良莠不齐        声誉    人人自危C．竭泽而渔      道德    如履薄冰    D．变本加厉        操守    难以为继30．稳定的体温是恒温动物适应复杂多变环境的重要生理基础。恒温动物可以利用自身代谢________体温、维持体温________，进而拓展生存空间。长期以来，恒温曾被认为是哺乳类和鸟类所特有的。近年来，越来越多的研究发现恒温在其他脊椎动物谱系中同样存在，仅在鱼类中就至少独立________了六次。依次填入画横线部分最恰当的一项是：A．改变   稳固    演变           B．调整     固定    进化C．控制   恒定    演绎           D．调节     稳定    演化                        第七天"}]},{"id":"g081","theme":"g-express","label":"折射／映射等4词","words":["折射","映射","投射","反射"],"rows":[{"w":"折射","f":13,"def":"1．（动词）光线、无线电波、声波等从一种介质进入另一种介质时传播方向发生偏折。2．（动词）比喻把事情的表象或实质表现出来。中性词。","key":"光线穿过不同介质改变方向；比喻曲折地反映（社会变迁、心态）","dim":"间接反映","egs":["钻石的闪耀光芒是由于光线在其内部发生多次折射和反射所造成的。","释放消费活力，折射美好生活日新月异。"],"rel":""},{"w":"映射","f":11,"def":"1．（动词）照射。2．（动词）反射，反映。（多抽象语境）","key":"映照投射（光线、数学上的对应关系）","dim":"投射对应","egs":["阳光映射在河面上。","知识产权数据映射经济活力。"],"rel":""},{"w":"投射","f":6,"def":"1．（动词）（对着目标）扔，掷。2．（动词）（光线等）射。3．（动词、名词）反映，反射。","key":"（光线等）射向某物；也指把自己的情感、想法加于他人他物","dim":"单向投射","egs":["美国近期正研发一种由有人机挂载并能携带、投射空空导弹的新概念无人装备。","拾级而上，穿过一字排开的宏伟柱廊，阳光从主楼大厅的玻璃天窗倾泻，投射斑斓的艺术光影。"],"rel":""},{"w":"反射","f":5,"def":"1．（动词）光线、声波等从一种介质到达另一种介质的界面时返回原介质。2．（动词）有机体通过神经系统，对于刺激所发生的反应。3．（动词）反映。","key":"光线、声波等遇界面返回；也指有机体对刺激的反应","dim":"返回反应","egs":["日晕又叫圆虹，是日光通过卷层云时，受到冰晶的折射或反射而形成的。","用西医的话来说，“望梅止渴”其实是一种条件反射。"],"rel":""}]},{"id":"g082","theme":"e-cause","label":"纸上谈兵／坐而论道","words":["纸上谈兵","坐而论道"],"rows":[{"w":"纸上谈兵","f":12,"def":"比喻空谈理论，不能解决实际问题。也比喻空谈不能成为现实。含贬义。","key":"在纸面上谈用兵，比喻空谈理论、脱离实际（贬义）","dim":"空谈理论","egs":["讲政治不能纸上谈兵、空喊口号，而是要落实到党和国家各项工作中去。","没有坚强的执行力，目标再远大、布局再科学、蓝图再宏伟，也只能是纸上谈兵。"],"rel":""},{"w":"坐而论道","f":5,"def":"意思是坐着空谈大道理。指口头说说，不见行动。比喻脱离实际地空谈。含贬义。","key":"坐着空谈大道理，不付诸行动（含批评）","dim":"空说不做","egs":["坚定文化自信不能止步于坐而论道，必须体现在文化自强的行动上。","敢于担当者，不是坐而论道的清谈客，而是起而行之的实干家。"],"rel":""}]},{"id":"g083","theme":"a-speed","label":"转化／转换等3词","words":["转化","转换","转变"],"rows":[{"w":"转化","f":13,"def":"1．（动词）矛盾的双方经过斗争，在一定的条件下，各自向着和自己相反的方面转变，向着对立方面所处的地位转变。2．（动词）转变，改变。","key":"事物从一种形态变为另一种形态（能量转化、成果转化），强调“由此变彼”","dim":"形态转变","egs":["经过长期的努力，矛盾中原本处于劣势的一方成功转化为优势方。","加快推进科技自立自强与科技创新，并将创新成果及时转化为现实生产力。"],"rel":""},{"w":"转换","f":10,"def":"（动词）改变，改换。","key":"改变、更换（角色、频道、思路、机制），强调“换”","dim":"对接更换","egs":["加快新旧动能转换，是有效应对下行压力、实现高质量发展的必然选择。","面对困境，我们需要转换思路，寻找新的解决方案。"],"rel":""},{"w":"转变","f":8,"def":"（动词、名词）指从一种情况变为另一种情况。","key":"由一种情况变到另一种情况（观念、作风、方式），多用于抽象","dim":"整体变化","egs":["必须加快水资源利用方式的根本转变。","市场形势瞬息万变，再不赶紧转变落伍的营销思维，日后的发展恐怕也就不可同日而语了。"],"rel":""}]},{"id":"g084","theme":"e-cause","label":"按图索骥／照本宣科","words":["按图索骥","照本宣科"],"rows":[{"w":"按图索骥","f":12,"def":"索：寻找。骥：良马。照着图像去寻找良马。1．比喻做事死守教条，而不懂得变通。2．比喻依据一定的线索去寻找事物。（中性词）","key":"按图上的样子去找好马，比喻按照线索寻找；也比喻墨守成规、不知变通","dim":"依样寻找","egs":["文物部门对文物的保护是以“按图索骥”的原则进行的，随之产生的遗憾就是，一些没有被列入保护名录的文物就此成为建设的牺牲品，离开了人们的视野，其历史意义也湮没了。","今后，信访人只要拿着信访清单按图索骥，就能找到相关职能部门反映诉求。"],"rel":""},{"w":"照本宣科","f":7,"def":"科：条文。照着本子念条文。形容讲课、发言等死板地按照课文、讲稿，没有发挥，不生动。比喻说话、做事等不能灵活运用。作谓语、定语、状语，含贬义。","key":"照着本子念，比喻死板照搬、不结合实际","dim":"死板照搬","egs":["思政课教学切忌浮于表面，照本宣科、空洞教条地把基本理论告诉大家。","作为我国法律体系中条文最多、体量最大、编章结构最复杂的一部法律，让老百姓真懂真用民法典不能简单照本宣科。"],"rel":""}]},{"id":"g085","theme":"a-speed","label":"变革／改革","words":["变革","改革"],"rows":[{"w":"变革","f":12,"def":"（动词、名词）改变事物的本质。多指社会制度、法度等宏观层面。","key":"事物发生根本性的改变（社会变革、技术变革）","dim":"根本改变","egs":["急剧变革的中国社会，各种公共突发事件频繁发生。","5G 高速度、低延时的技术创新将引领万物皆终端、万物皆媒介的变革。"],"rel":""},{"w":"改革","f":9,"def":"（动词、名词）把事物中旧的不合理的部分改成新的、能适应客观情况的。（多指比较大的、根本性的改变）","key":"把事物中旧的不合理的部分改成新的（多指制度、体制）","dim":"革除改新","egs":["在全面深化改革的未来进程中，务必加大民生领域的改革。","在形式上，要不断改革创新教学方式方法，注重启发自主思维。"],"rel":""}]},{"id":"g086","theme":"a-speed","label":"催生／催化","words":["催生","催化"],"rows":[{"w":"催生","f":12,"def":"（动词）尽力使某件事情能够提前或加速进行、产生。","key":"催促产生（新事物、新业态、新需求）","dim":"促使产生","egs":["在“母亲节”“520”等节日氛围的加持下，“鲜花经济”进一步升温，催生出消费新蓝海。","权力家族化催生畸形官场生态。"],"rel":""},{"w":"催化","f":5,"def":"（动词）促使化学反应的速率发生改变。泛指加速改变。","key":"加入催化剂加速反应；比喻促使事情加速发展（化学反应）","dim":"加速反应","egs":["由氯酸钾制氧可加二氧化锰催化，使氧发生迅速。","5G 催化智能经济快速崛起。"],"rel":""}]},{"id":"g087","theme":"i-verb","label":"赋予／给予","words":["赋予","给予"],"rows":[{"w":"赋予","f":12,"def":"（动词）给予，交给，寄托（重大任务、使命等）。","key":"（上对下）交给（使命、权利、意义、新内涵），多用于抽象","dim":"上对下授","egs":["赋予中法建交精神新的时代内涵。","党的各级领导干部必须正确行使人民赋予的权力。"],"rel":""},{"w":"给予","f":6,"def":"（动词）给、赠送、使别人得到。中性词。","key":"给（帮助、支持、评价），最通用，对象可抽象可具体","dim":"通用给予","egs":["好的文化教育给予当地孩子更多发展可能。","针对海外华人华侨以及年轻受众群体，文化综艺节目亦当给予关注，在故事中进行爱国主义、家国情怀等价值观的引导。"],"rel":""}]},{"id":"g088","theme":"c-extent","label":"管中窥豹／见微知著等5词","words":["管中窥豹","见微知著","一叶知秋","盲人摸象","以小见大"],"rows":[{"w":"管中窥豹","f":12,"def":"管：竹管。从管中看豹。1．比喻见识狭小，看不到全面。2．也比喻只看事物的一部分而推测事物的全貌。作谓语，中性词。（侧重整体与部分对比）","key":"从竹管里看豹，看到的只是斑纹，比喻只见局部、所见不全（也作“可见一斑”）","dim":"所见不全","egs":["得其大者兼其小的同时，也须小中见大、管中窥豹。","你怎么能断定你对国外的了解、对祖国的了解不是以蠡测海、管中窥豹？"],"rel":"管窥（2）：从管子里看东西。中性词，动词。可见一斑"},{"w":"见微知著","f":7,"def":"微：小，指事物微小的迹象。著：显明，指事物的发展。指见到细微的苗头，就能推断其发展趋向并认识问题的实质。同“睹微知著”。作谓语、定语。（侧重大小对比）","key":"看到微小的苗头就知道其发展趋势，褒义，强调洞察力","dim":"洞察趋势","egs":["安个护栏绿化一下别看事小，但是它见微知著了，防微杜渐了，柔性执法了。","新征程上，锤炼见微知著、明察秋毫的高度政治敏锐性，就要坚持底线思维、增强忧患意识。"],"rel":""},{"w":"一叶知秋","f":2,"def":"从一片落叶可以知道秋天的到来。比喻从一点征兆可以预料事物发展的趋向。也作“落叶知秋”、“叶落知秋”。（侧重从预兆推知未来）","key":"看到一片落叶知秋天到来，比喻从细微迹象推知趋势","dim":"以小推趋势","egs":["党员干部在群众路线教育实践活动的意见征集阶段,除了要有“闻过则喜”的诚恳态度，还须具备“一叶知秋”的敏锐。"],"rel":""},{"w":"盲人摸象","f":1,"def":"比喻以点带面、以偏概全。（现有时也用字面义，形容做一件事毫无头绪地摸索）","key":"几个盲人摸象各说各异，比喻以局部代替整体（贬义）","dim":"以偏代全","egs":["任何事被冠之以“秘密”后，总能激起人的窥探欲。然而，“窥探”却往往如盲人摸象，要么看偏，要么看缺。"],"rel":""},{"w":"以小见大","f":1,"def":"从小的可以看出大的，指通过小事可以看出大节，或通过一小部分看出整体。（侧重大小对比）","key":"从细小处看出大道理（多用于写作手法、认识方法）","dim":"小处见大","egs":["今年春晚语言类节目在主题立意上更加注重“以小见大”——小故事讴歌大时代，小人物书写大情怀。"],"rel":""}]},{"id":"g089","theme":"e-cause","label":"迫在眉睫／刻不容缓","words":["迫在眉睫","刻不容缓"],"rows":[{"w":"迫在眉睫","f":12,"def":"就像已经逼近了眉毛和睫毛一样。形容事情已逼近眼前，非常紧迫。作谓语、定语。","key":"事情已到眼前，非常紧迫（多形容形势、任务）","dim":"近在眼前","egs":["随着新能源装机量的不断增加，多举措解决消纳难题已经迫在眉睫。","疫情之初第一时间研发出核酸检测试剂盒，解决了迫在眉睫的问题。"],"rel":""},{"w":"刻不容缓","f":10,"def":"片刻也不能拖延，形容形势紧迫。","key":"一刻也不能拖延，强调时间上不能等","dim":"不能拖延","egs":["全面、全力和全方位加强“食育”，刻不容缓，势在必行。","当前，抗震救灾正处在刻不容缓的紧要关头。"],"rel":""}]},{"id":"g090","theme":"i-verb","label":"侵蚀／腐蚀","words":["侵蚀","腐蚀"],"rows":[{"w":"侵蚀","f":12,"def":"1．（动词）逐渐侵害使变坏。2．（动词）暗中一点一点地侵占（财物）。","key":"逐渐侵入使受损（风雨侵蚀、利益侵蚀），可指逐步侵占","dim":"逐步侵入","egs":["海水长年侵蚀着悬崖表面。","严防江湖习气等不良文化的侵蚀。"],"rel":""},{"w":"腐蚀","f":6,"def":"1．（动词）本为化学用词，指物质因化学作用而逐渐消损破坏。2．（动词）比喻坏的思想或环境，使人逐渐变质堕落。","key":"物体因化学作用而损毁；也指使人思想变质、腐化","dim":"腐化变质","egs":["金属零件在潮湿环境中容易被腐蚀，需要定期进行维护。","如果让商品交换原则侵蚀党内生活，必然滋生腐败，严重腐蚀党的肌体。"],"rel":""}]},{"id":"g091","theme":"d-relation","label":"融会贯通／举一反三等3词","words":["融会贯通","举一反三","触类旁通"],"rows":[{"w":"融会贯通","f":12,"def":"融会：融合；贯通：全面透彻的了解。指把各方面的知识、道理融合贯穿，从而获得对事物全面、透彻的理解。含褒义。","key":"把各方面知识和道理融合贯穿，得到全面透彻的理解","dim":"融合贯通","egs":["在扩大各民族交往交流中促进民族交融，将推动各民族在各个方面融会贯通。","教师要遵循启发性的教学原则，注重引导学生积极思考，融会贯通所学知识。"],"rel":"融会"},{"w":"举一反三","f":8,"def":"指从一件事类推而知道许多类似的其他事情。指善于推理，能由此知彼，触类旁通。含褒义。（多形容“问题”）","key":"从一件事类推而知道许多事，强调类推能力","dim":"一推知多","egs":["老旧小区改造中的“梗阻”并非个例，必须举一反三，加以排查整治。","理论有深度，看问题才能举一反三，做决策才能游刃有余。"],"rel":""},{"w":"触类旁通","f":2,"def":"触：接触。通：通晓。指掌握了某一事物的规律或知识，就能够以此类推，了解同类的其他事物。（侧重于抽象的思维层面。）（侧重类推）","key":"掌握某一事物的规律就能推知同类事物","dim":"类推他类","egs":["大多数人其实是被“狼来了”骗过之后才醒悟，并没有触类旁通，学会辨别这类假新闻，因而不时被低劣的造假手段“套路”。"],"rel":""}]},{"id":"g092","theme":"i-verb","label":"隐藏／蕴藏等3词","words":["隐藏","蕴藏","潜藏"],"rows":[{"w":"隐藏","f":12,"def":"（动词）隐蔽躲藏，不让别人发现。","key":"躲藏、藏起来不让人发现（主观隐蔽）","dim":"有意藏匿","egs":["烂梗流行的背后隐藏着什么？","在实际生活中，还有些隐藏的功能，可能都不是很清楚，我们一起来发现一下。"],"rel":""},{"w":"蕴藏","f":7,"def":"（动词）蓄积而未显露或未发掘。","key":"蓄积在内、尚未发掘（资源、潜力、情感）","dim":"蓄而未发","egs":["海底不仅蕴藏着丰富的能源，还有陆地上储量很少的稀有金属。","中华文明烙印在中华民族的基因里，蕴藏在中国人民的智慧中。"],"rel":""},{"w":"潜藏","f":6,"def":"（动词）藏在隐蔽处。","key":"潜藏于内、不易察觉（危险、矛盾、情绪）","dim":"潜伏未显","egs":["在这片看似平静的海域下，潜藏着许多未知的深海生物。","孩子们的心中潜藏着无尽的梦想和好奇心，等待着被激发和发掘。"],"rel":""}]},{"id":"g093","theme":"b-attitude","label":"责无旁贷／义不容辞等3词","words":["责无旁贷","义不容辞","当仁不让"],"rows":[{"w":"责无旁贷","f":12,"def":"自己应尽的责任，不能推卸给旁人。多用于指自己应当做的不可推卸的事，侧重“职责”、“责任”方面。","key":"自己的责任不能推给别人，强调“责任”","dim":"责任不可推","egs":["给学生心灵埋下真善美的种子，引导学生立鸿鹄志、做奋斗者，思想政治理论课责无旁贷。","当前时代，凝聚并践行社会主义核心价值观是媒体责无旁贷的社会责任。"],"rel":""},{"w":"义不容辞","f":8,"def":"指道义上不容许推辞、拒绝。常用于形容为了正义事业，敢于挺身而出，不做推辞。含褒义。","key":"道义上不允许推辞，强调“道义”","dim":"道义不容辞","egs":["钟南山认为自己只是一个医生，须对人民的生命安全负责，他的出声是义不容辞的。","保家卫国，是义不容辞的使命。"],"rel":""},{"w":"当仁不让","f":7,"def":"原义是指以仁为任，无所谦让。后指遇到应该做的事就积极主动去做，不推让。作谓语、状语、定语。","key":"遇到应该做的事主动承担、不推让，含“主动争先”","dim":"主动争先","egs":["赛场上体能比赛的场地和器材，比我军平常训练的体能训练差了不少，我军拿到第一，应是手到擒来，当仁不让。","我们要以舍我其谁的使命感、时不我待的紧迫感、当仁不让的责任感，发挥好兵团的特殊作用。"],"rel":""}]},{"id":"g094","theme":"b-attitude","label":"置若罔闻／视而不见等5词","words":["置若罔闻","视而不见","熟视无睹","充耳不闻","闭目塞听"],"rows":[{"w":"置若罔闻","f":12,"def":"置：放，指放在一边。若：好像。罔：没有。放在一边，好像没有听到。形容不重视，不关心。（主观上故意，主要用于“听觉”方面）","key":"放在一边好像没听见（明白着装听不见）","dim":"装听不见","egs":["对学校的规章制度，有的同学置若罔闻。"],"rel":""},{"w":"视而不见","f":11,"def":"1．虽然睁着眼看，却什么也没有看到，指不注意或不关心。作谓语，含贬义。","key":"看见了当作没看见（对象是眼前事物）","dim":"装看不见","egs":["在现代社会，很多人对身边的环境污染视而不见，这令人深感担忧。","安全生产是件大事，可总有人在这个性命攸关的问题上心存侥幸、对身边的风险隐患视而不见。"],"rel":""},{"w":"熟视无睹","f":11,"def":"1．看惯了却像没看见一样。2．看到某种现象，但不关心，只当没有看见。","key":"看惯了当作没看见（含麻木、漠视）","dim":"看惯漠视","egs":["如果说熟悉的地方没有风景，那么只能缘于人们的熟视无睹。","对群众疾苦和呼声熟视无睹、麻木不仁，是漠视侵害群众利益问题的另一大表现。"],"rel":"视若无睹"},{"w":"充耳不闻","f":5,"def":"充：塞住。形容故意不听别人的话。也形容对某些事漠不关心。也作“听而不闻”。（主观上故意或不重视）","key":"塞住耳朵不听，形容不愿听取意见（多含故意）","dim":"不愿听","egs":["有一些地方反应迟钝、动作迟缓，固守当时特定环境下的过度防疫举措，对社会叫停“一刀切”、扩大化等简单粗暴的阻隔举措的呼声充耳不闻。"],"rel":""},{"w":"闭目塞听","f":2,"def":"塞：堵塞。闭着眼睛，堵住耳朵。指不与外界接触，脱离实际。","key":"闭着眼睛、塞着耳朵，形容不接触实际、不听外界意见","dim":"封闭拒听","egs":["成人动漫市场的开拓不但要广开言路，更需要身体力行。不然，闭目塞听，闭门造车，不但新市场难有拓展，产业发展的方向很可能会走入另一个没有出路的死胡同。"],"rel":""}]},{"id":"g095","theme":"d-relation","label":"并行不悖／齐头并进等3词","words":["并行不悖","齐头并进","双管齐下"],"rows":[{"w":"并行不悖","f":11,"def":"并行：并肩而行；悖：违背，抵触。指同时进行或同时存在而不相冲突。作谓语、定语。（多形容看似矛盾实不矛盾的两个或两个以上事物）","key":"同时进行互不冲突（制度、做法、理念）","dim":"并行不冲突","egs":["科技与法律，两种价值取向其实并行不悖，都服务于人类的生存状态的改善。","全面深化改革和全面推进依法治国是目标方向一致、相辅相成、并行不悖的。"],"rel":"并行"},{"w":"齐头并进","f":11,"def":"几支队伍并行前进。常用来形容几件事情同时进行。作谓语、定语，含褒义。","key":"几方面同时前进（多方并进、共同推进）","dim":"多方同进","egs":["5G 技术领跑全球，建设与应用齐头并进。","全面深化改革和全面依法治国，是齐头并进的姊妹篇。"],"rel":""},{"w":"双管齐下","f":10,"def":"原指手握双笔同时作画。后比喻做一件事两个方面同时进行或两种方法同时使用。作谓语、宾语。","key":"两管笔同时作画，比喻两件事同时进行（两种办法一起用）","dim":"两法并用","egs":["提升高等教育的办学质量，政府和高校要做到“双管齐下”。","坚持国家治理体系和治理能力现代化双管齐下。"],"rel":"多管齐下"}]},{"id":"g096","theme":"d-relation","label":"不谋而合／不约而同","words":["不谋而合","不约而同"],"rows":[{"w":"不谋而合","f":11,"def":"谋：商量；合：相同。事先没有商量，而彼此的做法或意见却相同。（侧重思想上）（主语可以是人，也可以是物）","key":"没有商量而见解、行动完全一致","dim":"见解相合","egs":["对这个问题的看法，你们两人不谋而合。","“贤”字赛道设计，与国际赛车场的“上”赛道不谋而合，都极具中国文化特色。"],"rel":"不谋而同"},{"w":"不约而同","f":10,"def":"原意是事先没有约定而一齐前来会合。后用来指没有事先商量约定而彼此的看法或言行相同。作状语、定语。（侧重行为上）","key":"没有约定而彼此行动一致（多指具体动作）","dim":"行动一致","egs":["如今，聚焦现实题材成为网络作家不约而同的选择。","与往年不同，今年主流电商平台不约而同取消预售模式。"],"rel":""}]},{"id":"g097","theme":"e-cause","label":"大势所趋／势在必行","words":["大势所趋","势在必行"],"rows":[{"w":"大势所趋","f":11,"def":"大势：整个局势；所趋：所趋向的（地方）。整个局势发展的趋向。作宾语，多用于判断句。","key":"整个局势发展的趋向（客观形势）","dim":"客观趋向","egs":["以数字化赋能宣传思想文化工作成为大势所趋。","民族复兴、国家统一是大势所趋、大义所在、民心所向。"],"rel":"大势"},{"w":"势在必行","f":11,"def":"不能躲开或回避。指形势已决定了非做不可。作谓语、定语。","key":"从形势看必须做（强调“非做不可”）","dim":"不得不做","egs":["做大做强航运，是势在必行的重要工作。","适度放宽小学入学年龄势在必行。"],"rel":""}]},{"id":"g098","theme":"i-verb","label":"否定／肯定","words":["否定","肯定"],"rows":[{"w":"否定","f":11,"def":"（动词、形容词）否认事物的存在或事物的真实性（跟“肯定”相对）。","key":"对事物作出不承认、否定的判断","dim":"判为不对","egs":["外国的月亮一定比中国圆吗？至少在社会治安治理上，这个问题的答案是否定的。","每个专业都有存在的价值，不能因为钱而否定。"],"rel":""},{"w":"肯定","f":6,"def":"1．（动词、名词、形容词）承认事物的存在或事物的真实性（跟“否定”相对）。2．（副词）一定，必定，毫无疑问。3．（形容词）确切的，明确的。","key":"承认事物的存在或价值，作出正面判断","dim":"判为对","egs":["该报道以宁夏银川市贺兰县一家美团便利店闪电仓为例，肯定了即时零售促进线上线下消费融合、支持中小微商户数字化转型等价值。","中企智慧工地系统在沙特受肯定。"],"rel":""}]},{"id":"g099","theme":"f-light","label":"难以为继／后继无人","words":["难以为继","后继无人"],"rows":[{"w":"难以为继","f":11,"def":"难以继续下去。作谓语。","key":"难以继续下去（多指局面、模式、经营）","dim":"难以持续","egs":["在着力调结构、经济增速放缓背景下，房地产投资高增长恐难以为继。","部分教育培训机构因自身经营、疫情影响、政策效应等多种因素难以为继。"],"rel":""},{"w":"后继无人","f":5,"def":"继：继承。没有后人来继承前人的事业。也作“后继乏人”。作谓语、定语。（关于人，形容事业缺少接班人）","key":"后面没有接替的人（多指技艺、事业、人才培养断层）","dim":"无人接续","egs":["现在狠抓青年教师的培训恰是最好时机，不然再过三年，教师队伍将后继无人。","流传千年的“西兰卡普”技艺，面临后继无人之困。"],"rel":""}]},{"id":"g100","theme":"c-extent","label":"如数家珍／了如指掌","words":["如数家珍","了如指掌"],"rows":[{"w":"如数家珍","f":11,"def":"好像在数自己家里的珍宝一样。通常用来形容某人对所讲的事情十分熟悉。含褒义。","key":"像数自家珍宝一样熟悉，形容对情况非常熟悉（含喜爱）","dim":"熟悉喜爱","egs":["提起小区内事情，他如数家珍。","不少明星都在追看《星星》，不仅对经典台词如数家珍，更有女星模仿千颂伊的犯二行为，十分喜感。"],"rel":""},{"w":"了如指掌","f":6,"def":"形容对事物了解得非常清楚，像把东西放在手掌里给人家看一样。谓语。","key":"清楚得像指自己的手掌，形容对情况了解得非常清楚","dim":"了解透彻","egs":["格鲁吉亚货车司机迈斯拉泽已有多年驾龄，对当地路况几乎了如指掌。"],"rel":""}]},{"id":"g101","theme":"g-express","label":"探索／探究等3词","words":["探索","探究","探寻"],"rows":[{"w":"探索","f":11,"def":"（动词）多方寻求答案，研究。","key":"多方寻求答案、解决疑问（未知领域、规律）","dim":"寻求未知","egs":["探索真理的道路上充满了艰辛，但科学家们从未退缩。","人类探索宇宙的脚步从未停歇。"],"rel":""},{"w":"探究","f":8,"def":"（动词）探索研究；探寻追究。","key":"深入探讨、追根究底（原因、原理），更强调“钻研”","dim":"追根究底","egs":["研学其实是一种研究性学习，需要用眼睛看，用大脑去思考，让儿童在真实世界中去合作探究，去发现。","走进许慎故乡，听听关于《说文解字》的故事，探究中国汉字的造字规律。"],"rel":""},{"w":"探寻","f":8,"def":"（动词）指勘探、寻求。","key":"寻找、探求（踪迹、路径、答案），强调“找”","dim":"寻找踪迹","egs":["科学家们正在深海中探寻新的生物种类，以揭示生命的奥秘。"],"rel":""}]},{"id":"g102","theme":"b-attitude","label":"无可厚非／无可非议","words":["无可厚非","无可非议"],"rows":[{"w":"无可厚非","f":11,"def":"厚：过分；非：非难，责备。指说话做事虽有缺点，但还有可取之处，应予谅解，不可以过分责备。在句中一般作谓语。","key":"不可过分指责，表示虽有缺点但可以理解（有肯定意味）","dim":"可以理解","egs":["她头一次使用高压锅，把饭煮糊了，这无可厚非。","追星，无可厚非，但必须守规则。"],"rel":""},{"w":"无可非议","f":7,"def":"非议：批评指责。指没有什么可以指摘的，表示合乎情理。","key":"没有什么可指责的，表示完全正确（程度更强）","dim":"完全正当","egs":["追求公平固然是天经地义的，但强调“效率优先、兼顾平等”也无可非议。","中国根据国际法和相关国内法规开展正常的海洋活动无可非议。真题练习：36．新业态快速发展，既为经济社会发展提供了新的增长点，也成为公共安全新的风险点。对新业态发展中的问题，既不能________，也不能________，重在找准鼓励创新和防控风险的平衡点，坚持在发展中规范、在规范中发展。依次填入画横线部分最恰当的一项是:A．小题大做   一叶障目           B．因小失大     因循守旧C．坐以待毙   熟视无睹           D．因噎废食     视而不见37．有人认为网络短视频的火爆将逐渐挤占长视频的发展空间，但实际上网络短视频和长视频可以________。要在鼓励广大媒体工作者持续产出优质长视频的同时，积极反思、引导和治理短视频的发展，善用短视频这柄数字时代的双刃剑，________、趋利避害。依次填入画横线部分最恰当的一项是：A．各行其是   就实论虚           B．并行不悖     扬长避短C．相辅相成   取长补短           D．并驾齐驱     避实击虚38．将下列选项中的词语依次填入画横线部分最恰当的一项是：（1）这样多的读者哪一个是先看批评家的文章，然后再让批评家牵着鼻子走，________地去读原著呢？我看是绝无仅有的。（2）30 年前，国际形势________，国内改革________，党中央作出重大决策，掀开了我国改革开放向纵深推进的崭新篇章。A．照本宣科   风云变幻   风起云涌B．按图索骥   风起云涌   风云变幻C．照本宣科   风起云涌   风云变幻D．按图索骥   风云变幻   风起云涌39．新史料被发掘，有赖于史家具有证据意识。若是史家不认为某个史料可以作为证据，该史料可能会被________。比如甲骨文，起初甲骨被当作龙骨入药，不被史家关注。但晚清学者王懿荣意识到龙骨非同寻常，后经考证确认甲骨文是商代文字，之后史家以此为证据重构殷商历史，为中华文明起源这一重大问题提供了________支点。依次填入画横线部分最恰当的一项是：A．视而不见   稳固           B．弃如敝屣      崭新C．断章取义   可靠           D．束之高阁      坚实40．教师承担着立德育人的神圣使命，对教师的要求比其他行业高________，但高到什么程度，要有客观标准和现实考量。如果把教师的育人细节不加选择、________地置于舆论场，可能会给教师和学校制造不必要的麻烦和干扰。依次填入画横线部分最恰当的一项是：A．无可厚非   随心所欲         B．公平合理      杂乱无章C．不容置喙   毫无保留         D．由来已久      轻而易举                     第九天"],"rel":""}]},{"id":"g103","theme":"c-extent","label":"相提并论／等量齐观等5词","words":["相提并论","等量齐观","同日而语","并驾齐驱","混为一谈"],"rows":[{"w":"相提并论","f":11,"def":"把不同的人或不同的事放在一起谈论或对待。作谓语，多用于否定句中。（主语需两者或以上）","key":"把不同的人或事放在一起谈论（多用于否定，含“不配”）","dim":"不加区分地并提","egs":["部分电商专供虽然价格低廉，但品质往往难以和线下同款相提并论。","历史地看，这次会议的重要性确实可以与遵义会议相提并论。"],"rel":""},{"w":"等量齐观","f":10,"def":"指对有差别的人或事物同等看待。","key":"把差别很大的事物同等看待（多用于否定）","dim":"同等看待","egs":["在德与才的关系上，既重德又重才，不片面强调，又坚持以德为先，而非等量齐观。","对这两种情况等量齐观地看待是不正确的。"],"rel":""},{"w":"同日而语","f":8,"def":"放在同一时间谈论，指相提并论。（侧重于时间上的对比，多形容与自身的比较——现有时也有例外）（多用于否定句中）","key":"放在同一时间谈论（多用于否定，指不能相比），强调“时势不同”","dim":"时势不同","egs":["俄罗斯目前的经济状况同 2008 年的危机不能同日而语。","机器人产业对经济增长的带动作用显然不能与汽车产业同日而语。"],"rel":""},{"w":"并驾齐驱","f":7,"def":"几匹马并排拉一辆车，一齐快跑。彼此的力量或才能不分高下或地位相当。作谓语、定语。","key":"几匹马并排拉车，比喻不分先后、不相上下（可褒）","dim":"不相上下","egs":["如果集成光子学能够取得突破，光量子路径可能与超导路径并驾齐驱。","随着互联网技术深入发展，移动互联网逐渐成为与互联网并驾齐驱的新闻传播工具。"],"rel":""},{"w":"混为一谈","f":4,"def":"把不同的事物混在一起，说成是同样的事情。（侧重于强调事物本质上存在差别，多用于否定句中）","key":"把不同的事物混杂在一起说成相同（贬义）","dim":"混作一谈","egs":["不能将楼市精准调控与“政策松绑论”混为一谈。","过去很长一段时期，很多人将执法与服务混为一谈，导致执法力度弱化，服务满意度也不高。"],"rel":""}]},{"id":"g104","theme":"i-verb","label":"消除／消失等5词","words":["消除","消失","消解","消弭","消亡"],"rows":[{"w":"消除","f":11,"def":"（动词）使不存在，除去。","key":"使不存在（隐患、隔阂、误会）","dim":"使之不存在","egs":["为确保广大旅客的出行安全，新海港采取了一系列有力措施，深入分析并消除了春运期间的安全隐患。","我们始终坚定人民立场，强调消除贫困、改善民生。"],"rel":""},{"w":"消失","f":9,"def":"（动词）（人或事物）逐渐减少以至没有；不复存在。","key":"（事物）逐渐不见（中性，最通用）","dim":"不见踪迹","egs":["从“乡土中国”到“现代中国”，生活方式改变，一些习俗仪式或简化或消失不可避免。","火箭划出一道绚丽的曲线，瞬间便消失在了苍穹之中。"],"rel":"消失殆尽"},{"w":"消解","f":7,"def":"（动词）消释，消除。","key":"（疑虑、矛盾、情绪）逐渐消释化解","dim":"渐次化解","egs":["网络暴力越来越频繁地挑战着公共秩序、消解着公平正义。","消解干部内耗的一个基本手段是建立健全相关制度规范。"],"rel":""},{"w":"消弭","f":6,"def":"（动词）弭：平息。清除、消除某些不好的事情。","key":"消除、平息（战乱、灾祸、隔阂），多指抽象祸患，书面","dim":"平息祸患","egs":["如何更好地把矛盾纠纷化解在基层、消弭于萌芽？","这些不正常意识对党内监督起着消弭和冲抵的反作用。"],"rel":""},{"w":"消亡","f":6,"def":"（动词、名词）消失，灭亡。","key":"（事物）逐渐消失直至不复存在（多指物种、制度），不及物","dim":"自行消失","egs":["一旦见识到古山寨的美，就不会忍心让它们在风雨岁月中沉寂、消亡。","苹果公司 C．EO蒂姆·库克谈及诺基亚时说，不创新必然带来消亡。"],"rel":""}]},{"id":"g105","theme":"i-verb","label":"增强／加强","words":["增强","加强"],"rows":[{"w":"增强","f":11,"def":"（动词）增进，加强。","key":"增进、加强（信心、体质、意识、能力），多在原有基础上加大","dim":"自身变强","egs":["政策的暖意，正是不断增强中国市场的“磁吸力”。"],"rel":""},{"w":"加强","f":10,"def":"（动词）增强，使变得更强和更有效。","key":"使更坚强有力（管理、合作、领导、监督），多指措施力度","dim":"措施更有力","egs":["以法治建设加强和保障新时代反间谍工作。","在互联网和新媒体领域中，加强管理和引导创作生产应当双管齐下，共同发挥作用。"],"rel":""}]},{"id":"g106","theme":"i-verb","label":"保持／维持","words":["保持","维持"],"rows":[{"w":"保持","f":10,"def":"（动词）维持（原状），使不消失或减弱。","key":"维持原状使不消失或减弱（保持联系、保持稳定），含“主动延续”","dim":"延续原状","egs":["开启新征程，我们保持历史耐心，用接续不断的奋斗绘就蓝图。"],"rel":""},{"w":"维持","f":6,"def":"（动词）保持，使继续存在下去。","key":"使继续存在下去（秩序、生活、关系），常需外力支撑","dim":"靠外力撑住","egs":["数据显示，10 年间基尼系数一直维持在 0.4 以上。","村里经济发展严重滞后，他仅靠家里的几亩地和打点零工维持生活。"],"rel":""}]},{"id":"g107","theme":"i-verb","label":"产生／衍生","words":["产生","衍生"],"rows":[{"w":"产生","f":10,"def":"（动词）由已有事物中生出新的事物，出现。","key":"由已有事物中生出新事物（矛盾、影响、结果），最通用","dim":"生出新事物","egs":["在大自然中，阳光、水分和土壤相互作用，产生了各种各样的植物。","人大代表由选举产生。"],"rel":""},{"w":"衍生","f":6,"def":"（动词）繁衍生息。形容从母体物质得到的新物质的过程。","key":"演变而产生（多指由母体派生出新的分支，含“派生”意味）","dim":"派生出","egs":["在这片古老的土地上，生命的种子不断衍生，从微小的微生物到繁盛的森林，形成了丰富多样的生态系统。","借助互联网与新媒体平台，将熊猫等 IP 化后的文化符号进行多元衍生，实现商业价值转化，推动中华优秀传统文化传承与发展。"],"rel":""}]},{"id":"g108","theme":"b-attitude","label":"得不偿失／因小失大","words":["得不偿失","因小失大"],"rows":[{"w":"得不偿失","f":10,"def":"指所得的利益抵偿不了所受的损失。含贬义。","key":"所得的利益抵不上所受的损失（多指做事结果）","dim":"得失相抵不足","egs":["先污染、后治理的代价过大，得不偿失，这是被中外治污史反复证明的道理。","现实中很多人认为占便宜是一件好事。然而，你会发现占小便宜吃大亏，这是一种得不偿失的行为。"],"rel":""},{"w":"因小失大","f":6,"def":"因：为了。指为了小的利益造成大的损失。","key":"为了小的利益而失去大的利益（强调“舍不得小的”）","dim":"贪小失大","egs":["有的人就看着鼻子底下这点实利，算盘珠子拨得很精，看起来很聪明，实际上常常因小失大。"],"rel":""}]},{"id":"g109","theme":"i-verb","label":"调节／调控","words":["调节","调控"],"rows":[{"w":"调节","f":10,"def":"（动词）在数量、程度、规模等方面进行调整，使符合标准。","key":"从数量或程度上调整使适合要求（调节温度、价格、情绪）","dim":"适度调整","egs":["积极的心理暗示是一种常用的心理调节方法。","饮酒自古以来就是调节气氛、沟通感情必不可少的“推力”。"],"rel":""},{"w":"调控","f":7,"def":"（动词）调节控制。","key":"调节控制（宏观调控、房地产调控），多指政策手段","dim":"政策掌控","egs":["货币政策是中央银行调控宏观经济的重要手段之一。","MKK3 基因的双重调控机制可直接用于分子育种。"],"rel":""}]},{"id":"g110","theme":"h-quality","label":"错综复杂／纷繁复杂等4词","words":["错综复杂","纷繁复杂","扑朔迷离","盘根错节"],"rows":[{"w":"错综复杂","f":10,"def":"错综：纵横交错。形容事物交错聚集，情况纷繁杂乱。作谓语、定语。","key":"纵横交错、情况复杂（局势、关系、问题）","dim":"交织复杂","egs":["今年世界经济形势依然错综复杂、充满变数。","对于错综复杂的中美关系而言，经贸利益既“好吃”，又是推动双边关系保持“好看”的关键力量。"],"rel":"错杂：两种以上的东西交错夹杂在一起。"},{"w":"纷繁复杂","f":8,"def":"头绪、表象多而且复杂。","key":"多而杂、头绪繁多（现象、信息、世界）","dim":"繁多杂乱","egs":["在当前纷繁复杂的国内外政治格局中，各种政治思想相互交织，也相互纠缠。","现代社会的信息纷繁复杂，让人难以选择。"],"rel":"纷繁、纷繁芜杂：事情杂乱无章，没有头绪。"},{"w":"扑朔迷离","f":7,"def":"扑朔：乱动。迷离：眼睛半闭。形容事情错综复杂，不易看清真相。作谓语、定语。（侧重看不清）","key":"比喻事物错综复杂、难以看清真相","dim":"难以辨明","egs":["新老戏骨同台飚戏，两辈人的恩怨情仇更加扑朔迷离。","恐龙之所以总能勾起人们的好奇心，与这种庞然大物扑朔迷离的灭绝“奇案”脱不开关系。"],"rel":""},{"w":"盘根错节","f":5,"def":"树根盘曲，枝节交错。比喻事物的关系错综复杂，很难处理。（侧重关系纠葛密切且深入）","key":"树根盘绕、枝节交错，比喻事情繁难复杂、不易解决（也指旧势力关系复杂）","dim":"根节交错难解","egs":["中国之所以能面对风险挑战迎难而上，在盘根错节的利益交织中挺身向前，在风云变幻的国际竞争中逆风飞扬，靠的是领导干部的担当和作为。","涉黑涉恶“保护伞”“关系网”往往盘根错节，有的为蒙混过关，甚至找人顶包替罪。"],"rel":""}]},{"id":"g111","theme":"i-verb","label":"广阔／广袤","words":["广阔","广袤"],"rows":[{"w":"广阔","f":10,"def":"（形容词）广大宽阔。","key":"面积大、范围宽（视野、天地、市场、前景），可用于抽象","dim":"范围宽阔","egs":["中国式现代化是在改革开放中不断推进的，也必将在改革开放中开辟广阔前景。","登上山顶，我俯瞰着脚下广阔的田野，心中涌起一股豪情。"],"rel":"广阔无垠"},{"w":"广袤","f":6,"def":"1．（形容词）广阔。2．（名词）土地的长和宽，泛指面积。（东西的长度叫“广”，南北的长度叫“袤”）","key":"土地、天地辽阔无边，书面性强（广袤的土地、草原）","dim":"辽阔无垠","egs":["在广袤的时空中呈现时代感是新中国长篇小说创作 70 年提供给后人的一条重要启示。","祖国的土地广袤万里，从东到西，从南到北，都充满了生机与活力。"],"rel":"广袤无边、广袤无垠"}]},{"id":"g112","theme":"i-verb","label":"妨碍／阻碍等3词","words":["妨碍","阻碍","障碍"],"rows":[{"w":"妨碍","f":10,"def":"（动词、名词）使事情不能顺利进行，使过程或进展变得缓慢或困难。","key":"使事情不能顺利进行（妨碍交通、休息），程度较轻","dim":"造成不便","egs":["过于守旧的思想可能会妨碍社会的进步，我们需要保持开放和创新的态度。"],"rel":""},{"w":"阻碍","f":10,"def":"（动词、名词）阻挡去路，妨碍通过或发展。","key":"使不能顺利通过或发展（阻碍进步、发展），程度较重","dim":"阻挡发展","egs":["“职业闭店人”正成为预付式消费的维权阻碍。","低生育率阻碍韩国经济发展。"],"rel":""},{"w":"障碍","f":9,"def":"（名词）挡住道路、使不能顺利通过，或阻碍前进的事物。","key":"挡住道路使不能通过的东西；也指难以逾越的困难","dim":"具体拦阻物","egs":["在实际生活中，一些被认定为“靓号”的用户转网时仍遭遇了种种障碍。"],"rel":""}]},{"id":"g113","theme":"h-quality","label":"根本／基本","words":["根本","基本"],"rows":[{"w":"根本","f":10,"def":"1．（名词、形容词）事物的根源或最重要的部分。2．（副词）从头到尾，始终。","key":"事物的根源、最本质的部分（根本原因、根本保证）","dim":"最本质","egs":["“培养什么人、怎样培养人”始终是教育的永恒主题和根本问题。","他们不是不知道纪律规矩，而是根本没有敬畏之心。"],"rel":"根本性"},{"w":"基本","f":7,"def":"1．（名词、形容词）地基、根本。2．（副词）大体上。","key":"主要的、大体上的（基本情况、基本要求）","dim":"大体主要","egs":["人民是国家的基本。","这个理论的基本观点是，所有物质都是由原子构成的。"],"rel":"基本性、基本功"}]},{"id":"g114","theme":"c-extent","label":"明察秋毫／洞若观火","words":["明察秋毫","洞若观火"],"rows":[{"w":"明察秋毫","f":10,"def":"明：视觉敏锐；察：看；秋毫：鸟兽秋天新长出的细毛。本义为视力好到能查辨秋天鸟兽的细毛。多形容人精明，目光敏锐，能洞察一切。作谓语、定语，含褒义。","key":"眼力敏锐能看清极细微处，多形容洞察力强（也可指能体察民情）","dim":"洞察细微","egs":["面对形势变化，要明察秋毫，见微知著，有感于心，赴之以行。","新征程上，锤炼见微知著、明察秋毫的高度政治敏锐性。"],"rel":"明察：清楚地看到。"},{"w":"洞若观火","f":7,"def":"像看火一样透彻清楚。形容观察事物透彻明晰。作谓语、定语；含褒义。","key":"看得像看火一样清楚，形容对事物观察透彻明白","dim":"看得透彻","egs":["网评文章是有力量的，那些直抵心坎的金玉良言，那些洞若观火的真知灼见，那些针砭时弊的献策建言，无一不抚慰人心、涤荡心灵。","庆幸的是，对于在自己领土部署中程导弹基地的危害性，澳大利亚洞若观火。"],"rel":""}]},{"id":"g115","theme":"d-relation","label":"殊途同归／异曲同工","words":["殊途同归","异曲同工"],"rows":[{"w":"殊途同归","f":10,"def":"通过不同的途径，到达同一个目的。比喻采取不同的方法而得到相同的结果。（主语须是二者或以上）","key":"走不同的路而到同一目的地，比喻方法不同而结果相同","dim":"结果相同","egs":["外媒与网友对两会的关注点“殊途同归”，折射出中国的发展与社会的文明进步。","治标与治本殊途同归，治标有效才能治本有道。"],"rel":""},{"w":"异曲同工","f":6,"def":"曲：曲调。工：工巧，精致。比喻不同的做法有同样的好的效果。常用句式：有异曲同工之妙。","key":"曲调不同却同样美妙，比喻做法不同而效果一样好","dim":"效果同样好","egs":["开放大学与拆除围墙有异曲同工之妙，背后透露的恰恰是更加开放的心态。","育人先育心，“五育”对知识传授和能力培养各有侧重，但价值塑造的旨归异曲同工。"],"rel":""}]},{"id":"g116","theme":"c-extent","label":"望尘莫及／望其项背","words":["望尘莫及","望其项背"],"rows":[{"w":"望尘莫及","f":9,"def":"莫：不能；及：赶上。形容望着远去的人马行走时扬起的阵阵尘土，却不能追上他们，比喻远远地落在了别人的后面，相差甚远，无法追上。在句中一般作谓语、定语。（有时用于表示自谦）","key":"远远落后、追赶不上（多含自谦或客观差距）","dim":"远远落后","egs":["国人以粗茶淡饭、蔬菜豆腐为主食，从科学卫生角度而言，是各国都望尘莫及的。","如此高的薪酬，让无数大佬望尘莫及，也让她成了名副其实的“打工女王”。"],"rel":""},{"w":"望其项背","f":5,"def":"项：脖子的后部。能够看到别人的颈项和脊背。比喻可以赶得上或能相比的。（常用于否定句：难以～、无法～、不能～）","key":"能望见别人的脖子和后背，比喻赶得上（多用于否定“不能望其项背”）","dim":"赶得上（否定）","egs":["AI 音乐的创作效率，让传统音乐制作难以望其项背。"],"rel":""}]},{"id":"g117","theme":"f-light","label":"望而却步／望而生畏","words":["望而却步","望而生畏"],"rows":[{"w":"望而却步","f":9,"def":"却步：不敢前进，往后退。形容遇到危险、困难或力所不及的事就往后退缩。（侧重行为上的退却，多因为害怕、惊讶、震撼、犹豫、顾虑等）","key":"看到困难或危险就退缩不前（贬义/中性）","dim":"退缩不做","egs":["当前，要改变“贪”的亚文化精髓，必须让意欲腐败者望而生畏、望而却步。","产妇在临盆前，母性的自豪感能叫死神望而却步。"],"rel":""},{"w":"望而生畏","f":8,"def":"指让人看见了就害怕。作谓语。","key":"一看就害怕（心理畏惧，不一定退缩）","dim":"心生畏惧","egs":["他坐在椅子上，一言不发，那黑而严峻的面孔，令人望而生畏。","周国平的强项在于把高深艰涩、令人望而生畏的哲学大众化、普及化。"],"rel":""}]},{"id":"g118","theme":"f-light","label":"信手拈来／触手可及等3词","words":["信手拈来","触手可及","唾手可得"],"rows":[{"w":"信手拈来","f":10,"def":"信手：随手；拈：用两三个手指头捏东西。随手拿来。指写文章时能自由纯熟地选用词语或应用典故、素材，用不着怎么思考。引申为引用资料、数据、典故等娴熟不需要思考。（有时也可形容做事不费力——较少见）","key":"随手拿来，多形容写文章时材料、词语运用自如","dim":"随手运用","egs":["王老师讲课时，许多历史小故事信手拈来。","平时博览群书，含英咀华，将这些潜藏的储备应用到作文，便是信手拈来，撷英取华了。"],"rel":""},{"w":"触手可及","f":8,"def":"指近在手边，一伸手就可以接触到。形容距离极近。作谓语、定语、宾语。同“触手可得”。","key":"伸手就能摸到，形容距离近、容易达到","dim":"距离极近","egs":["如今，在上海的老年助餐版图上，社区长者食堂、助餐点星罗棋布，老年助餐服务触手可及。","那一刻，李隆基和杨玉环凄美飘渺的爱情传说，变成了触手可及的历史传奇。"],"rel":""},{"w":"唾手可得","f":7,"def":"唾手：往手上吐口唾沫；可：能够；得：得到。比喻不用费力，很容易就可得到。含褒义，作谓语、定语。","key":"往手上吐口水（准备动手），比喻非常容易得到","dim":"极易获得","egs":["没有唾手可得的成功，只有永不自满的追求。","受疫情影响，一场长途旅行虽不能“说走就走”，但“穿越古今、漫游寰宇”的奇幻之旅因 XR 技术而唾手可得。"],"rel":""}]},{"id":"g119","theme":"c-extent","label":"与生俱来／得天独厚","words":["与生俱来","得天独厚"],"rows":[{"w":"与生俱来","f":10,"def":"比喻生来就有的。","key":"生下来就具有（天性、禀赋）","dim":"生而有之","egs":["好生态，是云南与生俱来的“标签”。","人的一生，有些东西与生俱来、难以改变，有些东西则可以自主选择、自我把握。"],"rel":""},{"w":"得天独厚","f":6,"def":"独具特殊的优越条件。指所处的环境特别好，也指天赋、机遇非常好。褒义词。作谓语、定语。","key":"得到自然界或环境的特别优待（条件优越，多指环境、位置）","dim":"外因优待","egs":["东非国家坦桑尼亚，人文景观丰富多样，旅游禀赋得天独厚。","中国在航空产业供应链方面拥有得天独厚的优势。"],"rel":""}]},{"id":"g120","theme":"a-speed","label":"重塑／重构","words":["重塑","重构"],"rows":[{"w":"重塑","f":10,"def":"（动词）以原本存在为基础，重新打造","key":"重新塑造（形象、格局、信心），含“改变原有形态”","dim":"重新塑造","egs":["媒体融合发展进入“深水区”，全程媒体、全息媒体、全员媒体、全效媒体不断涌现，重塑着媒体内容生产和传播格局。","“提能善政”是重塑基层干部形象的基石。"],"rel":""},{"w":"重构","f":9,"def":"（动词）重新构造、建构。","key":"重新构建（结构、体系、秩序），多指系统内部重组","dim":"重新构建","egs":["重构社会主义话语体系，讲好中国故事。","厚积薄发、动能强劲、大有可为的安徽，正在重构区域人才竞争格局。"],"rel":""}]},{"id":"g121","theme":"i-verb","label":"保留／保存","words":["保留","保存"],"rows":[{"w":"保留","f":9,"def":"1．（动词）保存不变。2．（动词）暂时留着不处理。","key":"保存不变、留着不动（保留意见、保留座位），也可指“留待”","dim":"留着不动","egs":["斗转星移，曾经的莫氏宅院和宗祠早已湮灭于历史尘烟，而街名却保留如初。","不同的意见暂时保留，下次再讨论。"],"rel":""},{"w":"保存","f":6,"def":"（动词）使事物、性质、意义、作风等继续存在，不受损失或不发生变化。","key":"使事物继续存在、不受损失（保存文物、保存实力）","dim":"使不损坏","egs":["照片是保存美好记忆的最佳方式之一。","敦煌莫高窟保存着两千多尊历代彩塑，堪称中华文化的瑰宝。"],"rel":""}]},{"id":"g122","theme":"g-express","label":"涵盖／覆盖等3词","words":["涵盖","覆盖","掩盖"],"rows":[{"w":"涵盖","f":9,"def":"（动词）包括、覆盖。","key":"包容、覆盖（范围、内容、对象），可“涵盖+全部/各方”","dim":"包罗范围","egs":["十三篇评论文选，涵盖政治、社会、经济、文化四个方面。","此次上榜的百强食品企业涵盖食品综合、酒类、软饮料、乳制品…"],"rel":""},{"w":"覆盖","f":7,"def":"1．（动词）遮盖。2．（名词）指地面上的植物，对于土壤有保护作用。","key":"遮盖；也指涉及、遍及（覆盖城乡、覆盖面），强调“铺开”","dim":"遍及铺开","egs":["有效扩大社会保障覆盖面，加强低收入群体兜底帮扶。","“十四五”时期，我国邮政快递行业电子运单、循环中转袋基本实现全覆盖。"],"rel":"覆盖量"},{"w":"掩盖","f":6,"def":"1．（动词）隐藏，隐瞒。2．（动词）从上面盖住。","key":"遮盖住；也指隐瞒（掩盖真相、掩盖事实，多含贬义）","dim":"遮盖隐瞒","egs":["日本应深刻反省历史罪责，同一切美化、掩盖侵略历史的行为彻底切割，真正走和平发展道路。","厚厚的积雪掩盖了大地，使得原本熟悉的风景变得陌生而神秘。"],"rel":""}]},{"id":"g123","theme":"i-verb","label":"目标／目的","words":["目标","目的"],"rows":[{"w":"目标","f":9,"def":"1．（名词）射击、攻击或寻求的对象。2．（名词）计划要达到的标准。","key":"想要达到的境地或标准（具体、可行、有指标）","dim":"可量化的标的","egs":["俄罗斯威胁说，将把叙利亚上空美国领导的盟军飞机做为打击目标。","前三季度 4.8%的增速来之不易，为实现全年目标打下了坚实基础。"],"rel":""},{"w":"目的","f":9,"def":"（名词）想要达到的地点或境地；想要得到的结果。","key":"行为想要达到的结果或境地（偏主观意图）","dim":"行动意图","egs":["我们推进改革的根本目的，是要让国家变得更加富强、让社会变得更加公平正义、让人民生活得更加美好。"],"rel":"目的性"}]},{"id":"g124","theme":"i-verb","label":"契机／机遇等3词","words":["契机","机遇","机会"],"rows":[{"w":"契机","f":9,"def":"（名词）事物转化（多指向积极的方向）的关键、机会。","key":"事物转化的关键时机（转折点）","dim":"关键转折","egs":["一年一度的全国两会，是访地气、察民情的契机，也是聚民智、惠民生的平台。","以筹办北京冬奥会、冬残奥会为契机，我国冬季体育项目竞技实力全面提升，大众冰雪运动发展乘势而上。"],"rel":""},{"w":"机遇","f":7,"def":"（名词）指机会，有利的境遇。","key":"有利的时机、机会（多指外部条件，含“难得”）","dim":"难得的外部时机","egs":["这两个“新消费群体”崛起的背后，是人口高质量发展带来的人口综合红利，也是中国式现代化孕育的市场机遇。","澳门各界未来要鼓足干劲，抓住时代机遇，扎实推动各项事业不断向前发展。"],"rel":""},{"w":"机会","f":6,"def":"（名词）恰好的时候，时机。","key":"恰好的时候、时机，最通用","dim":"通用时机","egs":["希望通过参加消博会等国际性展会，让我们的产品在中国市场受到更多认可，获得更多发展机会。","我们要搭建促进全体劳动者职业可持续发展的“立交桥”，让每个人都有机会通过教育来改变自身的命运。"],"rel":""}]},{"id":"g125","theme":"a-speed","label":"势不可挡／势如破竹","words":["势不可挡","势如破竹"],"rows":[{"w":"势不可挡","f":9,"def":"指来势迅猛，不可抵挡。作谓语、定语。同“势不可当”。","key":"来势迅猛、无法抵挡（多形容潮流、趋势、力量）","dim":"来势难挡","egs":["越是民族危亡之际，中国人民就越能迸发出势不可挡的力量。","中国改革开放的大潮势不可挡。"],"rel":""},{"w":"势如破竹","f":5,"def":"势：形势。破竹：劈开竹子。形势如同劈竹子一样，劈开头上几节，下面各节就顺着刀口裂开了。后用来形容节节胜利，毫无阻碍。作谓语、定语、状语，多含褒义。","key":"形势像劈竹子一样，节节胜利、毫无阻碍（多形容进军、推进）","dim":"节节胜利","egs":["尽管《私人订制》在上映后遭遇恶评，但无论是在排片上还是票房上都势如破竹。","既重实干，又重谋势，方能开创势不可挡、势如破竹的新局面。"],"rel":""}]},{"id":"g126","theme":"i-verb","label":"收集／搜集","words":["收集","搜集"],"rows":[{"w":"收集","f":9,"def":"（动词）使聚集在一起。","key":"把分散的东西聚集起来（简单聚拢，对象可具体）","dim":"聚拢起来","egs":["网络平台的未来发展，收集个人信息边界在哪？"],"rel":""},{"w":"搜集","f":6,"def":"（动词）到处寻找（人或事物）并聚集在一起。","key":"到处寻找并聚集（需要主动搜求，对象多为资料、证据、意见）","dim":"主动搜求","egs":["20 年来，我坚持搜集与南京大屠杀相关的史料文物。","生物小组的同学们经常到野外搜集动植物标本。"],"rel":""}]},{"id":"g127","theme":"f-light","label":"瞻前顾后／进退维谷","words":["瞻前顾后","进退维谷"],"rows":[{"w":"瞻前顾后","f":9,"def":"瞻：向前看；顾：回头看。指看看前面，又看看后面。形容做事之前考虑周密慎重；也形容顾虑太多，犹豫不决。多用于贬义，作谓语、状语。","key":"看看前面又看看后面，形容做事谨慎；也比喻顾虑太多、犹豫不决","dim":"顾虑犹豫","egs":["必须要动态地看、发展地看、“瞻前顾后”地看。","遭遇逆境时，如果理想缺失、格局狭隘，就会瞻前顾后、患得患失。"],"rel":""},{"w":"进退维谷","f":9,"def":"无论是进还是退，都是处在困境之中。形容处境艰难，进退两难。作谓语、定语。同“进退两难”。","key":"进退都陷于困境（客观处境艰难）","dim":"处境两难","egs":["新一波新冠疫情提前暴发令欧洲进退维谷。","张艺谋的商业电影在过去几年，似乎呈现江郎才尽的疲态和进退维谷的尴尬。"],"rel":""}]},{"id":"g128","theme":"g-express","label":"证明／印证等3词","words":["证明","印证","验证"],"rows":[{"w":"证明","f":9,"def":"（动词、名词）用可靠的材料来表明或断定人或事物的真实性。","key":"用可靠材料表明真实性（最通用，也可作名词“证明书”）","dim":"证明真伪","egs":["赛场上运动员的成绩与名次，是证明自己的最好名片。","在诉讼过程中，书面证明是不可或缺的一部分。"],"rel":""},{"w":"印证","f":7,"def":"1．（动词）证明与事实相符。2．（名词）作为进一步证明的事物。","key":"通过对照、事实来证实（多用于假设、说法被证实）","dim":"对照验证","egs":["一桩桩充满正能量的事迹，展现出蓬勃的向上向善力量，印证着大爱中国的美美与共。","檐下这块石板被雨水滴出洞来，真是水滴石穿的最佳印证。"],"rel":""},{"w":"验证","f":6,"def":"（动词）通过实验使得到证实；检验证实。","key":"检验证实（多指通过实验、实践检验）","dim":"检验证实","egs":["在这个科学实验中，我们采用了多种验证方法来确保结果的准确性。"],"rel":"验证性"}]},{"id":"g129","theme":"b-attitude","label":"不置可否／模棱两可","words":["不置可否","模棱两可"],"rows":[{"w":"不置可否","f":8,"def":"不说可以，也不说不可以。指不表明态度。","key":"不说行也不说不行，既不肯定也不否定（多含回避）","dim":"回避表态","egs":["当无端受到责难非议时，不能含糊处理、不置可否，乃至坐视不理。","抗战爆发后，本已淡出政坛的他却坚持留在上海，面对日方多方拉拢，唐绍仪不置可否的态度最终招来杀身之祸。"],"rel":""},{"w":"模棱两可","f":5,"def":"形容态度、主张等含含糊糊，既不肯定，又不否定。","key":"话或态度含糊，可以这样理解也可以那样理解（含“态度不明”）","dim":"含糊两可","egs":["“购房获居留权”这一欧洲相关国家政府都有些模棱两可的政策，到了中国国内部分中介机构的口中，却变成“移民最优途径”。","在大的问题上、在基本的历史价值的认识上不能含含糊糊、模棱两可。"],"rel":""}]},{"id":"g130","theme":"d-relation","label":"沉浸／浸润","words":["沉浸","浸润"],"rows":[{"w":"沉浸","f":8,"def":"1．（动词）浸泡，浸入水中。2．（动词）比喻潜心于某种境界或思想活动中，全神贯注于某种事物。","key":"全神贯注于某种境界或思想活动中（沉浸其中、沉浸回忆）","dim":"全神投入","egs":["当身体沉浸在水中，思绪也随之变得清晰起来。","连日来，不少外国友人走进学校、社区等地，沉浸式感受传统中国年味。"],"rel":""},{"w":"浸润","f":7,"def":"1．（动词、名词）（液体）渐渐渗入，使滋润。2．（动词、名词）比喻精神、思想等像水一样逐渐渗透。","key":"液体渐渐渗入；比喻逐渐感染、熏陶（多指文化、情感慢慢渗透）","dim":"渐渐渗透","egs":["绵绵的细雨浸润着含苞待放的花朵。","现代体育经历奥林匹克精神的浸润，已成为联结全世界人民友谊的桥梁。"],"rel":""}]},{"id":"g131","theme":"a-speed","label":"大行其道／风靡一时","words":["大行其道","风靡一时"],"rows":[{"w":"大行其道","f":8,"def":"指在某范围内广为流传，盛行一时。作谓语、定语。（中性词，多贬义）","key":"某种观点、风气、做法广泛流行（贬义居多为“不良风气”）","dim":"风气盛行","egs":["“洁厕块致癌”谣言何以大行其道？","金庸小说在越南大行其道。"],"rel":""},{"w":"风靡一时","f":7,"def":"形容一个事物在一个时期非常盛行，像风吹倒草木一样。作谓语、定语。","key":"某一时期极为流行（多指商品、文艺作品、时尚）","dim":"一时流行","egs":["曾风靡一时的人人网，要成另一个天涯社区了吗？","《瓦尔特保卫萨拉热窝》1973 年被引进到中国后，风靡一时，留在不少中国观众的记忆中。"],"rel":""}]},{"id":"g132","theme":"f-light","label":"事半功倍／事倍功半","words":["事半功倍","事倍功半"],"rows":[{"w":"事半功倍","f":8,"def":"事：所要做的事情，指措施。功：功效。形容费力小，收效大。含褒义。","key":"费力小而收效大（褒义）","dim":"省力高效","egs":["改革有破有立，得其法则事半功倍，不得法则事倍功半甚至产生负作用。","发挥好政党的积极作用，对提升传播效能可以起到事半功倍的效果。"],"rel":""},{"w":"事倍功半","f":5,"def":"形容做事的方法费力大，收效小。含贬义。","key":"费力大而收效小（效率低）","dim":"费力低效","egs":["改革中搞单兵突进甚至各行其是，就会导致相互掣肘、事倍功半，延误改革进程，影响改革大局。","人才的培养、开发和使用是一门科学，遵循规律则事半功倍，违背科学则事倍功半。"],"rel":""}]},{"id":"g133","theme":"f-light","label":"对症下药／量体裁衣","words":["对症下药","量体裁衣"],"rows":[{"w":"对症下药","f":8,"def":"本义是医生针对患者病症用药，后比喻针对事物的问题所在，采取有效的措施。含褒义。同“对症开方”。","key":"针对病症用药，比喻针对具体问题采取有效措施（多指治病、纠正问题）","dim":"针对问题","egs":["从严治理干部关键要对症下药。","认定了划分标准，接下来就是对症下药地进行改造了。"],"rel":"对症开方"},{"w":"量体裁衣","f":3,"def":"按身材裁剪衣服。也比与按实际情况办事。","key":"按身材裁剪衣服，比喻根据实际情况办事（强调“适合对象”）","dim":"适合实际","egs":["大企业是经济发展的顶梁柱，往往也存在着跨区域、多税种的复杂涉税诉求，这就更需要我们聚焦精细服务，做到量体裁衣。"],"rel":""}]},{"id":"g134","theme":"b-attitude","label":"敷衍了事／虚与委蛇","words":["敷衍了事","虚与委蛇"],"rows":[{"w":"敷衍了事","f":8,"def":"指办事马马虎虎、不认真，只求应付过去就算完事。","key":"做事马虎应付，草草了结（态度不负责）","dim":"马虎了结","egs":["基层干部要心系群众、真正为群众办实事，切莫打官腔说空话，敷衍了事。","对任何一项工作、一个项目、一件民生实事，都不能有马马虎虎、敷衍了事的态度。"],"rel":"敷衍塞责：表面应付，对应负的责任搪塞了事。"},{"w":"虚与委蛇","f":4,"def":"虚：不真实，假意。与：跟。委蛇：敷衍。指对人虚情假意，敷衍应酬。","key":"对人假意敷衍应酬（多指人际应付，书面）","dim":"假意应酬","egs":["批评贵在坦诚真挚，来不得虚与委蛇，甚或苦心算计。","上级装模作样不下实功，下级也便虚与委蛇虚应一番。"],"rel":""}]},{"id":"g135","theme":"d-relation","label":"涵养／滋养","words":["涵养","滋养"],"rows":[{"w":"涵养","f":8,"def":"1．（名词）能控制情绪的功夫，修养。2．（动词）蓄积并保持（水分等）。","key":"滋润养育；也指修养、内蕴（涵养水源、涵养品格）","dim":"蓄养内蕴","egs":["容颜终会消逝，只有内在的涵养才能愈久弥新，醇厚迷人。","湿地是生命之源，被誉为地球之肾，有助于涵养水源、调节气候、维护生物多样性。"],"rel":""},{"w":"滋养","f":8,"def":"1．（动词）供给养分，培养。2．（名词）营养，养料。","key":"供给养分使生长（滋养身心、滋养土地），含“供养”意味","dim":"供给养分","egs":["春雨绵绵，滋养着大地，让万物焕发生机。","用中华优秀传统文化滋养社会主义核心价值观。"],"rel":""}]},{"id":"g136","theme":"g-express","label":"记录／记载","words":["记录","记载"],"rows":[{"w":"记录","f":8,"def":"（动词、名词）把所见、所闻、所思、所想等通过一定的手段保留下来。","key":"把听到的、发生的事写下来；也指记录下来的材料（动词名词皆可，具体）","dim":"随事记下","egs":["历史是最好的老师，它忠实地记录下每一个国家走过的足迹。","夏秋高温日数破历史记录。"],"rel":""},{"w":"记载","f":8,"def":"1．（动词）把事情记录下来。2．（名词）指记录事情的文字。","key":"把事情写进书报等文字材料（多指正式、书面、史册）","dim":"入册载录","egs":["古老的碑文上记载着一段神秘的传说，引发了人们的好奇和探究。","晚清时期，关于食用南瓜子的记载颇丰。"],"rel":""}]},{"id":"g137","theme":"b-attitude","label":"竭泽而渔／杀鸡取卵","words":["竭泽而渔","杀鸡取卵"],"rows":[{"w":"竭泽而渔","f":8,"def":"排尽湖中或池中的水捕鱼。比喻做事只顾眼前的利益，丝毫不为以后打算。含贬义。同“涸泽而渔”。","key":"排干池水捕鱼，比喻只顾眼前利益、不留余地（多指资源开发）","dim":"不留余地","egs":["短期来看，提高景区门票会带来更多的地方财政收入，但从长远来看这种“门票经济”无异于涸泽而渔，非但无法带动当地经济发展，甚至会严重影响中国旅游业的发展。","在空间格局方面，村村点火、户户冒烟的景象不复存在，有水快流、竭泽而渔的发展模式得到根本改变。"],"rel":""},{"w":"杀鸡取卵","f":7,"def":"为了要得到鸡蛋，不惜把鸡杀了。比喻贪图眼前的好处而不顾长远利益。含贬义，作谓语、宾语、定语。","key":"杀鸡取蛋，比喻贪图眼前微利而损害根本利益","dim":"断本取利","egs":["工业革命以来，竭泽而渔、杀鸡取卵式的发展方式导致了全球性生态危机。","商家为了追逐利益明知故犯的行为无异于“杀鸡取卵”，最终只会自食其果。"],"rel":""}]},{"id":"g138","theme":"c-extent","label":"巧夺天工／鬼斧神工","words":["巧夺天工","鬼斧神工"],"rows":[{"w":"巧夺天工","f":8,"def":"夺：压倒，胜过。形容人工的精巧胜过天然。比喻技艺精妙高超。含褒义，作谓语、定语。","key":"人工的精巧胜过天然，形容技艺极其精巧（多指工艺品、建筑）","dim":"人工胜天然","egs":["在大连首届寿山田黄石展暨工艺美术大师石雕作品展上，一组巧夺天工的寿山石石雕作品格外吸引眼球。","整个灯楼设计构造可谓巧夺天工！"],"rel":""},{"w":"鬼斧神工","f":7,"def":"原义是像是鬼神制作出来的。形容艺术技巧高超，不像是人力所能达到的。作定语、主语。（多搭配“大自然”）","key":"像鬼神制作的一样，形容技艺精巧（多用于自然景观、雕塑等）","dim":"神妙之极","egs":["鬼斧神工的大自然绘就了昭通秀美神奇的风光。","大自然的鬼斧神工为各类物种铸就了一个舒适的生态家园。"],"rel":""}]},{"id":"g139","theme":"g-express","label":"曲高和寡／阳春白雪","words":["曲高和寡","阳春白雪"],"rows":[{"w":"曲高和寡","f":8,"def":"乐曲的格调越高，能跟着唱的人就越少。旧指知音难得。现比喻思想言论或作品不通俗，能理解的人很少。作谓语、定语。","key":"曲调越高雅，能跟着唱的人越少，比喻言论或作品高深、知音少","dim":"高深少知音","egs":["在多数人眼中，诗歌一直是种曲高和寡、不食人间烟火的雅艺。","公共管理研究方法不能变得更加复杂难懂和曲高和寡，而应做到深入浅出，让人们看得懂、学得会。"],"rel":""},{"w":"阳春白雪","f":6,"def":"原指战国时期楚国的一种较高级的歌曲。后泛指高深典雅、不够通俗易懂的文艺作品。","key":"战国时楚国的高雅歌曲，比喻高深的、不通俗的文艺作品（常与“下里巴人”对举）","dim":"高雅不俗","egs":["阳春白雪般的诗篇，是文人墨客心中的至高追求。","在吴江，丝绸文化不仅是阳春白雪，也是与老百姓息息相关的日常生活。"],"rel":""}]},{"id":"g140","theme":"g-express","label":"认识／认知","words":["认识","认知"],"rows":[{"w":"认识","f":8,"def":"1．（名词）指人的头脑对客观世界的反映。2．（动词）认得，了解。","key":"对事物的感知和判断（最通用，可作动词“认识某人”）","dim":"感知判断","egs":["大家务必提高思想认识，牢固树立“没有安全就没有审查调查”理念。","认识世界发展大势，跟上时代潮流，是一个极为重要并且常做常新的课题。"],"rel":""},{"w":"认知","f":7,"def":"（动词、名词）通过思维活动认识、了解。","key":"通过思维活动获得知识、形成概念的过程（心理学术语，书面）","dim":"思维获取","egs":["改变对文学的认知，不仅让我们直面文化的复杂性，更帮助我们在涵纳了 AI 的更高维度上，珍视人类的精神主体，充分释放人类的创造力。","语言是认知世界最重要的工具。"],"rel":""}]},{"id":"g141","theme":"c-extent","label":"身临其境／设身处地","words":["身临其境","设身处地"],"rows":[{"w":"身临其境","f":8,"def":"指亲身到了某个境地。","key":"亲自到了那个境地（强调亲历现场）","dim":"亲历现场","egs":["无论是千里之外的博物馆展览，还是年代久远的历史场景，观众都可以通过虚拟现实技术随时随地身临其境。","通过情景教学、沉浸式体验等教学方式，可以让学生身临其境，提升学习兴趣。"],"rel":""},{"w":"设身处地","f":5,"def":"把自己放在别人所处的地位上考虑。指替别人着想。","key":"设想自己处在别人的境地（强调为人着想）","dim":"代人着想","egs":["参与社会生活，有一种能力很重要，即“设身处地”地理解他人的能力。","为了能设身处地地为搬迁群众考虑，“夜校”里的老师换了一拨又一拨。"],"rel":""}]},{"id":"g142","theme":"i-verb","label":"树立／建立","words":["树立","建立"],"rows":[{"w":"树立","f":8,"def":"（动词）建立（多用于抽象的好的事情）","key":"建立（多指抽象的、正面的：榜样、信心、形象、观念）","dim":"正面抽象","egs":["我们要把职业教育发展好，要树立工匠精神，把他们的待遇条件保障好。","通过树立典型，可以激励更多的人积极参与到社会公益事业中来。"],"rel":""},{"w":"建立","f":7,"def":"（动词）让某种事物从无到有的一个过程。有开始成立，开始形成，开始产生等含义在内。","key":"开始成立、开始产生（制度、关系、联系），最通用","dim":"从无到有","egs":["建立社会主义市场经济体制是一个前无古人的伟大创造。","中国是我们最重要的贸易伙伴之一，我们能做的就是和中国建立良好的关系。"],"rel":""}]},{"id":"g143","theme":"c-extent","label":"无懈可击／天衣无缝","words":["无懈可击","天衣无缝"],"rows":[{"w":"无懈可击","f":8,"def":"懈：松懈，引申为漏洞、破绽。指没有一点漏洞可以被攻击或挑剔，形容十分严密。作谓语、定语。","key":"没有弱点可以让人攻击，形容十分严密（多指论点、防守、逻辑）","dim":"严密无破绽","egs":["虽然广州恒大的进攻非常犀利，但我们认为他们的防线并非无懈可击。","看似无懈可击的DNA 检测技术，为何频频制造冤假错案？"],"rel":""},{"w":"天衣无缝","f":3,"def":"天衣：天上神仙穿的衣服。比喻事物完美自然，没有破绽。","key":"神话中天上神仙的衣服没有衣缝，比喻事物（诗文、计划）完美自然、毫无破绽","dim":"浑然无痕","egs":["补衣服讲究天衣无缝，修复更注重加固、延长文物寿命。","如果想偷梁换柱，妄图编造“天衣无缝”的谎言采取“补救”措施，注定是竹篮打水一场空。"],"rel":""}]},{"id":"g144","theme":"c-extent","label":"一目了然／一览无余","words":["一目了然","一览无余"],"rows":[{"w":"一目了然","f":8,"def":"一眼就看得很清楚。形容事物、事情原委很清晰，一看就知道是怎么回事。作谓语。","key":"一眼就看得很清楚（强调清楚、易懂，多指事物本身明了）","dim":"清楚易懂","egs":["集控智能系统的大屏幕上，各个生产流程一目了然。","中美到底谁坚持了“人民至上、生命至上”，答案一目了然。"],"rel":""},{"w":"一览无余","f":7,"def":"指一眼看去，所有的景物全看见了，毫无遗漏。（形容视野开阔、看得清楚）","key":"一眼看去全都看在眼里（强调视野开阔、尽收眼底，无遗漏）","dim":"尽收眼底","egs":["站在望火楼前，举目望去，绿意一览无余。","在西部矿业视频集成平台，生产作业情况一览无余。"],"rel":"一览无遗、一览而尽：指一眼望去，事物就全都收入眼底。"}]},{"id":"g145","theme":"i-verb","label":"植入／嵌入等3词","words":["植入","嵌入","渗入"],"rows":[{"w":"植入","f":8,"def":"1．（动词）将某个事物放置到另一个事物当中的过程。2．（动词）在影视、综艺等中加入软性广告。","key":"把某物放入（体内、剧中），现多指商业信息、观念的有意嵌入","dim":"有意嵌入","egs":["齐鲁医院完成全国首例心内科主导的人工心脏植入术。","开展义务植树活动，意义在于通过一年年的接续植绿，将改善生态、人人有责的意识植入学生们心中。"],"rel":""},{"w":"嵌入","f":6,"def":"（动词）把较小的物体嵌入较大的物体内。","key":"把较小的物体卡进另一物体中（嵌入芯片、嵌入框架）","dim":"嵌卡其中","egs":["将公共服务嵌入社区，让群众在家门口享受到优质普惠的公共服务，是“关键小事”，更是“民生大事”。","设计师将 LED 灯嵌入到家具中，营造出温馨而独特的氛围。"],"rel":""},{"w":"渗入","f":5,"def":"1．（动词）液体慢慢地渗到里面去。2．（动词）比喻一种事物对另一事物缓慢的渗透、影响。","key":"液体慢慢透过；比喻某种势力、思想逐渐进入","dim":"慢慢透入","egs":["雨水慢慢地渗入干燥的土壤，滋润了每一颗种子。","网络技术以及互联网精神的渗入，正在极大地改变金融领域。"],"rel":""}]},{"id":"g146","theme":"i-verb","label":"追寻／追捧等3词","words":["追寻","追捧","追逐"],"rows":[{"w":"追寻","f":8,"def":"（动词）跟随，跟踪寻找。","key":"跟踪寻找（踪迹、足迹、理想），含“追”的动态","dim":"跟踪寻找","egs":["失踪儿童的父母焦急万分，他们联合警方和社会力量，持续追寻着孩子的下落。","媒体的责任是要报道和追寻社会真相。"],"rel":""},{"w":"追捧","f":6,"def":"（动词）指追逐捧场。比喻事物被认可，身价被抬高。（中性词）","key":"追逐捧场（对明星、潮流），含“崇拜热捧”（多含贬义）","dim":"热捧","egs":["湖北武汉市东西湖区兔年元宵庙会上，现做现煮的汤圆，受到市民追捧。","一些影视创作团队不再把主要精力放在打磨作品上，而是致力于追捧所谓的“流量明星”。"],"rel":""},{"w":"追逐","f":6,"def":"（动词）追赶，迅速积极地追寻。","key":"追赶（具体对象）；也指追求（名利、利益）","dim":"追赶追求","egs":["亚冬会不仅为运动健儿们提供了一个追逐梦想的舞台，更为弘扬中华传统文化提供了一个绝佳的平台。","人一旦沉迷于追逐名利，就会迷失自我。"],"rel":""}]},{"id":"g147","theme":"c-extent","label":"比肩／媲美","words":["比肩","媲美"],"rows":[{"w":"比肩","f":7,"def":"（动词）并肩，比喻相当、比美。含褒义。","key":"肩膀挨肩膀，比喻地位、成就相当（也指“比肩而立”）","dim":"地位相当","egs":["歼-20 足以与美国 F-22 隐形战机比肩。","走访中，我们感受到国产动画在技术应用方面已经比肩世界一流。"],"rel":"比肩同行"},{"w":"媲美","f":5,"def":"（动词）美好的程度比得上，比美。","key":"美好的程度不相上下（多用于事物、成就的比较）","dim":"美好相当","egs":["有着“素中之荤”美誉的花生，其营养价值比粮食类高，可与鸡蛋、牛奶、肉类等一些动物性食物媲美。","现在的中国品牌不仅有媲美国际品牌的设计和质量，更有亲民的价格和对中国人使用习惯的熟知。"],"rel":""}]},{"id":"g148","theme":"c-extent","label":"鞭长莫及／力不能及","words":["鞭长莫及","力不能及"],"rows":[{"w":"鞭长莫及","f":7,"def":"虽然鞭子很长，但总不能打到马肚子上。比喻距离太远或力量达不到而无能为力。作谓语，定语。","key":"鞭子虽长，打不到马肚子，比喻力量达不到（距离远）","dim":"距离力不及","egs":["过去人们总觉得广大农村地处偏僻，各种法律规章制度对村干部而言鞭长莫及。","南海诸岛自古以来就是中国领土，但南海海域广袤辽阔，张超每次驾机执行任务，总有一种鞭长莫及的遗憾。"],"rel":""},{"w":"力不能及","f":7,"def":"指力量无法达到。同“力所不及”、“力所不逮”、“力有不逮”。","key":"能力达不到（自身力量不足）","dim":"能力不足","egs":["虽然对那个项目充满热情，但由于资源有限，力不能及，最终只能遗憾地放弃。"],"rel":""}]},{"id":"g149","theme":"b-attitude","label":"不以为然／不以为意","words":["不以为然","不以为意"],"rows":[{"w":"不以为然","f":7,"def":"不认为是正确的，表示不同意或否定。","key":"不认为是对的（不赞同对方观点）","dim":"不认为对","egs":["未入编辑这一行之前，我曾经对所谓“采风”颇不以为然，认为无非是巧立名目的游山玩水。"],"rel":""},{"w":"不以为意","f":1,"def":"不放在心上。指对某人或某事不加重视，不认真对待。","key":"不把它放在心上、不重视（不当回事）","dim":"不放在心上","egs":["面对周围人的冷嘲热讽，她选择不以为意，坚持自己的信念，努力追求梦想，最终证明了自己的实力。","其实人还没有离任，就备受当地民众诟病，但不以为意，这是对民意的蔑视，更是对权力来源的错误认知。"],"rel":""}]},{"id":"g150","theme":"i-verb","label":"锤炼／磨炼等3词","words":["锤炼","磨炼","锻炼"],"rows":[{"w":"锤炼","f":7,"def":"1．（动词、名词）磨炼，历练。2．（动词、名词）刻苦钻研，反复琢磨使艺术等精练、纯熟。","key":"反复锤打使精炼；比喻反复琢磨使精熟（语言、意志、本领）","dim":"反复打磨","egs":["孟子更是以“天将降大任于斯人也，必先苦其心志，劳其筋骨”来强调逆境对人格的锤炼。","他还广泛浏览古今诗词，学习锤炼语言和推敲韵律。"],"rel":"千锤百炼"},{"w":"磨炼","f":7,"def":"（动词、名词）（在艰难困苦的环境中）锻炼。","key":"在艰难困苦中锻炼（意志、品格），强调“经受考验”","dim":"经受考验","egs":["年轻干部应珍惜韶华，以只争朝夕的姿态磨炼自己。","只有在一次又一次的磨炼中，才能练就一颗坚韧之心。"],"rel":""},{"w":"锻炼","f":5,"def":"1．（动词）通过生产劳动、社会活动和工作实践，使觉悟、工作能力等提高。2．（动词）指锻造或冶炼。3．（动词）比喻通过体育运动增强体质。","key":"通过运动或实践增强体质、增长才干，最通用","dim":"通用训练","egs":["要加倍珍惜在基层一线实践锻炼的机会，主动到基层去经风雨、见世面、壮筋骨。","锻炼冶金，是战国时期的重要成就。"],"rel":""}]},{"id":"g151","theme":"b-attitude","label":"独善其身／明哲保身","words":["独善其身","明哲保身"],"rows":[{"w":"独善其身","f":7,"def":"原指修身养性，保全己身，不管世事。现多指只顾自己，不管他人。含贬义，作谓语、定语，多与否定词连用。（常用语境要素：个人与外部的对比、保全保护）","key":"独自修养身心、保持节操（原指不得志时修身）；现也指只顾自己、不管他人","dim":"只顾自己","egs":["人类是荣辱与共的命运共同体，重大危机面前没有任何一个国家可以独善其身。","中国式现代化不是中国独善其身的现代化。"],"rel":""},{"w":"明哲保身","f":7,"def":"明哲：聪明有智慧。1．原指聪明有智慧之人，善于趋安避危，保全自身。有褒义。2．现在也指为了保住个人利益而回避原则斗争的处世态度。有贬义。作谓语、定语。","key":"明智的人善于保全自己，现多指回避斗争、怕犯错而保全个人（含贬义）","dim":"回避保身","egs":["科研只能实事求是，不能明哲保身，否则受害的将是患者。","谦和是谦虚、谦逊者的表情和态度。谦和之人退能明哲保身，进能感化他人。"],"rel":""}]},{"id":"g152","theme":"b-attitude","label":"釜底抽薪／扬汤止沸","words":["釜底抽薪","扬汤止沸"],"rows":[{"w":"釜底抽薪","f":7,"def":"抽去锅底下的柴火。比喻从根本上解决问题。","key":"从锅底下抽掉柴火，比喻从根本上解决问题（褒义）","dim":"根本解决","egs":["杜绝“奢华培训”，以“社会化”的方式完善管理固然甚好，而撤销培训中心和招待所，更可谓是“釜底抽薪”。","暗访只是扬汤止沸，管住权力才是釜底抽薪。"],"rel":""},{"w":"扬汤止沸","f":6,"def":"把锅里开着的水舀起来再倒回去，使它凉下来不沸腾。比喻办法不彻底，不能从根本上解决问题。作谓语、定语，含贬义","key":"把开水舀起来再倒回去使不沸腾，比喻办法不彻底、不能根本解决","dim":"治标不治本","egs":["即使一个社会有不少个人和单位进行捐赠，那对于缩小该社会各阶层贫富差别也只起扬汤止沸的极小或个别作用。","靠行政干预国内演艺团体“走出去”只能是扬汤止沸，因为不少演出团体由企业赞助，或者自掏腰包，无须报批。"],"rel":""}]},{"id":"g153","theme":"d-relation","label":"浑然一体／浑然天成","words":["浑然一体","浑然天成"],"rows":[{"w":"浑然一体","f":7,"def":"1．融合成一个整体，不可分割。2．形容文章绘画等，布置匀整，结构谨严。作谓语、定语。","key":"融合成一个整体，不可分割（多指画面、结构、自然与人文）","dim":"融为一体","egs":["写别人与写自己，对他而言是难以分割、浑然一体的。","经过近两年时间的田野发掘，徐显秀墓壁画重见天日。从墓道，经过过洞、天井、甬道到墓室，满壁施画，浑然一体。"],"rel":""},{"w":"浑然天成","f":6,"def":"1．形容诗文结构严密自然，用词运典毫无斧凿痕迹。2．亦形容人的才德完美自然（少见）。3．也可形容事物无人工雕琢痕迹。作谓语、定语。","key":"自然形成的整体，没有斧凿痕迹（多指诗文、艺术自然完美）","dim":"天成无痕","egs":["人文景观与自然环境浑然天成、融为一体，才能给人以美的享受。","像“远上寒山石径斜”这样的名句，几乎是每一代小朋友开蒙必读，这个读音不仅合辙押韵且浑然天成。"],"rel":""}]},{"id":"g154","theme":"a-speed","label":"烟消云散／销声匿迹","words":["烟消云散","销声匿迹"],"rows":[{"w":"烟消云散","f":7,"def":"比喻事物全部消失。同“烟消雾散”。","key":"像烟云消散一样消失得无影无踪（多指情绪、疑虑、气氛）","dim":"消散无影","egs":["在流了这么多的眼泪以后，这许多日子来的阴郁的思想都烟消云散了。"],"rel":""},{"w":"销声匿迹","f":5,"def":"销声：消除声音。匿迹：隐匿踪迹。指隐藏起来或不公开露面。同“消声匿迹”、“匿迹销声”。","key":"不再公开讲话、不再露面，形容隐藏起来（人或事物不再出现）","dim":"隐藏不露面","egs":["一个曾经繁华一时的西域重镇，在此后的 1500 多年里再次销声匿迹。"],"rel":""}]},{"id":"g155","theme":"f-light","label":"驾轻就熟／轻车熟路","words":["驾轻就熟","轻车熟路"],"rows":[{"w":"驾轻就熟","f":6,"def":"赶着轻载的车走在熟悉的路上。比喻对所做的事情熟悉，办起来容易。","key":"驾轻车、走熟路，比喻对事情熟悉、做起来容易（强调“熟练”）","dim":"熟练易做","egs":["经过刻苦专业训练和长期实地操作，如今的李培生对这个工作已是驾轻就熟。","如今，非遗人已经对接上直播带货这一新业态，驾轻就熟地运用起跨界组合、内容电商、文化带货等新技能。"],"rel":""},{"w":"轻车熟路","f":3,"def":"轻车：负载轻的车子。驾着负载很轻的车子，走熟悉的道路。比喻事情又轻松又熟悉，办起来很容易。","key":"驾轻车走熟路，比喻对情况熟悉、做起来省力（强调“路径熟”）","dim":"路径熟悉","egs":["对于写信息写调研我可以说是轻车熟路,至于讲这个政治课题,当时着实难为我了。"],"rel":""}]},{"id":"g156","theme":"c-extent","label":"淋漓尽致／酣畅淋漓","words":["淋漓尽致","酣畅淋漓"],"rows":[{"w":"淋漓尽致","f":6,"def":"形容渗透了水或湿淋淋往下滴的样子。形容事情做得十分畅快或文章、谈话表达得十分详尽透彻。作定语、状语、补语，含褒义。","key":"形容文章、说话详尽透彻；也形容暴露得很彻底","dim":"详尽透彻","egs":["这些景象都深深地将勤劳持家的温馨场景淋漓尽致地描画出来。","该服务采用了高清画质，尤其是在内容创作方面，力求将每一个细节展现得淋漓尽致。"],"rel":"淋漓"},{"w":"酣畅淋漓","f":4,"def":"酣畅：痛快。淋漓：畅快的样子。形容非常畅快、舒适，情感得到充分抒发。","key":"形容非常畅快（多指书画、文章、抒发情感）","dim":"畅快尽兴","egs":["今年春节档，票房和口碑双丰收的《红海行动》让影迷们看得酣畅淋漓。","一条人工扎制的龙，却被舞活过来，舞成酣畅淋漓的一道景观。"],"rel":""}]}],"solo":[{"w":"创造","f":37,"def":"（动词）建立、想出或做出从未有过的事物。","egs":["中国共产党团结带领中国人民，创造了新时代中国特色社会主义的伟大成就，对世界其他国家和政党具有重要参考价值。"]},{"w":"发展","f":35,"def":"1．（动词）事物由小到大、由简单到复杂、由低级到高级的变化。2．（动词）组织规模等扩大。3．（名词）指变化的趋势。","egs":["近年来，国家林草局深入践行大食物观，以发展经济林和林下经济为主要抓手，加快推动森林食物生产扩面增量提质。"]},{"w":"一脉相承","f":30,"def":"从同一血统、派别世代相承流传下来。比喻某种思想、行为或学说之间有继承关系。作谓语、定语。","egs":["教育实践活动的三个环节一脉相承、环环相扣。"]},{"w":"改变","f":30,"def":"1．（动词）事物变得和原来不一样，多为显著的差别。2．（名词）变化。","egs":["城乡关系的面貌一改变，整个社会的面貌也跟着改变。"]},{"w":"层出不穷","f":28,"def":"指接连不断地出现，没有穷尽。偏正式结构；在句中一般作谓语、定语。","egs":["在视觉经济日益发达的今天，各式各样的选美活动层出不穷，凤凰卫视有“中华小姐”，亚洲电视有“亚洲小姐”，“港姐”背后的光环早已退却。"]},{"w":"影响","f":28,"def":"1．（动词）对他人或周围事物起作用。2．（名词）对人或事物所起的作用。","egs":["强冷空气影响北方地区。"]},{"w":"传承","f":26,"def":"指对某某学问、技艺、教义等，在师徒间的传授和继承的过程。泛指对前人的经验进行传授和继承并发扬发展的过程。","egs":["历史文化遗产所蕴含的理念、智慧、气度、神韵，彰显中国文化、激荡中国精神、传承文明根脉。"]},{"w":"创新","f":26,"def":"1．（动词）抛开旧的，创造新的。2．（名词）新意，创造性。","egs":["智慧党建体验中心协助该单位将智慧党建产品与职工生活相结合，把院内公共区域升级为智慧党建区，丰富职工院内生活的同时，创新党内生活形式。"]},{"w":"故步自封","f":24,"def":"故步：原来所走的步子。封：限制在一定的范围内。比喻因循守旧，安于现状，不求创新进取。同“固步自封”。作谓语、定语。含贬义。（更侧重满足于现状，不求上进）","egs":["他们非常注意世界科学的新动向，紧紧跟上科学发展的步伐，决不固步自封。"]},{"w":"丰富","f":23,"def":"1．（形容词）种类多或数量大。2．（动词）使丰富。","egs":["传信、辟谣、科普、鼓劲……在抗击疫情这场只能赢不能输的战役中，人民网用丰富的短视频内容，实现了主流媒体的多重功能。"]},{"w":"突破","f":23,"def":"1．（动词）集中兵力向一点进攻，打开缺口。2．（动词）打破（限制、困难等）或超过。3．                                             （名词）打破。","egs":["鹅鸭在里面活动筋骨，它们也曾用嘴衔着网线啄呀啄，试图突破防线，但均以失败告终。"]},{"w":"简单","f":22,"def":"1．单纯；不复杂。2．经历、能力等平凡普通。3．草率；不细致。","egs":["能源转型的“先立后破”，不是简单的化石能源和可再生能源此消彼长、一蹴而就的问题，而是需要两者相互配合。"]},{"w":"一蹴而就","f":22,"def":"踏一步就成功。形容事情非常容易，一下子就能成功。常用作否定句。","egs":["制度的完善、纪律的执行不可能一劳永逸、一蹴而就。"]},{"w":"延伸","f":22,"def":"在宽度、大小、范围上向外延长、伸展。","egs":["推进全面从严治党向基层延伸，扎实做好抓基层强基础的工作。"]},{"w":"有的放矢","f":22,"def":"的：箭靶。矢：箭。对着靶子射箭。比喻目的性强，有针对性。","egs":["多从内因着眼、着手、着力，找准症结就有的放矢、对症下药。"]},{"w":"承载","f":21,"def":"（动词）托着物体，承受它的重量。","egs":["承载人民重托，乘势而上迈向新征程。"]},{"w":"源远流长","f":21,"def":"源头远，水流长。多比喻历史悠久。作谓语、定语，含褒义。","egs":["中国和印度尼西亚隔海相望，两国友好关系的历史源远流长。"]},{"w":"水到渠成","f":20,"def":"水一流到，沟渠自然形成。比喻条件成熟，事情就会自然成功。含褒义，在句中一般作谓语、定语。","egs":["我深知，友好关系的建立并非一蹴而就，必须通过人与人之间的长久交流而水到渠成。"]},{"w":"稳定","f":20,"def":"1．（形容词）平稳安定，没有变动。2．（动词）使之平稳、安定。","egs":["当期就业形势总体保持稳定。"]},{"w":"调整","f":19,"def":"（动词、名词）改变原有的情况，使适应客观环境和要求。","egs":["实际上，学科专业调整工作一直在进行。"]},{"w":"复杂","f":19,"def":"（形容词）事物的种类、头绪等多而杂，跟“简单”相对。","egs":["今天，面对严峻复杂的国际疫情和世界经济形势，尤须运用底线思维来明晰立身之本和发展方向，统筹推进疫情防控和经济社会发展工作。"]},{"w":"模糊","f":19,"def":"1．（形容词）不分明，不清楚。2．（动词）使不清晰。","egs":["随着技术的进步，现有导弹类别之间的界限正在变得模糊。"]},{"w":"融入","f":19,"def":"（动词）融合；混入、混合。泛指物质间的彼此接纳。","egs":["把红色基因融入高校校园文化，达到以文化人、以文育人。"]},{"w":"薪火相传","f":19,"def":"前一根柴刚烧完，后一根柴已经烧着，火永远不熄。比喻通过师生传授，使学问技艺得以一代代承传。也比喻种族、文化、精神等代代相传。","egs":["80 年前的长征，没有被岁月的长河磨砺销蚀，而是在时代的变迁中淬火升华，已经化身为弥足珍贵的民族精神，薪火相传，经久不息。"]},{"w":"朴实","f":18,"def":"1．（形容词）朴素，不浮夸。2．（形容词）质朴诚实。","egs":["这种笨拙的织布方式，虽然效率不高，却形成了朴实无华、带着泥土气息的织物。"]},{"w":"精雕细琢","f":18,"def":"形容做事仔细用心。多指艺术品的创作。作谓语或定语。","egs":["工匠精神体现着劳动者独具匠心、精雕细琢、尽善尽美的追求和坚守。"]},{"w":"强化","f":18,"def":"（动词）加强，使坚强巩固。","egs":["2025 年我国将强化气象灾害防治体系建设。"]},{"w":"体验","f":18,"def":"（动词、名词）通过实践来认识周围的事物，亲身经历。","egs":["“人脸替换明星专区”这一创新功能利用了最新的人工智能技术，旨在为广大用户提供更加丰富的娱乐体验。"]},{"w":"系统","f":18,"def":"1．（名词）同类事物按一定的关系组成的整体。2．（形容词）有条理地，连贯地。","egs":["人类的免疫系统相当不可思议。"]},{"w":"延续","f":18,"def":"（动词）照原来的样子持续下去。","egs":["最是一年春好处，期待优质产品和服务的温度，不断延续网红城市的热度，最终转化为老百姓对文旅消费的满意度。"]},{"w":"必然","f":17,"def":"确定不移的，不可避免的。（跟“偶然”相对）。","egs":["风腐问题同根同源，必然要求同查同治。"]},{"w":"变幻莫测","f":17,"def":"指事物变化很多不能预料，变化多端难以揣测。作谓语、定语，多用于气候、形势、命运等。","egs":["初夏 5 月，驻足拉萨河畔，天蓝得澄澈，成朵的云白得炫目，变幻莫测。"]},{"w":"感受","f":17,"def":"1．（动词）接受，受到。2．（名词）接触外界事物得到的影响，体会。","egs":["湖北是我感受中国魅力最重要的窗口。"]},{"w":"构建","f":17,"def":"（动词）建立（多用于抽象事物）。","egs":["携手构建更公正世界和更可持续星球的中巴命运共同体。"]},{"w":"科学","f":17,"def":"1．（名词）反映自然、社会、思维等的客观规律的分科的知识体系。2．（形容词）合乎科学的。","egs":["以优质丰富的内容和喜闻乐见的形式，激发青少年崇尚科学、探索未知的兴趣。"]},{"w":"明确","f":17,"def":"1．（形容词）清晰明白而确定不移。2．（动词）使清晰明白而确定不移。","egs":["会议从八个方面明确未来五年发展的主要目标。"]},{"w":"绵延不绝","f":17,"def":"绵延：延续不断的样子。形容连续不断，一直延续。","egs":["我们的文化绵延不绝，我们的创造生生不息！"]},{"w":"无与伦比","f":17,"def":"指事物非常完美，没有能够与它相比的。作谓语、定语。","egs":["我每次访问中国都能看到许多变化，中国发展成就无与伦比。"]},{"w":"与时俱进","f":17,"def":"时：时间。俱：一起，一同。进：前进。与时间一起前进。也指随着时代的发展而不断发展、前进。","egs":["马克思主义具有与时俱进的理论品格。"]},{"w":"独立","f":16,"def":"1．（动词）单独地站立。2．（动词、形容词）不依靠他人。3．（动词）脱离原来所属单位，成为另一单位。","egs":["他在人群中独立着，目光坚定，仿佛不受周围喧嚣的影响。"]},{"w":"独特","f":16,"def":"（形容词）独有的，特殊的。","egs":["雕塑作为一种立体艺术，具有独特的表现力。"]},{"w":"广泛","f":16,"def":"（形容词）涉及的方面广，范围大。","egs":["人大代表密切同人民群众的联系，做到深入了解民情、真实反映民意、广泛集中民智，当好党和国家联系人民群众的桥梁。"]},{"w":"基础","f":16,"def":"（名词）事物发展的根本或起点。","egs":["我国经济基础稳、优势多、韧性强、潜能大。"]},{"w":"兼容并蓄","f":16,"def":"把不同内容、不同性质的东西收下来，保存起来。同“兼容并包”。","egs":["中华文明探源工程揭示出大量有趣的文明细节，佐证着中华文明兼容并蓄的特征。"]},{"w":"精益求精","f":16,"def":"精：完美，好；益：更加。比喻已经很好，但还要追求更加完美。作谓语、定语，含褒义。","egs":["工匠以工艺专长造物，在专业的不断精进与突破中演绎着“能人所不能”的精湛技艺，凭借的是精益求精的追求。"]},{"w":"挑战","f":16,"def":"1．（动词）鼓动对方跟自己竞赛。2．（动词）主动尝试战胜对方。3．（名词）指需要应付、处理的局面或难题。","egs":["由本届世界杯“最大黑马”摩洛哥队挑战卫冕冠军法国队。"]},{"w":"喜闻乐见","f":16,"def":"喜欢听，乐意看。形容很受欢迎。作谓语、定语，含褒义。（主语一般是人）","egs":["组织开展形式多样、人民群众喜闻乐见的促消费活动。"]},{"w":"整合","f":16,"def":"（动词）通过整顿、协调重新组合。","egs":["要加强现有治理资源整合，从“九龙治水”转为“九牛爬坡”。"]},{"w":"标新立异","f":15,"def":"标：表明。异：独特，与众不同。原意为表明新颖的义理，提出与众不同的见解。后指故意提出新奇的见解，表示自己与众不同。中性词。（主观上故意性）","egs":["大舅母的话也不对，若是没有人标新立异，世界上哪还有进步？"]},{"w":"发现","f":15,"def":"（动词、名词）经过探索研究认识或找到前人没有认识或看到的事物或规律。","egs":["这一发现或将极大拓展科学家对量子领域的认知。"]},{"w":"更新","f":15,"def":"（动词、名词）旧的去了，新的来到。","egs":["一个个惠民项目、一幕幕生活场景，记录着城市更新行动的新进展。"]},{"w":"理解","f":15,"def":"（动词、名词）懂得，了解。","egs":["加深了对“人类命运共同体”的认识理解。"]},{"w":"立竿见影","f":15,"def":"在阳光下竖起竹竿，立刻就能看到它的影子。比喻收效迅速，见效很快。","egs":["掌握了正确的学习方法，便可收到立竿见影的效果。"]},{"w":"形成","f":15,"def":"（动词）通过发展变化而成为具有某种特点的事物，或者出现某种情形、局面。","egs":["面对复杂的国内外形势，我国需要形成全方位、多层次、宽领域的全面开放新格局。"]},{"w":"严谨","f":15,"def":"（形容词）严肃谨慎，细致周全。","egs":["严谨细致，是科学家基本的专业素养。"]},{"w":"因地制宜","f":15,"def":"根据各地的具体情况，制定适宜的办法。在句中作谓语、状语、定语。","egs":["吉林各地应因地制宜，探索适合的黑土地保护模式。"]},{"w":"制约","f":15,"def":"（动词）一事物的存在、变化是另一事物存在、变化的先决条件，则前者制约后者。","egs":["如果解决得好，突破瓶颈制约，就会实现质的飞跃，推动经济社会发展。"]},{"w":"水乳交融","f":15,"def":"像水和乳汁那样融合在一起，比喻关系非常融洽或结合得很紧密。含褒义，作谓语、定语。","egs":["在古希腊的神话里，诗歌诞生在酒神的狂欢之中，与音乐和舞蹈水乳交融，共同铸就文化的辉煌。"]},{"w":"保障","f":14,"def":"1．（动词）保护（生命、财产、权利等），使不受侵犯和破坏。2．（名词）起保障作用的事物。3．（动词）确保，保证做到。","egs":["政府加强了社会治安的维护，以保障人民的生命和财产安全。"]},{"w":"标准","f":14,"def":"1．（名词）衡量事物的准则。2．（形容词）本身合于准则的，可供同类事物比较核对的。","egs":["6 月 1 日起，一批新的国家标准开始实施。"]},{"w":"不期而遇","f":14,"def":"事先没有约定而意外地相逢。","egs":["生命像什么？像落叶、像浮云、像谜语……生命就是一场不期而遇。"]},{"w":"举步维艰","f":14,"def":"迈步行走十分困难。形容已陷入十分艰难的处境。多用于表示处境艰难。同“举步艰难”“步履维艰”“步履艰难”。","egs":["那时的国网巴西控股公司，可谓四顾茫然，举步维艰。"]},{"w":"差异","f":14,"def":"（名词）差别，不相同的地方。","egs":["差异让世界精彩，尊重让我们团结。"]},{"w":"持续","f":14,"def":"（动词）无间隔，连续不断。","egs":["2024 年，社会治安形势持续保持平稳。"]},{"w":"独一无二","f":14,"def":"指没有相同的或没有可以相比的，形容唯一的、难得的、十分稀少。","egs":["中国共产党的治理模式独一无二，有着长远的发展规划、高效的执行能力以及为民服务的政府机构。"]},{"w":"干扰","f":14,"def":"（动词、名词）扰乱，打扰。","egs":["中方一贯反对美方泛化国家安全概念，干扰和限制正常经贸往来。"]},{"w":"规范","f":14,"def":"1．（动词）使合乎规范。2．（名词）标准，准则。3．（形容词）符合规范的。","egs":["规范网络电商广告用语。"]},{"w":"局限","f":14,"def":"（动词、名词）限制在某个范围内。","egs":["保护生物多样性不能简单局限在物种层面。"]},{"w":"普遍","f":14,"def":"（形容词、副词）存在的面很广泛，具有共同性的。","egs":["着力解决人民群众普遍关心关注的民生问题。"]},{"w":"认可","f":14,"def":"1．（动词）许可，同意。2．（名词）认为好，觉得不错。","egs":["经过多次沟通和协商，双方终于达成了彼此认可的协议。"]},{"w":"深刻","f":14,"def":"（形容词）指透彻、深入。","egs":["要深刻领会、准确把握实现中华民族伟大复兴的中国梦。"]},{"w":"适应","f":14,"def":"（动词）符合客观条件或需要。","egs":["适应新常态、把握新常态、引领新常态。"]},{"w":"释放","f":14,"def":"1．（动词）恢复被拘押者或服刑者的人身自由。2．（动词）散放，放出。","egs":["中央政治局会议，释放三个有力信号。"]},{"w":"依赖","f":14,"def":"（动词）依靠别人或事物而不能自立或自给。","egs":["这种技术进步的取得，依赖于市场的扩大和由此带来的学习曲线与成本分摊效应。"]},{"w":"同舟共济","f":13,"def":"大家同坐一条船过河。比喻在困境中同心协力，共同克服困难。一般作谓语、定语，含褒义。","egs":["面对共同挑战，世界需要同球共济、守望相助。"]},{"w":"各有千秋","f":13,"def":"各有各的存在的价值。比喻各人有各人的长处，各人有各人的特色。褒义词。","egs":["国家电网公司三千多支服务队千姿百态，各有千秋。"]},{"w":"关键","f":13,"def":"（形容词）比喻事物重要的部分，对情况起重要作用的因素。","egs":["当前正值迎峰度夏关键期，多地持续高温。"]},{"w":"关注","f":13,"def":"（动词）关心重视。","egs":["近来，“首发经济”成为热词，无论是在概念层面还是在实践层面，都备受关注。"]},{"w":"缓解","f":13,"def":"（动词）使丧失锋芒，有所减轻，变缓和。","egs":["有效缓解民营企业融资难、融资贵问题。"]},{"w":"激励","f":13,"def":"（动词）激发鼓励。","egs":["历史还告诉我们，“比铁还硬，比钢还强”的团结之力，激励中国人民攻克一道又一道难关、创造一个又一个奇迹。"]},{"w":"交相辉映","f":13,"def":"各种亮光、色彩等相互照耀、映射。多用于形容美好的景象。作谓语、定语，褒义词。","egs":["日落时分，余晖与丹霞交相辉映。"]},{"w":"借鉴","f":13,"def":"（动词）指把别的人或事当镜子，对照自己，以便吸取经验或教训。","egs":["中国式现代化为广大发展中国家自主探索符合自身国情的现代化道路提供了借鉴。"]},{"w":"历史","f":13,"def":"（名词）过去的事实。","egs":["历史事实证明，战争只会带来灾难和痛苦，和平才是人类真正的追求。"]},{"w":"灵活","f":13,"def":"1．（形容词）敏捷，不呆板。2．（形容词）不拘泥而善于变通。","egs":["他头脑灵活，总是能迅速找到解决问题的办法。"]},{"w":"趋势","f":13,"def":"（名词）事物或局势发展的动向。","egs":["随着科技的快速发展，人工智能已成为未来技术发展的主要趋势。"]},{"w":"如出一辙","f":13,"def":"辙：车辙。好像出自同一车辙。比喻两种事物非常相似。作谓语、定语。（或两种以上事物）","egs":["细看不难发现，各家平台上的爆火视频都如出一辙，并无太多创新。"]},{"w":"深入","f":13,"def":"1．（动词）透过外部，达到事物内部或中心。2．（形容词）深刻、透彻。","egs":["坚持从实际出发，前提是深入实际、了解实际。"]},{"w":"渗透","f":13,"def":"1．（动词）液体、气体从细小的缝隙中透过。2．（动词）比喻一种事物或势力逐渐进入另一种事物或势力（多用于抽象事物）。","egs":["雨水逐渐渗透进了干燥的土壤，为植物的生长提供了必要的水分。"]},{"w":"特殊","f":13,"def":"（形容词）不同于一般。","egs":["铁路部门通过“爱心卡”、“服务站”、“小黄帽”等举措竭尽全力满足特殊旅客的刚性需求。"]},{"w":"一以贯之","f":13,"def":"贯：贯穿。贯通事情的始末或全部的过程。含褒义。","egs":["坚持和发展中国特色社会主义要一以贯之。"]},{"w":"一枝独秀","f":13,"def":"其他花都没有开放，只有这一枝在开着。比喻人或事物超群出众，特别优异。","egs":["票房冠军进入十亿时代，商业大片依然一枝独秀。"]},{"w":"抑制","f":13,"def":"（动词）压下去，控制。","egs":["一种基因突变可抑制肿瘤恶化进程。"]},{"w":"增加","f":13,"def":"（动词）在原有的基础上加多。","egs":["2024 年全年，我国人民币贷款增加 18.09 万亿元。"]},{"w":"主动","f":13,"def":"（形容词）不待外力推动而行动。跟“被动”相对。","egs":["统筹各种资源，调动各方力量，主动发出正面声音，形成网上舆论工作一盘棋。"]},{"w":"筚路蓝缕","f":12,"def":"筚路：柴车；蓝缕：又旧又破的衣服。意思是驾着柴车穿着破旧衣服去开辟山林。现用来形容创业的艰难与辛苦。也作“荜路蓝缕”。（词义有拓展，也可形容事情发展的初期阶段）","egs":["随着“洋机器”的进入，才出现了第一代荜路蓝缕的企业家，他们推动着中国进入现代文明的序列。"]},{"w":"出现","f":12,"def":"1．（动词）显露出来。2．（动词）产生出来。","egs":["比赛前半小时运动员已经出现在运动场上了。"]},{"w":"大有可为","f":12,"def":"指很有发展前途、极有希望，值得去做。（多形容未来）","egs":["在全面建设社会主义现代化国家新征程中，职业教育前途广阔、大有可为。"]},{"w":"方向","f":12,"def":"（名词）指东、西、南、北四个方位。形容预定的位置、路径。","egs":["始终坚持正确的政治方向。"]},{"w":"弘扬","f":12,"def":"（动词）大力宣扬，发扬光大。","egs":["弘扬伟大的民族精神。"]},{"w":"互动","f":12,"def":"（动词、名词）彼此联系，相互影响。","egs":["未来将推出更多形式的网络活动，鼓励公众广泛参与，增强社会互动。"]},{"w":"接踵而至","f":12,"def":"指人们前脚跟着后脚，接连不断地来，形容人接连而来或事情持续发生。作谓语、定语。","egs":["春节和“新春走基层”等报道接踵而至。"]},{"w":"决定","f":12,"def":"1．（动词）对怎样行动做出主张。2．（动词）起主导作用。3．（名词）已经确定的事项。","egs":["国家卫健委决定将新型冠状病毒感染的肺炎纳入法定传染病乙类管理。"]},{"w":"了解","f":12,"def":"1．（动词）明白、理解，知道得清楚。2．（动词）调查，打听，弄清楚。","egs":["我国人口数据到底如何统计？这些知识点要了解。"]},{"w":"排斥","f":12,"def":"（动词）排挤驳斥，使离开或使不让进入。","egs":["不得采取歧视性或非便利性措施排斥现金支付。"]},{"w":"如履薄冰","f":12,"def":"好像踩在薄冰上。比喻随时都会发生危险，做事极为小心谨慎。","egs":["领导者要有“如履薄冰，如临深渊”的自觉。"]},{"w":"弱化","f":12,"def":"（动词）使某种事物变弱，减轻程度。","egs":["我国民营经济只能壮大、不能弱化。"]},{"w":"深入人心","f":12,"def":"指理论、学说、政策等为人们深切了解和信服。作谓语、宾语，含褒义。（侧重受到拥护）","egs":["各国政府和国际组织积极响应，充分说明“一带一路”倡议对世界稳定和发展的重要意义已深入人心。"]},{"w":"随心所欲","f":12,"def":"泛指任凭自己的意愿，想要怎样就怎样。中性词。","egs":["在熟人关系的保护下，个人的行为更加显得无所顾忌，随心所欲。"]},{"w":"吸引","f":12,"def":"（动词）把别的（物体、力量或别人的注意力等）引到自己这方面来。","egs":["石林景区深秋美景吸引游人。"]},{"w":"与众不同","f":12,"def":"与其他的人或事物不一样。","egs":["从北京到西安的旅途对我来说是一次与众不同的经历。"]},{"w":"追求","f":12,"def":"（动词）用积极的行动来争取达到某种目的。","egs":["中国共产党人追求的是人民和国家之公利、人类和天下之大利。"]},{"w":"别具一格","f":11,"def":"格：风格。另有一种与众不同的风格。同“独具一格”、“别有一格”。作谓语、定语。（侧重风格独特）","egs":["打造别具一格的中新关系有着广阔的潜力与前景。"]},{"w":"不可替代","f":11,"def":"不能被其他人或其他事物取代。作谓语、定语。","egs":["哲学社会科学具有不可替代的重要地位。"]},{"w":"颠覆","f":11,"def":"1．（动词）物体颠倒，翻倒。2．（动词）推翻，摧毁。3．（动词）改变事物原有的模样。属于一种极端行为，对某项事物造成强烈冲击改变，使事物本质发生变化。","egs":["巨浪袭来，这艘小船顷刻间颠覆了。"]},{"w":"发扬","f":11,"def":"（动词）发展、提倡、宣扬。（多形容优良作风、传统、精神等）","egs":["教育引导全党大力发扬红色传统、传承红色基因。"]},{"w":"风起云涌","f":11,"def":"大风起来，乌云涌现。形容气势雄伟。形容雄浑磅礴之势。也比喻事物迅速发展，声势浩大。作谓语、定语，含褒义，指天气或事物的发展。","egs":["恍然间，风起云涌，阳光突然消逝，整个天空被浓云遮蔽。"]},{"w":"改善","f":11,"def":"（动词）改变原有情况使好一些。","egs":["中国人口稠密地区的空气质量已经显著改善。"]},{"w":"感悟","f":11,"def":"（动词、名词）人们对特定事物或经历所产生的感想与体会。","egs":["在党史学习教育中进一步感悟思想伟力。"]},{"w":"贯穿","f":11,"def":"（动词）穿过，连通。","egs":["这条隧道贯穿了整个山脉，可见工程的浩大与艰辛。"]},{"w":"规律","f":11,"def":"1．（名词）事物之间的内在的本质联系，法则。2．（形容词）合乎规律的。","egs":["彩票开奖有规律可循吗？"]},{"w":"好高骛远","f":11,"def":"指不切实际地去追求过高过远、难以实现的目标。含贬义。","egs":["须知，梦想也要量体裁衣，审视好自己再来谈。不考虑可操作性，那就是好高骛远。"]},{"w":"核心","f":11,"def":"（名词、形容词）中心，主要部分。","egs":["用户思维是互联网思维的基石与核心。"]},{"w":"厚积薄发","f":11,"def":"多多积蓄，慢慢放出。形容只有准备充分才能办好事情。","egs":["基础学科的人才培养应注重厚积薄发。"]},{"w":"获得","f":11,"def":"（动词）取得，得到（多用于抽象事物）。","egs":["中国队获得本次比赛的第四名。"]},{"w":"积极","f":11,"def":"（形容词）肯定的，正面的，有利于发展的（跟“消极”相对）。","egs":["中国采取积极的政策来应对气候变化。"]},{"w":"继承","f":11,"def":"1．（动词）依法承受死者的遗产或权利等。2．（动词）泛指把前人的作风、文化、知识等接受过来。3．（动词）后人继续做前人遗留下来的事业。","egs":["在孙辈继承上，很多人存在误区，以为孙辈是直接法定继承人。"]},{"w":"结果","f":11,"def":"1．（动词）长出果实。2．（名词）人或事的最后结局。","egs":["经过辛勤的耕耘，果树终于结果了。"]},{"w":"困难","f":11,"def":"1．（形容词）事情复杂，阻碍多。2．（形容词）穷困，不好过。3．（名词）前进中遇到的不易解决的问题或障碍。","egs":["当你决定出发的时候，最困难的那部分其实已经完成了。"]},{"w":"扩大","f":11,"def":"（动词）使（范围、规模等）比原来大。","egs":["全方位扩大国内需求。"]},{"w":"理性","f":11,"def":"（形容词、名词）指按照事物发展的规律和自然进化原则来考虑的态度，考虑问题、处理事情时不冲动，不凭感觉做事情（跟“感性”相对）。","egs":["最好的应援是喝彩而非拉踩，粉丝文化需回归理性。"]},{"w":"蔓延","f":11,"def":"（动词）如蔓草滋生，连绵不断。引申为延伸，扩展。","egs":["阻止加利福尼亚州山火进一步蔓延取得了一定进展。"]},{"w":"千篇一律","f":11,"def":"泛指事物只有一种形式，毫无变化。含贬义，作谓语、定语、状语。","egs":["千篇一律的反应，万众一致的声音，不由得引得人审慎思考。"]},{"w":"强调","f":11,"def":"（动词）特别着重或着重提出。","egs":["总书记强调，民族团结是我国各民族人民的生命线。"]},{"w":"趋之若鹜","f":11,"def":"像鸭子一样成群地跑过去，比喻很多人争相趋附、前往。含贬义。（现在有时非贬义）","egs":["年轻人在面对公务员这个“金饭碗”之时，到底是应该趋之若鹜，还是理性回归？"]},{"w":"升级","f":11,"def":"1．（动词）从较低的级别升到较高的级别。2．（动词）指战争规模扩大、事态的紧张程度加剧等。","egs":["以科技赋能产业优化升级。"]},{"w":"束手无策","f":11,"def":"手被绑住，无法解脱。形容遇到问题毫无解决的办法。","egs":["当危急情况出现时，有多少人并不是见义不为，而是束手无策？"]},{"w":"束之高阁","f":11,"def":"把东西捆起来，放在高高的架子上。指弃置不用或置之不理。比喻扔在一边，不用或不管。（多用来形容有价值、且暂时无用的事物）","egs":["材料的意义在于应用，不应在实验室被束之高阁。"]},{"w":"神秘","f":11,"def":"（形容词、名词）使人摸不透的，高深莫测的。","egs":["航拍云南彝族白倮人神秘“部落”——城寨。"]},{"w":"统一","f":11,"def":"（动词、形容词）部分联成整体，分歧归于一致。","egs":["坚定不移推进祖国统一大业。"]},{"w":"突出","f":11,"def":"1．（动词）鼓起来。2．（动词、形容词）超出一般。3．（动词）冲出。","egs":["山顶上突出的巨石，像一朵含苞待放的花朵。"]},{"w":"望洋兴叹","f":11,"def":"望洋：仰视的样子。1．指在伟大的事物面前感叹自己的渺小。2．比喻做事时因能力不够或条件缺乏而感到无可奈何。同“望洋而叹”。一般作谓语。（侧重自身的渺小或能力不足）","egs":["面对美丽而神秘的宇宙，人们只能望洋兴叹。"]},{"w":"随意","f":11,"def":"（形容词、名词）随着自己的意愿。","egs":["一些随意放生行为不仅给生态造成危害，也对他人生命财产构成威胁。"]},{"w":"相形见绌","f":11,"def":"形：对照，比较。绌：不够，不足。跟同类的人或同类事物相比较，显出很不足。","egs":["与中国的西进战略比起来，西澳大利亚州吸引东部诸州人口的努力相形见绌。"]},{"w":"协调","f":11,"def":"（动词、形容词）使搭配得适当，配合得当。","egs":["生产、生活、生态协调发展是满足人民美好生活需要的迫切要求。"]},{"w":"循规蹈矩","f":11,"def":"1．指遵守规矩。2．指拘泥于旧准则，不敢稍做变通。中性词。","egs":["打破潜规则，首先要营造循规蹈矩的良好环境。"]},{"w":"严格","f":11,"def":"（形容词）在遵守制度或掌握标准时认真不放松。","egs":["严格遵守党的纪律，是做合格共产党员的基本条件。"]},{"w":"一马当先","f":11,"def":"原指作战时策马冲锋在前。泛指领先、带头或起带头作用。含褒义。","egs":["多名奋战在救灾一线的将校，用立身为旗、一马当先的行动作出了响亮回答。"]},{"w":"直接","f":11,"def":"（形容词）不经过中间事物发生关系的（跟“间接”相对）。","egs":["发展速度超出预期，资本市场进入直接融资新时代。"]},{"w":"还原","f":10,"def":"（动词）使事物恢复到原状。","egs":["还原新闻真相。"]},{"w":"包罗万象","f":10,"def":"包：包括。罗：网罗。万象：各种景象。形容内容非常丰富，应有尽有，无所不包。作谓语、定语。","egs":["在不同历史阶段，城市不断兼收并蓄、包罗万象，促进人类文明的不断进步。"]},{"w":"避免","f":10,"def":"（动词）设法不使某种情形发生，防止。","egs":["简而言之，避免粮食危机的第一步是不让任何一个人掉队。"]},{"w":"避重就轻","f":10,"def":"回避重的责任，只拣轻的来承担。也指回避主要的问题，只谈无关重要的方面。","egs":["遇到困难挑战，是事不避难、知难而进，还是避重就轻、避而远之？"]},{"w":"博大精深","f":10,"def":"形容广博高深。多用于形容文化文明、理论、思想、艺术等。作谓语、定语，含褒义。","egs":["中华文明源远流长、博大精深，是我们具有高度文化自信的基础。"]},{"w":"具体","f":10,"def":"（形容词）很明确的、不抽象的、不笼统的（跟“抽象”相对）。","egs":["爱祖国和爱人民是有机统一的，爱人民是爱祖国的具体体现。"]},{"w":"超越","f":10,"def":"1．（动词）越过，跨过。2．（动词）超过，胜过。","egs":["越来越多的中资企业进入拉美，它们面临的挑战已不只是严格按照国际标准和当地法规去做事，而是要超越这些标准和法规，做到西方企业不曾做到的。"]},{"w":"冲击","f":10,"def":"1．（动词）（水流等）撞击物体。2．（动词）冲向敌人进行攻击、挑战。3．（动词）比喻大的触动或打击。","egs":["海浪冲击着岸边的礁石，发出震耳欲聋的声响。"]},{"w":"殚精竭虑","f":10,"def":"殚：尽，竭尽；精：精神，精力；竭：尽，竭尽；虑：思虑。意为用尽精力，费尽心思。在句中作谓语、状语，褒义词。","egs":["为青少年健康成长殚精竭虑。"]},{"w":"气势磅礴","f":10,"def":"气势：表现出的力量和态势；磅礴：广大无边的样子。形容气势雄伟壮大。作谓语、定语，含褒义。","egs":["极目远眺，五百里井冈层峦叠嶂，气势磅礴。"]},{"w":"发挥","f":10,"def":"1．（动词）使事物的内在能力充分表现出来。2．（动词）把意思或道理充分表达出来。","egs":["专家学者认为，中国在叙利亚问题上发挥了重要作用。"]},{"w":"纷至沓来","f":10,"def":"形容纷纷到来，连续不断地到来。用于指人或事物。作谓语、定语。","egs":["赣州市油菜花盛开，与赣派古建筑相互映衬，吸引游客纷至沓来。"]},{"w":"个性","f":10,"def":"（名词）人或事物的独特性质，使其与其他人或事物相区别。（跟“共性”相对）","egs":["现代社会，人们的自我意识不断增强，越来越重视个性发展，同时也越来越离不开别人的协同合作。"]},{"w":"合理","f":10,"def":"（形容词）合乎道理或事理。","egs":["金融行业门槛高、专业性强，高工资是合理的。"]},{"w":"后来居上","f":10,"def":"后来的人和事，进步很快，赶上或超过了先前的。在句中一般作谓语、定语。","egs":["中国志愿服务的历史虽然没有西方久远，其发展速度却有后来居上之势。"]},{"w":"价值","f":10,"def":"1．（名词）泛称物品的价格。2．（名词）正面、积极的作用。","egs":["2016 年，第三方移动支付的总商品价值比去年同期增长了 200%，达到 38 万亿元人民币。"]},{"w":"谨小慎微","f":10,"def":"原指以非常谨慎的态度对待细小问题，以免造成错误和损失。现也指对细小的事情过于小心，流于畏缩。中性词。","egs":["“千里之堤，以蝼蚁之穴溃；百尺之室，以突隙之烟焚”，这句话出自《韩非子·喻老》。其中所蕴含的谨小慎微、防微杜渐和防患于未然的道理，浅显易懂而影响深远。"]},{"w":"空中楼阁","f":10,"def":"指悬在半空中的阁楼。比喻虚幻的事物，或脱离实际的空想。在句中作主语、宾语。（名词词性）","egs":["如果任由特权和特例行走其中，严肃的规则便会成为假山和风景，成为俯瞰公众的空中楼阁，这远比违法建筑本身更可怕。"]},{"w":"力不从心","f":10,"def":"指心中想做某事而力量达不到或无力去做。在句中一般作谓语、宾语。","egs":["人到中年，会渐渐感觉力不从心，逐步进入身心健康失衡的“多事之秋”。"]},{"w":"琳琅满目","f":10,"def":"满眼都是美玉。形容各种美好的东西很多。褒义词。（现多用于搭配“商品、工艺品”）","egs":["春节临近，大胡同年货市场热闹起来，春节挂饰琳琅满目。"]},{"w":"鳞次栉比","f":10,"def":"像鱼鳞和梳子齿那样有次序地排列着，多用来形容房屋或船只等排列得很密很整齐。作谓语、定语。","egs":["赣深高铁列车往来疾驰，沿线乡村小洋房鳞次栉比，共同构成一幅冬日和美乡村画卷。"]},{"w":"满足","f":10,"def":"1．（动词）使得到满足、感到满意。2．（动词）满意，感到已经足够了。","egs":["流动的中国，努力满足不同旅客的出行需求。"]},{"w":"美轮美奂","f":10,"def":"形容房屋高大华美而众多。作谓语、定语。（现在词义有拓展）","egs":["民国时期，同宗海外侨胞返乡置产，遗留有多座保存完好的碉楼，融合中西、风格迥异、美轮美奂、声名远播。"]},{"w":"偶然","f":10,"def":"1．（形容词）事理上不一定要发生而发生的（跟“必然”相对）。2．（副词）不经常，偶尔。","egs":["成功并非偶然，每个光彩夺目的微笑背后，都隐藏着默默耕耘的身影。"]},{"w":"判断","f":10,"def":"（动词、名词）断定、裁定（是非曲直、吉凶善恶等）。","egs":["从信息内容、传播途径、受众人数、社会关注程度等方面综合判断，此案已经具备造成公共秩序严重混乱的特定后果。"]},{"w":"披荆斩棘","f":10,"def":"指拨开荆丛，砍掉荆棘。比喻在创业阶段清除障碍，艰苦奋斗。也泛指在前进道路上清除各种障碍，克服种种困难。","egs":["中国共产党通过奋斗，披荆斩棘，走过了万水千山。"]},{"w":"千姿百态","f":10,"def":"形容姿态多种多样。作谓语、定语。","egs":["通过城市领略新疆千姿百态的独特魅力，是国内外游客的共同期望。"]},{"w":"巧妙","f":10,"def":"（形容词）指精巧美妙，超过寻常的。","egs":["山东枣庄将石榴元素与传统美食及艺术巧妙结合，推出红石榴“喜馍。"]},{"w":"前所未有","f":10,"def":"从来没有过的。从来没有过的。从来没有过的。作谓语、定语。","egs":["信息时代，个人信息权益面临前所未有的挑战，个人信息保护一次又一次成为人们关注的焦点。"]},{"w":"认同","f":10,"def":"（动词、名词）认可，赞同。","egs":["在当代，文化、历史、集体记忆是建构国家认同不可缺少的重要资源。"]},{"w":"生生不息","f":10,"def":"不断地生长、繁殖而不停止。","egs":["中华文化是一个绵延不断、生生不息的生命体。"]},{"w":"顺应","f":10,"def":"（动词）顺从适应。","egs":["顺应人民群众对高品质生活的新期待。"]},{"w":"提炼","f":10,"def":"1．（动词）用化学方法或物理方法从化合物或混合物中提取（所要的东西）。2．（动词）比喻对某种事物进行去粗取精、去伪存真的分析、概括。","egs":["我们可以从原油中提炼出多种化学物质。"]},{"w":"天马行空","f":10,"def":"指天马奔驰于天空。1．形容才华横溢，气势豪放，不受约束。2．也形容言论空泛，不着边际。在句中一般作谓语、定语。","egs":["15 岁的少年殷宇恒专心致志地学习着如何捏出饺子的形状，其他孩子们也发挥天马行空的想象力。"]},{"w":"微不足道","f":10,"def":"指意义、价值等小得不值得一提。作谓语、定语。","egs":["有人认为这点税收减免微不足道，但从中可以见微知著。"]},{"w":"蔚然成风","f":10,"def":"事物盛极一时，成为一种良好的风气。褒义词，作谓语。","egs":["让尊崇军人在全社会蔚然成风，还需要我们持续发力，久久为功。"]},{"w":"显露","f":10,"def":"（动词）原来看不见的变成看得见，现出。","egs":["当越来越多的未成年人参与其中时，游戏背后潜藏的“虚荣攀比”和“过度消费”的问题也逐渐显露。"]},{"w":"削足适履","f":10,"def":"指因为鞋小脚大，把脚削去一块来凑合鞋的大小。比喻不合理地迁就凑合或不顾具体条件，生搬硬套。含贬义。","egs":["倘若作者如此牺牲了抒写的自由，即使极小部分，也无异于削足适履。"]},{"w":"心驰神往","f":10,"def":"心神奔向所向往的事物。形容一心向往。（主语是人）","egs":["购物天堂、美食之都、不夜之城，令人心驰神往的现代都市生活图景大抵如此。"]},{"w":"心旷神怡","f":10,"def":"心境开阔，精神愉快。（主语是人，有时可省略）","egs":["春风从赛汗塔拉草原吹向远方的楼宇，行走草原步道间，心旷神怡。"]},{"w":"演绎","f":10,"def":"1．（动词）经过引申发挥后进行展现、表现。2．（动词）一种由一般的知识、原理推导出特殊或个别的结论的逻辑推理方法(跟“归纳”相对)。","egs":["中华优秀传统文化的深厚积淀，用“体育”这门世界通用语言演绎和诠释，正在绽放出愈来愈迷人的魅力。"]},{"w":"眼花缭乱","f":10,"def":"缭乱：纷乱。眼睛看见复杂纷繁的东西而感到迷乱，比喻事物复杂，无法辨清。（主语是人）","egs":["随着气温下降，这些保暖“高科技”概念让人眼花缭乱。"]},{"w":"一如既往","f":10,"def":"指态度或做法没有任何变化，还是像从前一样。作褒义，多搭配“未来”。","egs":["今年全国两会期间，“科技创新”一如既往成为代表委员们热议的关键词之一。"]},{"w":"应用","f":10,"def":"（动词、名词）使用，运用。","egs":["在科学研究中，应用新技术可以提高实验效率和数据准确性。"]},{"w":"优势","f":10,"def":"（名词）能超过对方的有利形势。","egs":["中国具有独特的政治优势、显著的制度优势，能够跨地区、跨部门、跨行业进行顶层设计。"]},{"w":"与日俱增","f":10,"def":"指随着时间的推移而不断增长。作谓语、定语。","egs":["国际社会对中华文化的关注与日俱增，期待中华文化对人类文明发展进步发挥更大作用。"]},{"w":"安全","f":9,"def":"（名词、形容词）没有危险。","egs":["安全与发展犹如车之两轮、鸟之两翼，任何一方面有明显短板，都会影响国家富强、社会安定。"]},{"w":"把握","f":9,"def":"1．（动词）掌握，抓住。2．（名词）成功的可靠性（多用在“有”或“没”后面）。","egs":["我国具备持续健康发展的有利条件，我们牢牢把握着我国发展主动权。"]},{"w":"本质","f":9,"def":"（名词）指事物本身所固有的，决定事物性质、面貌和发展的根本属性。","egs":["现代化的本质是人的现代化。"]},{"w":"波澜壮阔","f":9,"def":"江河湖海等水势雄伟辽阔。形容气势宏伟，规模浩大。作谓语、定语，多用于运动、艺术、历史等。","egs":["展开共和国波澜壮阔的画卷，处处闪耀着英雄模范的风采。"]},{"w":"成就","f":9,"def":"1．（动词）完成（多指事业）。2．（名词）某种事业上的成绩。","egs":["在真刀真枪的实干中成就一番事业。"]},{"w":"成熟","f":9,"def":"（动词、名词、形容词）生长或发展到完善的程度或阶段。","egs":["时代在变，对体育的认知同样在变，奥运健儿们的心态更加成熟稳重、从容自信。"]}]};